export const recipes: CountryRecipe[] = [{"country":"vn","id":"pho-bo","slug":"pho-bo","title":{"zh-TW":"北越河內經典生滾牛肉河粉","en":"Hanoi Classic Beef Phở (Phở Bò Tái Nạm)","vi":"Phở Bò Tái Nạm Hà Nội","ja":"ハノイ伝統の牛肉フォー（フォー・ボー）","ko":"하노이 정통 소고기 쌀국수 (퍼보)"},"subtitle":{"zh-TW":"炭烤生薑八角草果高湯・薄切生牛肉與柔韌米粉","en":"Charred Spiced Bone Broth with Rare Sirloin & Rice Noodles","vi":"Nước dùng ninh xương thơm gừng nướng, hoa hồi, thảo quả","ja":"焼き生姜と八角香る牛骨スープと極薄切りレア牛肉","ko":"구운 생강과 팔각으로 우려낸 맑은 소뼈 육수와 부드러운 소고기"},"tagline":{"zh-TW":"越南國寶級美食靈魂，清澈甘甜的琥珀骨湯與鮮嫩生牛肉的極致交融","en":"The ultimate soul of Vietnamese gastronomy—a pristine, aromatic beef elixir","vi":"Tinh hoa ẩm thực Việt Nam, nước dùng thanh trong thơm lừng góc phố","ja":"ベトナムが世界に誇る国民食。澄んだ琥珀色の極上牛骨スープ","ko":"베트남을 대표하는 미식의 정수, 맑고 깊은 감칠맛의 소고기 쌀국수"},"heroImage":"/images/vn/pho-bo.jpg","difficulty":"medium","prepTimeMinutes":30,"cookTimeMinutes":60,"defaultServings":4,"caloriesPerServing":480,"category":"mains","dietaryTags":["classic","halal"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"北部・河內與南定省 (Nam Định)","en":"Northern Vietnam / Hanoi & Nam Dinh","vi":"Miền Bắc / Hà Nội & Nam Định","ja":"北部・ハノイおよびナムディン省","ko":"베트남 북부 / 하노이 및 남딘성"},"famousStreetMarkets":[{"zh-TW":"河內老城區 (Phở Gia Truyền Bát Đàn)","en":"Bat Dan Traditional Pho (Hanoi Old Quarter)","vi":"Phở Gia Truyền Bát Đàn","ja":"ハノイ旧市街 バットダン通り","ko":"하노이 밧단 전통 쌀국수"},{"zh-TW":"同春市場周邊 (Chợ Đồng Xuân)","en":"Dong Xuan Market Alleys","vi":"Khu ẩm thực Chợ Đồng Xuân","ja":"ドンスアン市場周辺","ko":"동쑤언 시장 골목"}],"historyStory":{"zh-TW":"Phở 誕生於 20 世紀初的北越紅河三角洲，受到法國殖民燉牛肉 (Pot-au-feu) 與廣東粉麵技法的雙重啟發。正宗北越河內派講究「湯清澈見底、鮮甜純粹」，不加過多豆芽或甜麵醬，僅撒上一把青翠細蔥與薄荷葉，擠上一瓣新鮮青檸。","en":"Born in the early 20th century in northern Vietnam, Phở evolved as a marriage of French beef stewing techniques (pot-au-feu) and southern Chinese flat rice noodles. True Hanoi-style Phở celebrates a crystal-clear, subtly spiced broth adorned simply with scallions, fresh herbs, and lime.","vi":"Phở ra đời vào đầu thế kỷ 20 tại vùng đồng bằng sông Hồng. Phở Hà Nội nguyên bản nổi tiếng với nước dùng trong vắt, thanh ngọt tự nhiên từ xương bò hầm cùng gừng, hành nướng xém, không dùng rau giá hay tương ngọt như miền Nam.","ja":"20世紀初頭、フランス領インドシナ時代に誕生。フランスのポトフ文化と中国の米麺文化が融合して生まれました。ハノイ流は余計な甘みを加えず、牛骨の純粋な旨味とスパイスの香りをストレートに味わいます。","ko":"20세기 초 프랑스의 비프 스튜(포토푀)와 중국의 쌀국수 문화가 융합되어 탄생했습니다. 하노이 정통 스타일은 숙주나 단 소스 대신 오직 맑고 깊은 육수와 파, 라임만을 곁들여 본연의 맛을 즐깁니다."},"vietScript":"Phở Bò Tái Nạm","vietPhonetics":"Fuh Baw Tie Nahm","audioPronunciationText":"Cho tôi một tô phở bò tái nạm nhiều hành không lấy giá!"},"ingredients":[{"id":"beef-bones","name":{"zh-TW":"新鮮牛大骨 / 牛筒骨 (帶骨髓)","en":"Beef Marrow Bones","vi":"Xương ống bò (có tủy)","ja":"牛骨（骨髄付き）","ko":"소 사골 / 우족"},"amount":1000,"unitMetric":"g","unitUS":"2.2 lb","isKeyFlavor":true,"vietName":"Xương ống bò","vietPronunciation":"Seu-ong Ong Baw"},{"id":"beef-flank","name":{"zh-TW":"牛腩或牛腱肉塊 (燉湯用)","en":"Beef Flank or Shank (For simmering)","vi":"Nạm bò / Bắp bò","ja":"牛バラ肉または牛スネ肉","ko":"양지머리 또는 소 사태"},"amount":400,"unitMetric":"g","unitUS":"14 oz","vietName":"Nạm bò","vietPronunciation":"Nahm Baw"},{"id":"beef-sirloin","name":{"zh-TW":"頂級沙朗生牛肉薄片 (滾湯燙熟)","en":"Thinly Sliced Raw Beef Sirloin / Tenderloin","vi":"Thịt thăn bò tươi thái mỏng (Tái)","ja":"極薄切り牛サーロイン生肉（レア用）","ko":"차돌박이 또는 얇게 썬 소 안심 (샤브샤브용)"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"vietName":"Thịt bò tái","vietPronunciation":"Teet Baw Tie"},{"id":"pho-noodles","name":{"zh-TW":"新鮮越式扁河粉 (Bánh Phở)","en":"Fresh or Dry Flat Rice Pho Noodles","vi":"Bánh phở tươi (hoặc phở khô)","ja":"フォー用ライスヌードル（平麺）","ko":"포(Pho) 쌀국수 납작면"},"amount":500,"unitMetric":"g","unitUS":"1.1 lb","isKeyFlavor":true,"vietName":"Bánh phở","vietPronunciation":"Bahn Fuh"},{"id":"charred-ginger","name":{"zh-TW":"老薑塊 (直火炭烤至外皮微焦拍碎)","en":"Fresh Ginger (Charred over open flame)","vi":"Gừng già (nướng cháy vỏ đập dập)","ja":"生姜（直火で皮を焦がしたもの）","ko":"생강 (직화로 껍질을 태워 으깬 것)"},"amount":60,"unitMetric":"g","unitUS":"2 oz","isKeyFlavor":true,"vietName":"Gừng nướng","vietPronunciation":"Geung Neu-ong"},{"id":"charred-shallots","name":{"zh-TW":"紫紅蔥頭 (帶皮直火烤香)","en":"Purple Shallots (Charred & peeled)","vi":"Hành tím củ (nướng thơm bóc vỏ)","ja":"紫エシャロット（直火焼き）","ko":"샬롯 / 적양파 (직화로 구운 것)"},"amount":5,"unitMetric":"piece","unitUS":"piece","vietName":"Hành tím nướng","vietPronunciation":"Hahn Teem"},{"id":"pho-spice-kit","name":{"zh-TW":"香料包：八角 3 顆、草果 1 顆、肉桂棒 1 支、小茴香與芫荽籽","en":"Pho Spice Blend: Star Anise, Black Cardamom, Cinnamon Stick, Coriander Seeds","vi":"Gói gia vị phở: Hoa hồi, thảo quả, quế, tiểu hồi, hạt mùi","ja":"スパイスセット：八角3個、ブラックカルダモン1個、シナモンスティック1本、コリアンダーシード","ko":"스파이스 믹스: 팔각 3개, 초과 1개, 시나몬스틱 1개, 코리앤더 씨드"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Gia vị phở (Hồi, quế, thảo quả)","vietPronunciation":"Zia Vee Fuh","substitute":{"substituteName":{"zh-TW":"市售「越式牛肉河粉香料茶包」","en":"Ready-made Pho Spice Pouch","vi":"Túi lọc gia vị phở nấu sẵn","ja":"市販のフォー用スパイスティーバッグ","ko":"시판 쌀국수 육수용 스파이스 티백"},"ratio":"1:1","explanation":{"zh-TW":"草果與八角需乾鍋乾炒 2 分鐘激發精油香氣，放入滷包袋中燉煮","en":"Toast whole spices in a dry pan for 2 mins to awaken oils before bagging.","vi":"Rang thơm các loại gia vị khô trên chảo trước khi cho vào túi lọc.","ja":"スパイスを油をひかずに乾煎りして香りを引き出してから煮込みます。","ko":"마른 팬에 향신료를 2분간 덖어 오일 향을 깨운 뒤 티백에 넣어 끓이세요."},"whereToBuy":{"zh-TW":"東南亞超市、Amazon 或全聯香料專區","en":"Asian supermarkets or Amazon","vi":"Chợ truyền thống hoặc tiệm thuốc bắc","ja":"アジア食材店や輸入食品店","ko":"아시안 마트 또는 온라인"}}},{"id":"fish-sauce","name":{"zh-TW":"富國島特級原液魚露 (40°N)","en":"Phú Quốc Pure Fish Sauce (40°N)","vi":"Nước mắm truyền thống Phú Quốc (40 độ đạm)","ja":"フーコック島産 プレミアム魚醤（ヌクマム 40°N）","ko":"푸꾸옥 프리미엄 피시소스 (40°N)"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"vietName":"Nước mắm Phú Quốc","vietPronunciation":"Neu-oc Mahm Foo Kwok"},{"id":"rock-sugar","name":{"zh-TW":"黃冰糖 (使湯頭圓潤清甜)","en":"Yellow Rock Sugar","vi":"Đường phèn vàng","ja":"黄氷砂糖","ko":"노란 얼음설탕"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","vietName":"Đường phèn","vietPronunciation":"Deu-ong Fen"},{"id":"fresh-herbs","name":{"zh-TW":"新鮮配菜：刺芹 (Ngò gai)、九層塔 (Húng quế)、青蔥絲、紅蔥頭與新鮮青檸角","en":"Garnish Herbs: Culantro (Sawtooth herb), Thai basil, thin scallions, and lime wedges","vi":"Rau thơm ăn kèm: Ngò gai, húng quế, hành hoa chẻ, chanh tươi","ja":"トッピングハーブ：ノコギリコリアンダー（オオバコエンドロ）、バジル、青ネギ、生ライム","ko":"고명 허브: 쿨란트로(톱니바질), 타이바질, 실파채, 생 라임 조각"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Rau ngò gai, húng quế, chanh ớt","vietPronunciation":"Rao Naw Guy"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"牛骨焯水洗淨與直火烤香生薑香料","en":"Blanch Beef Bones & Flame-Char Aromatics","vi":"Chần sạch xương bò & nướng thơm gừng hành","ja":"牛骨の血抜き下茹でと生姜・スパイスの直火焼き","ko":"소뼈 핏물 제거 초벌 데치기 및 향신 채소 직화 굽기"},"instruction":{"zh-TW":"將牛大骨冷水下鍋，大火煮沸滾 5 分鐘煮出深色浮沫血水，撈出後用溫水徹底沖洗乾淨。同時將生薑塊與紅蔥頭放在瓦斯爐明火上烤 4-5 分鐘至表皮微焦黑，剝除外層焦黑外皮並用刀背拍破。八角、肉桂棒與草果用乾鍋微火乾焙 2 分鐘至飄出濃郁辛香。","en":"Place beef marrow bones in cold water, boil vigorously for 5 mins to purge impurities. Drain and rinse thoroughly with warm water. Char ginger and shallots directly over open flame until fragrant and skins blacken slightly; scrape charred skin and crush lightly. Toast spices in a dry skillet for 2 mins until fragrant.","vi":"Cho xương bò vào nồi nước lạnh, đun sôi bùng 5 phút để thải bỏ hết bọt bẩn và máu đọng. Vớt ra rửa thật sạch dưới vòi nước ấm. Nướng gừng già và hành tím trực tiếp trên lửa đến khi cháy xém thơm lừng, cạo bớt vỏ đen rồi đập dập. Rang thơm hoa hồi, quế, thảo quả trên chảo khô.","ja":"牛骨を水から強火にかけ、沸騰後5分間グラグラ煮てアクと余分な血を抜きます。取り出してぬるま湯で綺麗に洗います。生姜とエシャロットを直火で皮が焦げるまで4〜5分焼き、黒い皮を削ぎ落として包丁の背で叩きます。八角やシナモンは油をひかずに乾煎りします。","ko":"찬물에 소 사골을 넣고 5분간 강하게 끓여 불순물을 배출한 뒤 미온수로 깨끗이 헹궈냅니다. 생강과 샬롯은 가스레인지 직화로 겉이 까맣게 탈 때까지 구운 뒤 탄 껍질을 긁어내고 칼등으로 으깹니다. 팔각, 시나몬, 초과는 마른 팬에 2분간 덖어 향을 냅니다."},"durationSeconds":300,"image":"/images/vn/pho-bo-step1.jpg","crucialTips":{"zh-TW":"第一鍋焯骨水必須徹底倒掉並洗淨骨頭縫隙的血塊，這是河內牛肉粉湯色清亮透明、毫無腥味的關鍵！","en":"Discard the blanching water completely and scrub bones. This is the sacred secret to crystal-clear broth.","vi":"Bắt buộc phải đổ bỏ nước chần đầu và rửa sạch từng kẽ xương. Đây là bí quyết sống còn để nước phở trong vắt.","ja":"最初の下茹で汁は完全に捨て、骨の隙間の血糊まで丁寧に洗い流してください。澄んだスープの絶対条件です。","ko":"첫 번째 데친 물은 반드시 버리고 뼈 사이사이 핏덩이를 솔로 씻어내세요. 맑은 육수의 핵심 비법입니다."}},{"stepNumber":2,"title":{"zh-TW":"微沸清燉琥珀高湯","en":"Gently Simmer the Golden Elixir Broth","vi":"Ninh nước dùng lửa nhỏ riu riu","ja":"弱火でじっくり煮出す極上牛骨スープ","ko":"약불에서 은근히 끓여내는 황금빛 소고기 육수"},"instruction":{"zh-TW":"在大湯鍋中注入 3.5 公升清水，放入焯淨的牛骨、牛腩塊、拍碎烤薑、烤蔥與裝入棉布包的辛香料包。大火煮沸後立刻轉最小火，保持湯面「菊花心」微滾冒小泡狀態。燉煮 1 小時後先撈出熟透軟嫩的牛腩塊切薄片備用，牛骨繼續慢火熬煮 2 小時。全程勿蓋死鍋蓋，隨時撇去浮油浮沫。","en":"Add 3.5L fresh water into a stockpot with bones, beef flank, charred aromatics, and spice pouch. Bring to a gentle boil, then immediately drop heat to the lowest setting for a gentle ripple simmer. After 1 hour, remove flank to slice thinly. Keep simmering bones for another 2 hours, skimming surface regularly. Never boil vigorously.","vi":"Cho 3.5 lít nước sạch vào nồi lớn cùng xương bò, nạm bò, gừng hành nướng và túi vải gia vị phở. Đun sôi rồi hạ lửa thật nhỏ để nước chỉ sôi lăn tăn mắt cua. Sau 1 giờ, vớt miếng nạm bò chín mềm ra để nguội thái lát, tiếp tục ninh xương thêm 2 giờ. Tuyệt đối không đậy kín vung và thường xuyên vớt bọt.","ja":"大鍋に水3.5Lを注ぎ、牛骨、牛バラ肉、焼き生姜、焼きエシャロット、スパイス袋を入れます。沸騰したらすぐに極弱火に落とし、表面がフツフツと波打つ程度の火加減を保ちます。1時間後に牛バラ肉を取り出して薄切り用に冷まします。骨はさらに2時間じっくり煮出します。フタは密閉せず、アクと油をこまめにすくい取ります。","ko":"큰 냄비에 물 3.5L를 붓고 사골, 양지머리, 구운 채소, 스파이스 백을 넣습니다. 끓어오르면 즉시 가장 약한 불로 줄여 표면이 잔잔하게 끓도록 유지합니다. 1시간 뒤 양지머리를 건져 얇게 썰어두고, 뼈는 2시간 더 은근히 우려냅니다. 뚜껑을 꽉 닫지 말고 떠오르는 거품과 기름을 수시로 걷어내세요."},"durationSeconds":3600,"image":"/images/vn/pho-bo-step2.jpg","dangerWarnings":{"zh-TW":"切忌大火滾湯！大火劇烈翻滾會使骨髓油脂乳化，整鍋湯會變成混濁乳白色而失去鮮甜清香。","en":"Never boil violently! Vigorous boiling emulsifies bone fats, making the broth cloudy and murky.","vi":"Không đun lửa to! Nước dùng sẽ bị đục ngầu do mỡ tủy bị nhũ hóa, mất đi độ thanh ngọt tinh tế.","ja":"強火で沸騰させ続けるのは厳禁！白濁してハノイ伝統の透き通るスープが台無しになります。","ko":"절대 센 불로 팔팔 끓이지 마세요! 골수가 유화되어 국물이 뿌옇게 탁해집니다."},"cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"High Pressure: 45 mins + Natural Release 20 mins","instructionOverride":{"zh-TW":"【電子壓力鍋極速版】：將牛骨、牛腩、生薑、紅蔥頭與香料放入內膽，加水 2.5 公升。密封閥門，設定「High Pressure (高壓)」45 分鐘。結束後自然洩壓 20 分鐘開蓋，湯頭濃郁度媲美熬煮 6 小時！撈出牛腩切片，開 Sauté 模式加冰糖與魚露調味。","en":"【Instant Pot Turbo Method】: Add blanched bones, flank, charred aromatics, and spice bag with 2.5L water into the inner pot. Cook on High Pressure for 45 mins, then Natural Release for 20 mins. Broth reaches 6-hour depth in under an hour! Remove flank to slice, switch to Sauté mode to season with fish sauce and rock sugar.","vi":"【Nồi áp suất điện siêu tốc】: Cho xương, nạm, gừng hành và gói gia vị vào lòng nồi cùng 2.5L nước. Chọn chế độ High Pressure trong 45 phút, sau đó xả van tự nhiên 20 phút. Vớt nạm bò thái lát, bật chế độ Sauté nêm nước mắm và đường phèn.","ja":"【電気圧力鍋時短モード】：内釜に牛骨、肉、焼き野菜、スパイスと水2.5Lを入れ、高圧45分にセット。自然減圧20分でフタを開ければ、6時間煮込んだような濃厚スープが完成！Sautéモードにして魚醤と氷砂糖で調味します。","ko":"【인스턴트팟 고속 모드】: 내솥에 뼈, 고기, 구운 채소, 스파이스백과 물 2.5L를 넣고 고압 45분 조리 후 자연 감압 20분 진행합니다. 양지를 건져 썰고, Sauté 모드로 전환해 피시소스와 얼음설탕으로 간을 맞춥니다."}}]},{"stepNumber":3,"title":{"zh-TW":"過濾金湯、黃金魚露調味與燙煮米粉","en":"Strain Broth, Season with Fish Sauce & Prep Noodles","vi":"Lọc trong nước dùng, nêm nước mắm & chần bánh phở","ja":"スープの濾過、ヌクマムでの味付けと麺の湯通し","ko":"육수 거르기, 피시소스 조미 및 면 삶기"},"instruction":{"zh-TW":"用細濾網將牛骨與香料殘渣濾出，得到清澈金黃的純淨高湯。加入黃冰糖與特級富國島魚露調味（鹽度需比平時喝湯略鹹一分，因為加入麵條與生肉後會被稀釋）。另起一鍋滾水，將新鮮扁河粉放入漏勺燙 15-20 秒至熱透柔軟，甩乾水分盛入預熱過的大碗中。","en":"Strain the broth through a fine-mesh sieve to collect pristine golden liquid. Season with rock sugar and premium Phu Quoc fish sauce (taste should be slightly saltier than usual, as noodles and fresh herbs will dilute it). In a separate pot of boiling water, blanch fresh pho noodles for 15-20 secs, shake dry, and transfer into pre-warmed serving bowls.","vi":"Dùng rây mắt nhỏ lọc sạch vụn xương và gia vị để thu được nồi nước dùng vàng óng trong vắt. Nêm đường phèn và nước mắm Phú Quốc loại ngon (vị đậm đà hơn bình thường một chút để khi chan vào phở và thịt tươi là vừa vặn). Nấu nồi nước sôi riêng, chần bánh phở tươi trong 15-20 giây cho mềm mướt, vẩy ráo nước rồi cho vào tô.","ja":"細目のザルで骨やスパイスを濾し、澄み切った黄金色のスープを取り出します。氷砂糖と高級フーコック島ヌクマムで味を調えます（麺や具が入るため、少し濃いめの塩加減がベスト）。別の鍋で湯を沸かし、フォー麺を15〜20秒サッと湯通しして湯切りし、温めておいた器に盛ります。","ko":"고운 체로 뼈와 향신료 찌꺼기를 걸러내어 맑은 황금빛 육수를 완성합니다. 얼음설탕과 푸꾸옥 피시소스로 간을 맞춥니다(면과 고기가 들어가므로 평소보다 살짝 짭짤해야 완벽합니다). 다른 냄비에 물을 끓여 쌀국수 면을 15~20초간 살짝 데친 뒤 물기를 털고 그릇에 담습니다."},"durationSeconds":180,"image":"/images/vn/pho-bo-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"鋪上熟牛腩與生牛肉片，滾湯直沖綻放鮮嫩","en":"Arrange Beef & Scald with Boiling Broth","vi":"Xếp nạm chín, thịt tái & chan nước dùng sôi sùng sục","ja":"牛肉の盛り付けと沸騰スープの注ぎ入れ","ko":"양지와 생 소고기 세팅 및 펄펄 끓는 육수 붓기"},"instruction":{"zh-TW":"在河粉上整齊碼上切片的熟牛腩與極薄切的生沙朗牛肉片，撒上大量的青蔥花、細切蔥白絲與新鮮刺芹碎。大火將調味高湯煮至大沸翻滾，用大湯勺舀起滾燙高湯，精準均勻淋在生牛肉薄片上！生牛肉在高溫熱湯瞬間燙至粉紅半熟，嫩滑多汁，隨即端上桌！","en":"Layer sliced cooked flank and paper-thin raw sirloin across the noodles. Scatter generously with sliced scallions, thin shallot ribbons, and chopped culantro. Bring the seasoned broth to a rolling boil. Ladle scalding broth directly over the raw beef slices; the searing heat cooks the beef instantly to a tender, juicy medium-rare. Serve immediately!","vi":"Xếp nạm bò chín thái mỏng và từng lát thịt bò tái thật mỏng lên trên mặt bánh phở. Rắc nhiều hành hoa thái nhỏ, đầu hành chẻ sợi và ngò gai cắt nhỏ. Đun nồi nước dùng sôi sùng sục, múc nước dùng sôi chan trực tiếp và đều tay lên khắp các lát thịt bò tái. Thịt tái gặp nước sôi sẽ chín hồng mềm mọng, tỏa hương thơm ngát!","ja":"麺の上に薄切りの煮込み牛バラ肉と、極薄切りの生サーロイン肉を並べます。たっぷりの刻み青ネギ、白髪ネギ、オオバコエンドロを散らします。スープをグラグラに沸騰させ、お玉で熱々のスープを生肉の上に直接回しかけます！熱気で生肉がほんのりピンク色のレアに火が通り、極上の柔らかさになります。","ko":"면 위에 썰어둔 삶은 양지와 종잇장처럼 얇게 썬 생 소고기를 펼쳐 올립니다. 쪽파와 채 썬 파, 쿨란트로를 듬뿍 얹습니다. 육수를 펄펄 끓여 국자로 생 소고기 위에 직접 골고루 부어줍니다! 뜨거운 열기로 고기가 즉시 연한 분홍빛 미디엄 레어로 익으며 최고의 부드러움을 선사합니다."},"durationSeconds":60,"image":"/images/vn/pho-bo-step4.jpg","dangerWarnings":{"zh-TW":"生牛肉必須在沖入高湯的「最後一刻」依然保持滾沸狀態，否則水溫不足無法瞬間鎖住肉汁，牛肉容易顯老變韌！","en":"The broth must be boiling vigorously when ladling, or the raw beef will not cook properly.","vi":"Nước dùng bắt buộc phải sôi sùng sục khi chan để thịt bò tái chín mềm tức thì.","ja":"注ぐ直前のスープは必ず沸騰状態にしてください！ぬるいと肉に火が通らず生臭さが残ります。","ko":"육수는 반드시 펄펄 끓는 상태에서 부어야 소고기가 질겨지지 않고 육즙을 가둔 채 익습니다."}}],"troubleshooting":[{"id":"pho-cloudy-broth","problem":{"zh-TW":"河粉湯頭混濁不透、呈乳白色且有微腥味","en":"Broth turned murky, cloudy, or lacks crystalline clarity","vi":"Nước dùng phở bị đục, ngả màu đục ngầu và có mùi nồng","ja":"スープが白く濁り、透明感がなくなってしまった","ko":"육수가 맑지 않고 탁하게 흐려졌어요"},"cause":{"zh-TW":"1. 第一遍焯水時間不夠或未徹底清洗骨頭縫隙；2. 熬湯時火開太大劇烈翻滾导致骨髓乳化；3. 熬湯時蓋緊了鍋蓋。","en":"1. Incomplete initial bone blanching; 2. Boiled too vigorously instead of a lazy ripple simmer; 3. Kept the pot tightly lidded.","vi":"1. Chưa chần sạch xương hoặc không rửa kỹ vụn máu; 2. Đun lửa quá to làm tủy mỡ nhũ hóa; 3. Đậy vung kín khi ninh.","ja":"1. 最初の下茹でが不十分だった。2. 強火でグラグラ沸騰させてしまった。3. フタを密閉して煮込んだ。","ko":"1. 초벌 삶기가 미흡했거나 2. 센 불로 끓여 유화되었거나 3. 뚜껑을 꼭 닫아두었기 때문입니다."},"solution":{"zh-TW":"熬骨時全程保持微沸（表面僅冒小泡），不蓋死鍋蓋。若已經濁了，可將 2 顆蛋白稍微打散倒入溫熱湯中微火煮 5 分鐘，蛋白會像磁鐵吸附雜質浮起，濾出即可恢復清亮。","en":"Maintain a lazy ripple simmer without tightly lidding. If already cloudy, whisk 2 egg whites into warm broth over low heat; they will coagulate and capture floating impurities.","vi":"Luôn ninh lửa nhỏ liu riu không đậy vung. Nếu nước lỡ bị đục, đánh tan 2 lòng trắng trứng cho vào nồi nước ấm đun nhỏ lửa, lòng trắng sẽ hút sạch cặn đục nổi lên trên.","ja":"常に弱火で表面が揺れる程度の火加減を保ち、フタはずらしておきます。濁ってしまったら卵白2個分を入れて弱火にかけると、アクを吸着して澄んだ状態に戻せます。","ko":"약불을 유지하며 뚜껑을 비스듬히 열어두세요. 이미 탁해졌다면 달걀흰자 2개를 풀어 약불에 넣으면 불순물을 흡착해 맑아집니다."}}],"proTips":[{"zh-TW":"河內在地老饕吃法：先喝兩口純粹的清甜金湯品嚐原味，再依喜好擠入新鮮青檸汁與兩圈生辣椒圈。北越派絕不在清甜牛肉湯中直接加入甜麵醬或辣椒醬，因為那會完全掩蓋熬製數小時的牛骨精華！","en":"Authentic Hanoi etiquette: Sip the pure broth first before squeezing fresh lime or adding fresh chili slices. Northern purists never squirt hoisin or sriracha directly into the bowl, as it masks the nuanced 10-hour bone craftsmanship!","vi":"Nghệ thuật ăn phở Hà Nội: Húp 1-2 thìa nước dùng nguyên bản để cảm nhận vị ngọt thanh của tủy xương, sau đó mới vắt chanh tươi và thả vài lát ớt hiểm. Người sành phở không cho tương ớt ngọt hay tương đen thẳng vào tô.","ja":"ハノイ流の通な食べ方：まずはライムや調味料を入れずにスープを一口すすり、牛骨本来の深みと甘みを堪能します。その後生ライムをひと絞りし、生の輪切り唐辛子を加えるのが王道スタイル！","ko":"하노이 현지인 꿀팁: 먼저 양념을 넣지 않고 국물 본연의 깊은 감칠맛을 두어 숟가락 음미하세요. 그 다음 라임을 살짝 짜 넣고 생고추를 띄워 먹는 것이 정통 방식입니다."}]},{"country":"vn","id":"banh-mi","slug":"banh-mi","title":{"zh-TW":"越式招牌脆皮炭烤肉法包","en":"Classic Saigon Crispy Pork Bánh Mì","vi":"Bánh Mì Thịt Nướng Sài Gòn","ja":"サイゴン名物 炭火焼き豚肉のバインミー","ko":"사이공 정통 크리스피 숯불 돼지고기 반미"},"subtitle":{"zh-TW":"雲朵薄脆空氣感外皮・秘製香茅蜜汁肉排與香濃豬肝醬","en":"Shatteringly Crispy Baguette with Lemongrass Pork & Rich Pâté","vi":"Vỏ bánh giòn rụm, thịt nướng sả thơm lừng, pate béo ngậy","ja":"極薄パリパリのバゲット・レモングラス豚肉と濃厚レバーパテ","ko":"바삭하게 부서지는 바게트와 불향 가득 레몬그라스 돼지고기, 고소한 파테"},"tagline":{"zh-TW":"全球最受讚譽的街頭三明治之王，法式優雅與越南市井煙火的完美結晶","en":"The undisputed King of Street Sandwiches—a symphony of crunch, richness, and herbal zing","vi":"Món bánh mì đường phố vươn tầm thế giới, giòn tan đậm đà ngập tràn hương vị","ja":"世界が愛する極上サンドイッチ。フレンチとアジアンハーブの究極のハーモニー","ko":"세계인이 사랑하는 최고의 길거리 샌드위치, 겉바속촉 바게트와 이국적인 허브의 조화"},"heroImage":"/images/vn/banh-mi.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":15,"defaultServings":2,"caloriesPerServing":520,"category":"rollsSnacks","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"南部・胡志明市 (西貢)","en":"Southern Vietnam / Ho Chi Minh City (Saigon)","vi":"Miền Nam / TP. Hồ Chí Minh (Sài Gòn)","ja":"南部・ホーチミン市（サイゴン）","ko":"베트남 남부 / 호찌민시 (사이공)"},"famousStreetMarkets":[{"zh-TW":"西貢第一郡 (Bánh Mì Huỳnh Hoa)","en":"Huynh Hoa Banh Mi (Saigon District 1)","vi":"Bánh Mì Huỳnh Hoa","ja":"サイゴン1区 フインホア","ko":"호찌민 1군 후인호아 반미"},{"zh-TW":"濱城市場周邊 (Chợ Bến Thành)","en":"Ben Thanh Market Food Carts","vi":"Khu ẩm thực Chợ Bến Thành","ja":"ベンタイン市場周辺","ko":"벤탄 시장 노점"}],"historyStory":{"zh-TW":"19 世紀中葉法國殖民者將長棍麵包 (Baguette) 引進越南。西貢麵包師傅聰慧地在麵糰中加入適量米粉，降低筋度，烘焙出外皮如紙薄脆、內部空心蓬鬆無負擔的獨特「越式法包」。包入濃醇豬肝醬、蜜汁香茅烤肉、酸甜醃白蘿蔔絲 (Đồ chua) 與一把新鮮香菜，成就世界街頭奇蹟。","en":"Introduced by the French in the mid-19th century, the classic baguette was reinvented by Vietnamese bakers who blended rice flour with wheat flour, yielding an ultra-thin, crackling crust with an airy, feather-light crumb. Stuffed with savory pork liver pâté, grilled lemongrass pork, pickled daikon & carrots, and spicy bird’s eye chili.","vi":"Bánh mì du nhập vào Việt Nam từ thời Pháp thuộc. Người Sài Gòn đã sáng tạo pha thêm bột gạo vào bột mì để tạo nên ổ bánh có vỏ mỏng giòn tan như sương mai, ruột mềm xốp, kết hợp cùng pate gan béo ngậy, thịt nướng thơm lừng và đồ chua giải ngấy tuyệt hảo.","ja":"フランス統治時代に持ち込まれたバゲットを、米粉をブレンドすることで外皮は薄氷のようにパリパリ、中はふんわり軽やかに進化させました。レバーパテとレモングラス香る焼肉、甘酸っぱいなますが絶妙に絡み合います。","ko":"19세기 프랑스 바게트가 베트남에 들어온 후, 현지 제빵사들이 쌀가루를 섞어 껍질은 얇고 바삭하며 속은 공기처럼 가벼운 베트남식 바게트를 완성했습니다. 고소한 간 파테와 달콤짭조름한 숯불 돼지고기가 일품입니다."},"vietScript":"Bánh Mì Thịt Nướng","vietPhonetics":"Bahn Mee Teet Neu-ong","audioPronunciationText":"Cho tôi hai ổ bánh mì thịt nướng đầy đủ, nhiều ớt cay!"},"ingredients":[{"id":"banh-mi-baguette","name":{"zh-TW":"越式脆皮空氣感小法包 (外脆內蓬鬆)","en":"Vietnamese Light Crust Baguettes","vi":"Ổ bánh mì Việt Nam giòn xốp","ja":"ベトナム式バゲット（皮が薄くパリパリのもの）","ko":"베트남식 바삭한 바게트 (쌀가루 함유)"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Bánh mì","vietPronunciation":"Bahn Mee"},{"id":"pork-shoulder","name":{"zh-TW":"豬梅花肉或五花肉薄片 (肉質柔嫩帶油花)","en":"Pork Shoulder or Belly (Thinly sliced)","vi":"Thịt nạc vai heo thái mỏng","ja":"豚肩ロースまたは豚バラ肉薄切り","ko":"돼지 목살 또는 삼겹살 (얇게 썬 것)"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"vietName":"Thịt heo nướng","vietPronunciation":"Teet Heo Neu-ong"},{"id":"lemongrass-minced","name":{"zh-TW":"新鮮香茅 (細末)","en":"Fresh Lemongrass (Finely minced)","vi":"Sả tươi băm nhuyễn","ja":"生レモングラス（みじん切り）","ko":"다진 생 레몬그라스"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"vietName":"Sả băm","vietPronunciation":"Sah Bahm"},{"id":"pork-liver-pate","name":{"zh-TW":"越式奶油豬肝醬 (抹在麵包內壁的靈魂香氣)","en":"Vietnamese Pork Liver Pâté","vi":"Pate gan heo truyền thống","ja":"ベトナム風豚レバーパテ","ko":"베트남식 돼지 간 파테"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"vietName":"Pate gan","vietPronunciation":"Pah-Teh Gahn","substitute":{"substituteName":{"zh-TW":"法式罐裝豬肝醬或法式鴨肝肉醬","en":"Canned French pork/duck pâté","vi":"Pate hộp Pháp hoặc pate gà","ja":"市販のフレンチレバーペースト","ko":"시판 캔 파테 또는 오리간 스프레드"},"ratio":"1:1","explanation":{"zh-TW":"進烤箱前先將肝醬均勻塗在麵包底層，受熱融化後肉香濃郁滲透麵包體","en":"Spread generously on the warm sliced bread so it melts slightly into the crumb.","vi":"Phết đều vào lòng bánh mì ấm để pate tan chảy thấm đượm ruột bánh.","ja":"温めたバゲットの内側にたっぷり塗ることで、コクがパン全体に染み渡ります。","ko":"따뜻한 빵 안쪽에 넉넉히 발라 촉촉한 풍미를 극대화하세요."},"whereToBuy":{"zh-TW":"大型超市進口食品區、東南亞雜貨店","en":"Gourmet market or Asian grocer","vi":"Siêu thị hoặc tiệm bánh mì","ja":"輸入食品店やカルディ","ko":"수입 식료품점 또는 백화점 식품관"}}},{"id":"do-chua-pickles","name":{"zh-TW":"越式醃白蘿蔔與紅蘿蔔絲 (Đồ chua 酸甜爽脆解膩)","en":"Pickled Daikon & Carrots (Đồ Chua)","vi":"Đồ chua củ cải & cà rốt","ja":"大根と人参のベトナム風甘酢なます（ド・チュア）","ko":"새콤달콤한 무 당근 피클 (도추아)"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"vietName":"Đồ chua","vietPronunciation":"Doh Chu-ah"},{"id":"vietnamese-mayo","name":{"zh-TW":"越式蛋黃美乃滋醬 (Bơ 濃郁綿滑)","en":"Vietnamese Egg Yolk Butter/Mayo (Bơ Bánh Mì)","vi":"Sốt bơ trứng gà đánh tay","ja":"ベトナム風エッグマヨネーズ","ko":"베트남식 달걀 마요네즈 버터 스프레드"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","vietName":"Bơ trứng gà","vietPronunciation":"Baw Teu-ong"},{"id":"cucumber-cilantro","name":{"zh-TW":"小黃瓜長條切片、新鮮香菜葉、綠鳥眼辣椒圈","en":"Cucumber spears, fresh cilantro sprigs & sliced bird’s eye chili","vi":"Dưa leo thái lát, rau ngò rí, ớt hiểm","ja":"きゅうり薄切り、フレッシュパクチー、青唐辛子","ko":"오이 슬라이스, 생 고수, 청양고추"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Dưa leo, ngò rí, ớt","vietPronunciation":"Zeu-ah Leo, Naw Ree"},{"id":"marinade-sauce","name":{"zh-TW":"醃肉醬：魚露 1.5 匙、美極鮮味露 1 匙、蜜糖 1 匙、蠔油 1 匙、蒜蓉黑胡椒","en":"Marinade: Fish sauce, Maggi sauce, honey, oyster sauce, minced garlic & black pepper","vi":"Gia vị ướp thịt: Nước mắm, nước tương Maggi, mật ong, dầu hào, tỏi tiêu","ja":"漬けダレ：ヌクマム、マギー醤油、蜂蜜、オイスターソース、ニンニク、黒胡椒","ko":"고기 양념: 피시소스 1.5큰술, 매기 간장, 꿀, 굴소스, 다진 마늘, 후추"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Gia vị ướp thịt nướng","vietPronunciation":"Zia Vee Eup Teet"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"香茅蜜汁醃漬豬肉片","en":"Marinate Pork with Fragrant Lemongrass","vi":"Ướp thịt với sả băm mật ong","ja":"レモングラスと特製ダレで豚肉を漬け込む","ko":"레몬그라스 특제 양념에 돼지고기 재우기"},"instruction":{"zh-TW":"將梅花肉切成 0.5 公分薄片。加入細香茅末、大蒜碎、魚露、美極鮮味露、蜂蜜、蠔油與黑胡椒碎，用手抓勻按摩 2 分鐘，靜置醃製至少 20 分鐘入味。","en":"Slice pork shoulder into 0.5cm thin strips. Mix with minced lemongrass, garlic, fish sauce, Maggi seasoning, honey, oyster sauce, and freshly cracked black pepper. Massage for 2 mins and let rest for at least 20 mins.","vi":"Thái thịt nạc vai thành từng lát mỏng 0.5cm. Cho sả băm, tỏi, nước mắm, xì dầu Maggi, mật ong, dầu hào và hạt tiêu vào bóp đều tay trong 2 phút, ướp ít nhất 20 phút cho ngấm gia vị.","ja":"豚肩ロースを厚さ5mmにスライスします。みじん切りレモングラス、ニンニク、ヌクマム、マギー醤油、蜂蜜、オイスターソース、黒胡椒をもみ込み、20分以上漬け込みます。","ko":"돼지 목살을 0.5cm 두께로 얇게 썹니다. 다진 레몬그라스, 마늘, 피시소스, 매기간장, 꿀, 굴소스, 후추를 넣고 조물조물 버무려 20분간 재워둡니다."},"durationSeconds":120,"image":"/images/vn/banh-mi-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"煎烤蜜汁香茅豬肉至微焦金黃","en":"Sear Lemongrass Pork until Caramelized & Smoky","vi":"Áp chảo hoặc nướng thịt vàng thơm xém cạnh","ja":"豚肉を香ばしく香ばしく焼き上げる","ko":"불향 나게 돼지고기 노릇하게 굽기"},"instruction":{"zh-TW":"平底鍋倒入少許油大火燒熱，將醃好的豬肉片單層鋪開。大火每面各煎 2 分鐘，直到邊緣呈現蜜汁焦香金黃色（鑊氣滿滿），盛出備用。","en":"Heat 1 tbsp oil in a skillet over high heat. Lay pork slices in a single layer. Sear undisturbed for 2 mins per side until deeply caramelized with savory charred edges. Transfer to a plate.","vi":"Làm nóng chảo với chút dầu ăn trên lửa lớn, trải đều thịt đã ướp. Áp chảo mỗi mặt 2 phút đến khi thịt chín vàng ươm, xém cạnh thơm lừng mùi sả nướng.","ja":"フライパンに油を強火で熱し、豚肉を重ならないように広げます。両面を2分ずつ焼き、タレがキャラメリゼして香ばしい焦げ目がつくまで焼き上げます。","ko":"팬에 기름을 두르고 센 불에서 고기를 펼쳐 올립니다. 앞뒤로 2분씩 구워 양념이 노릇하게 눌어붙으며 불향이 가득 배도록 익혀냅니다."},"durationSeconds":240,"image":"/images/vn/banh-mi-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 190°C (375°F) for 8 mins","instructionOverride":{"zh-TW":"【氣炸鍋烤肉版】：氣炸鍋預熱 190°C，將豬肉片平鋪在炸籃內（避免重疊），烤 5 分鐘後翻面再烤 3 分鐘，逼出油脂邊緣酥脆！","en":"【Air Fryer Pork】: Preheat air fryer to 190°C (375°F). Spread pork slices flat in basket. Air fry for 5 mins, flip and fry 3 more mins until sizzling with crisp edges.","vi":"【Nồi chiên không dầu】: Làm nóng nồi ở 190°C. Xếp thịt vào khay nướng 5 phút, lật mặt nướng thêm 3 phút cho xém cạnh thơm nức.","ja":"【ノンフライヤー焼き豚】：190°Cに予熱し、重ならないように並べて5分、裏返して3分加熱。余分な脂が落ちてカリッとジューシーに！","ko":"【에어프라이어 구이】：190°C 예열 후 고기를 겹치지 않게 깔아 5분 조리, 뒤집어서 3분 더 구워 겉바속촉으로 완성합니다."}}]},{"stepNumber":3,"title":{"zh-TW":"烤熱法包並恢復極致酥脆外殼","en":"Warm Baguette to Shatteringly Crisp Crust","vi":"Nướng giòn rụm lại vỏ bánh mì","ja":"バゲットを温めてパリパリの極薄クラストを復活","ko":"바게트를 구워 극강의 바삭함 되살리기"},"instruction":{"zh-TW":"法包表面噴上一層薄薄細霧水。放入烤箱或氣炸鍋 180°C 烘烤 2-3 分鐘。出爐時輕捏麵包外皮，會發出像枯葉般清脆的碎裂聲，內部保持輕盈鬆軟！用麵包刀從中間橫向切開 3/4 深（切勿切斷）。","en":"Mist the baguette lightly with a sprinkle of water. Toast in an oven or air fryer at 180°C (350°F) for 2-3 mins until shatteringly crisp when gently tapped, while the inside remains soft and steamy. Slice horizontally 3/4 deep along the length.","vi":"Xịt một lớp nước sương mỏng lên vỏ bánh mì. Cho vào lò nướng hoặc nồi chiên không dầu ở 180°C trong 2-3 phút. Khi bóp nhẹ vỏ bánh sẽ nghe tiếng giòn rụm tan vỡ. Dùng dao xẻ dọc thân bánh sâu 3/4.","ja":"バゲットの表面に霧吹きで軽く水をかけます。トースターまたはノンフライヤー180°Cで2〜3分温めます。触るとパリッと音が鳴る極薄サクサクに！パン切り包丁で縦に切れ目を入れます。","ko":"바게트 겉면에 분무기로 물을 살짝 뿌립니다. 에어프라이어나 오븐 180°C에서 2~3분간 데우면 껍질이 낙엽처럼 바삭바삭해집니다. 옆면을 세로로 길게 갈라줍니다."},"durationSeconds":180,"image":"/images/vn/banh-mi-step3.jpg","crucialTips":{"zh-TW":"烘烤前噴薄水霧是越式法包「薄脆如紙」的終極絕技！水氣在熱風中瞬間蒸發會形成微小氣泡，使外皮極致酥鬆。","en":"Misting water before toasting is the secret to bakery-level crackling glass crust.","vi":"Bí quyết xịt sương nước trước khi nướng giúp vỏ bánh phồng giòn tan như ngoài tiệm.","ja":"焼く前の霧吹きが、紙のように薄くパリパリの食感を生み出す最大の秘訣です。","ko":"데우기 전 물을 살짝 뿌려주는 것이 빵집처럼 바삭한 껍질을 만드는 특급 비밀입니다."}},{"stepNumber":4,"title":{"zh-TW":"抹醬塗抹與黃金層次組裝","en":"Layer Pâté, Mayo, Grilled Pork & Pickles","vi":"Phết sốt pate, bơ trứng & kẹp đầy ắp nhân thịt","ja":"パテとマヨを塗り、肉・なます・ハーブを贅沢にサンド","ko":"파테 바르기, 고기와 피클, 허브 가득 채우기"},"instruction":{"zh-TW":"在麵包剖開的下層厚厚抹上一大匙越式豬肝醬，上層抹上濃郁蛋黃美乃滋。依次鋪上爽脆小黃瓜長片、堆疊滿滿的熱騰騰香茅烤肉片，接著塞入大量的醃酸甜紅白蘿蔔絲 (Đồ chua)。最後塞入新鮮香菜、幾圈生辣椒圈，淋上一小匙美極鮮醬油，輕輕合攏雙手壓緊，一口咬下喀擦脆響！","en":"Generously spread pork liver pâté along one side of the bread and egg butter mayo on the other. Lay down cucumber strips, stack high with warm caramelized lemongrass pork, followed by a thick layer of pickled daikon & carrots. Crown with fresh cilantro stems and sliced chilies. Press together and savor the legendary crunch!","vi":"Phết một lớp pate gan dày ở đáy bánh, mặt trên phết bơ trứng thơm béo. Đặt dưa leo thái mỏng, xếp đầy đặn thịt nướng nóng hổi, tiếp theo gắp nhiều đồ chua củ cải cà rốt. Cuối cùng thêm ngò rí, vài lát ớt hiểm và rưới vài giọt Maggi. Ép nhẹ ổ bánh và cắn một miếng giòn tan ngập tràn hương vị!","ja":"バゲットの下側にレバーパテをたっぷり、上側にエッグマヨを塗ります。きゅうり、焼きたての温かい豚肉、たっぷりの甘酢なます、パクチー、青唐辛子を挟みます。仕上げにマギー醤油を数滴たらし、手で軽くギュッと押さえて完成！","ko":"바게트 안쪽 한 면에 간 파테를 듬뿍 바르고, 반대편에 에그 버터 마요를 바릅니다. 오이, 따끈한 숯불 고기, 새콤달콤한 무 당근 피클을 넉넉히 채웁니다. 고수와 생고추를 얹고 매기간장 몇 방울을 뿌려 완성합니다!"},"durationSeconds":120,"image":"/images/vn/banh-mi-step4.jpg"}],"troubleshooting":[{"id":"banh-mi-soggy","problem":{"zh-TW":"法包放一下子外皮就受潮變軟變韌，咬不動","en":"Baguette crust turns rubbery, soggy, or tough to chew","vi":"Vỏ bánh mì nhanh bị ỉu, dai ngoách khó cắn","ja":"バゲットの皮が湿気てゴムのように硬くなってしまった","ko":"바게트가 금방 눅눅해지고 질겨져서 씹기 힘들어요"},"cause":{"zh-TW":"1. 醃酸甜紅白蘿蔔絲與小黃瓜未徹底瀝乾水分；2. 烘烤溫度不足未能烤乾表皮水氣。","en":"1. Pickles and cucumbers were too wet; 2. Baguette was under-toasted.","vi":"1. Đồ chua và dưa leo chưa vắt kiệt nước; 2. Nướng bánh chưa đủ độ nóng.","ja":"1. なますやきゅうりの水気をしっかり絞っていなかった。2. バゲットの焼きが甘かった。","ko":"1. 무 피클과 오이의 물기를 충분히 짜지 않았거나 2. 바게트를 덜 구웠기 때문입니다."},"solution":{"zh-TW":"醃蘿蔔絲夾入前務必用乾淨廚房紙巾用力擠乾多餘水分！鋪小黃瓜在底部可作為天然隔離層，阻隔水氣滲透至麵包皮。","en":"Squeeze pickled veggies firmly with paper towels before stuffing. Place cucumbers first as a protective moisture barrier.","vi":"Luôn vắt kiệt nước đồ chua bằng khăn sạch trước khi kẹp. Đặt dưa leo ở đáy để làm lớp ngăn nước ngấm vào vỏ bánh.","ja":"なますはキッチンペーパーで水分を限界まで絞ってください。きゅうりを敷いて水気ブロックの壁を作ります。","ko":"피클을 넣기 전 키친타월로 물기를 꽉 짜내세요. 오이를 먼저 깔면 수분이 빵으로 스며드는 것을 막아줍니다."}}],"proTips":[{"zh-TW":"正宗西貢吃法秘訣：越式法包的靈魂絕對是「豬肝醬」與「美極鮮露 (Maggi)」！缺少這兩樣就只是普通的歐式三明治。在組裝完成前沿著肉縫滴入 4-5 滴美極鮮露，鹹鮮味瞬間昇華！","en":"Saigon street tip: The true secret soul of Bánh Mì is pork liver pâté and a splash of Maggi liquid seasoning. Always drizzle a few drops of Maggi directly over the meat before closing!","vi":"Bí kíp bánh mì Sài Gòn: Linh hồn nằm ở pate béo ngậy và vài giọt nước tương Maggi. Rưới chút Maggi trực tiếp lên thớ thịt trước khi cắn để vị ngon bùng nổ!","ja":"本場サイゴンの極意：バインミーの魂は「レバーパテ」と「マギー醤油」にあります。具を挟んだ最後にマギー醤油をサッと垂らすことで、旨味の爆発が起こります！","ko":"사이공 현지인 팁: 반미의 진정한 영혼은 돼지 간 파테와 매기 간장입니다. 한 입 베어 물기 전 고기 위에 매기 간장을 몇 방울 떨어뜨려 보세요!"}]},{"country":"vn","id":"bun-cha","slug":"bun-cha","title":{"zh-TW":"河內炭烤豬肉米線 (奧巴馬同款)","en":"Hanoi Grilled Pork Vermicelli (Bún Chả Hà Nội)","vi":"Bún Chả Hà Nội Truyền Thống","ja":"ハノイ名物 炭火焼き豚肉のつけ米麺（ブン・チャー）","ko":"하노이 정통 숯불 돼지고기 비빔국수 (분짜)"},"subtitle":{"zh-TW":"炭火微焦香嫩肉丸・溫熱酸甜青木瓜魚露汁與鮮滑米線","en":"Charred Pork Patties & Belly in Warm Sweet-Sour Dipping Broth","vi":"Chả viên nướng than hoa thơm nức mũi, nước chấm đu đủ chua ngọt","ja":"炭火の焦げ目が香ばしい肉団子と温かい甘酢パパイヤダレ","ko":"숯불 향 가득한 고기 완자와 삼겹살, 따뜻한 파파야 피시소스 육수"},"tagline":{"zh-TW":"河內正午街巷最勾魂的炭火煙香，美國前總統奧巴馬訪越摯愛名品","en":"The irresistible smoky lunch ritual of Hanoi alleys—world-famous after Anthony Bourdain & Obama","vi":"Đệ nhất quà trưa chốn kinh kỳ, nức tiếng năm châu đượm nồng khói than","ja":"オバマ元大統領も絶賛したハノイ路地裏の至高のソウルフード","ko":"오바마 전 대통령도 반한 하노이 골목길의 전설적인 숯불 점심 메뉴"},"heroImage":"/images/vn/bun-cha.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":20,"defaultServings":2,"caloriesPerServing":560,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"北部・首都河內 (Hà Nội)","en":"Northern Vietnam / Hanoi","vi":"Miền Bắc / Thủ đô Hà Nội","ja":"北部・ハノイ首都圏","ko":"베트남 북부 / 수도 하노이"},"famousStreetMarkets":[{"zh-TW":"河內香蓮烤肉米線 (Bún Chả Hương Liên - 奧巴馬店)","en":"Bun Cha Huong Lien (Obama Restaurant)","vi":"Bún Chả Hương Liên","ja":"ハノイ フオンリエン（オバマ氏訪問店）","ko":"하노이 흐엉리엔 (오바마 분짜)"},{"zh-TW":"同春市場老巷 (Hàng Mành)","en":"Hang Manh Street Bun Cha","vi":"Bún Chả Hàng Mành","ja":"ハンマン通り","ko":"항만 거리 분짜"}],"historyStory":{"zh-TW":"Bún Chả 是河內最道地的傳統午餐文化。每到上午 11 點，老城區街邊就擺開小炭爐，油脂滴在炭火上滋滋作響，整條街巷飄滿焦糖肉香。2016 年名廚 Anthony Bourdain 與美國總統歐巴馬在河內藍色小塑膠凳上一同享用 Bún Chả 配冰啤酒，讓這道市井珍饈轟動全球。","en":"Bún Chả is Hanoi’s quintessential lunchtime heartbeat. Around 11 AM, sidewalks come alive with handheld bamboo grills, sending fragrant clouds of caramelized pork fat into the air. Catapulted to global fame when Anthony Bourdain treated President Barack Obama to a casual streetside bowl in 2016.","vi":"Bún chả là nét văn hóa ẩm thực trưa đặc trưng của người Tràng An xưa. Mùi khói nướng chả quạt nan thơm lừng khắp phố phường. Năm 2016, cố đầu bếp Anthony Bourdain cùng Tổng thống Mỹ Barack Obama đã ngồi ghế nhựa thưởng thức bún chả, đưa món ăn này lên bản đồ ẩm thực toàn cầu.","ja":"ハノイの昼の風物詩。昼時になると路地裏のあちこちでうちわを仰ぎながら炭火で肉を焼く煙が立ち込めます。2016年にオバマ元大統領とアンソニー・ボーディン氏がプラスチック椅子で食べたことで世界的名声を博しました。","ko":"하노이의 대표적인 점심 식사 문화입니다. 2016년 고(故) 앤서니 보 Bourdain 셰프와 버락 오바마 미국 대통령이 파란 플라스틱 의자에 앉아 분짜와 맥주를 즐기며 전 세계적으로 유명해졌습니다."},"vietScript":"Bún Chả Hà Nội","vietPhonetics":"Boon Chah Hah Noy","audioPronunciationText":"Cho tôi hai suất bún chả chả nướng lẫn, thêm nem rán!"},"ingredients":[{"id":"pork-mince","name":{"zh-TW":"肥三瘦七豬絞肉 (製作炭烤肉丸 Chả viên)","en":"Ground Pork (30% fat for juicy patties)","vi":"Thịt nạc vai xay có mỡ (làm chả viên)","ja":"豚ひき肉（脂身3割程度）","ko":"다진 돼지고기 (목살 또는 삼겹 부위)"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"vietName":"Thịt xay làm chả","vietPronunciation":"Teet Say Lahm Chah"},{"id":"pork-belly","name":{"zh-TW":"帶皮五花肉薄片 (製作烤肉片 Chả miếng)","en":"Pork Belly (Thin slices for Chả miếng)","vi":"Thịt ba chỉ thái mỏng (chả miếng)","ja":"豚バラ肉薄切り","ko":"삼겹살 (얇게 슬라이스한 것)"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"vietName":"Thịt ba chỉ nướng","vietPronunciation":"Teet Bah Chee"},{"id":"rice-vermicelli","name":{"zh-TW":"新鮮越式細米線 (Bún 軟滑清爽)","en":"Fresh or Dry Thin Rice Vermicelli (Bún)","vi":"Bún tươi sợi nhỏ","ja":"ベトナム細米麺（ブン）","ko":"가는 쌀국수 면 (분 면)"},"amount":350,"unitMetric":"g","unitUS":"12 oz","vietName":"Bún tươi","vietPronunciation":"Boon Teu-oy"},{"id":"caramel-sauce","name":{"zh-TW":"越式焦糖色糖汁 (Nước màu 靈魂上色與焦香)","en":"Vietnamese Caramel Cooking Sauce (Nước Màu)","vi":"Nước hàng / Nước màu kho thịt","ja":"キャラメルソース（ヌック・マウ）","ko":"베트남 캐러멜 쿠킹 소스 (늑마우)"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","isKeyFlavor":true,"vietName":"Nước màu","vietPronunciation":"Neu-oc Mow"},{"id":"green-papaya-carrot","name":{"zh-TW":"青木瓜片與紅蘿蔔花片 (泡在暖魚露汁裡爽脆解膩)","en":"Green Papaya & Carrot Flower Slices","vi":"Đu đủ xanh & cà rốt thái lát mỏng","ja":"青パパイヤと人参の薄切り","ko":"그린 파파야 및 당근 슬라이스"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":true,"vietName":"Đu đủ dưa góp","vietPronunciation":"Doo Doo Zeu-ah Gop"},{"id":"warm-dipping-sauce","name":{"zh-TW":"溫暖酸甜魚露水：溫水 250ml、魚露 3 大匙、白醋或檸檬汁 2.5 大匙、砂糖 3 大匙、細蒜末、朝天椒碎","en":"Warm Dipping Broth: 250ml warm water, 3 tbsp fish sauce, 2.5 tbsp rice vinegar/lime, 3 tbsp sugar, minced garlic & chili","vi":"Nước chấm ấm: Nước ấm, nước mắm, giấm, đường, tỏi ớt băm","ja":"温かい甘酢ヌクマムつゆ：ぬるま湯、ヌクマム、米酢、砂糖、刻みニンニク・唐辛子","ko":"따뜻한 디핑 육수: 미온수 250ml, 피시소스 3큰술, 식초, 설탕, 다진 마늘, 베트남 고추"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Nước chấm bún chả","vietPronunciation":"Neu-oc Chahm Boon Chah"},{"id":"fresh-herb-platter","name":{"zh-TW":"生菜盤：皺葉生菜、紫蘇葉 (Tía tô)、越南香薷薄荷 (Kinh giới)、香菜","en":"Fresh Herb Platter: Butter lettuce, Vietnamese perilla (Tía tô), Kinh giới balm, cilantro","vi":"Rau sống: Xà lách, tía tô, kinh giới, mùi ta","ja":"生野菜盛り合わせ：サニーレタス、紫蘇（エゴマ）、キンゾイ（香薷）、パクチー","ko":"생채소 플래터: 상추, 자소엽(베트남 깻잎), 킨조이 허브, 고수"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Rau tía tô, kinh giới","vietPronunciation":"Tee-ah Toh, Keen Zeu-oy"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"醃漬肉丸與五花肉片","en":"Season Patties & Pork Belly Slices","vi":"Ướp chả viên & chả miếng đậm đà","ja":"肉団子と豚バラ肉の下味つけ","ko":"고기 완자와 삼겹살 양념하기"},"instruction":{"zh-TW":"豬絞肉加入細紅蔥頭末、大蒜碎、魚露、焦糖色汁 (Nước màu)、蠔油、砂糖與黑胡椒，順同一方向攪拌至起膠質，捏成直徑 3 公分的扁圓肉丸。五花肉片同樣加入相同調料抓勻，兩者各醃漬 25 分鐘。","en":"Mix ground pork with minced shallots, garlic, fish sauce, caramel sauce (nước màu), oyster sauce, sugar, and black pepper. Stir vigorously in one direction until sticky; shape into small 3cm flat patties. Toss pork belly slices in the same marinade. Let both rest for 25 mins.","vi":"Trộn thịt băm với hành tỏi băm, nước mắm, nước màu, dầu hào, đường và hạt tiêu. Quết đều tay cho thịt dẻo dai rồi viên thành các miếng chả tròn dẹt cỡ 3cm. Thịt ba chỉ cũng ướp tương tự trong 25 phút.","ja":"豚ひき肉にエシャロット、ニンニク、ヌクマム、キャラメルソース、オイスターソース、砂糖、黒胡椒を加え、粘りが出るまでよく練ります。直径3cmの平たい団子に成形します。豚バラ肉も同様のタレで25分漬け込みます。","ko":"다진 돼지고기에 샬롯, 마늘, 피시소스, 늑마우(캐러멜소스), 굴소스, 설탕, 후추를 넣고 찰기가 생길 때까지 치댄 후 납작한 완자로 빚습니다. 삼겹살도 같은 양념에 25분간 재워둡니다."},"durationSeconds":180,"image":"/images/vn/bun-cha-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"炭烤或煎烤雙色烤肉","en":"Grill Patties & Pork to Smoky Perfection","vi":"Nướng chả vàng ruộm thơm nức mũi","ja":"香ばしい焦げ目がつくまで焼き上げる","ko":"숯불 향 나게 노릇노릇 굽기"},"instruction":{"zh-TW":"平底鍋放少許油燒熱，先放入肉丸微火煎至兩面金黃熟透，表面刷一層醃汁焦化起香；接著放入五花肉片大火快煎至肥肉邊緣微捲微焦。","en":"Heat a heavy skillet or grill pan. Sear patties over medium heat until cooked through and glossy with caramelized edges. Next, sear pork belly slices over high heat until the fat crisps and edges curl deliciously.","vi":"Làm nóng chảo với chút dầu, áp chảo chả viên trên lửa vừa đến khi chín vàng hai mặt và dậy mùi caramel. Tiếp tục nướng chả miếng ba chỉ trên lửa to cho mỡ xèo xèo và xém cạnh.","ja":"フライパンを熱し、肉団子を中火で両面こんがりと焼きます。タレを塗りながらキャラメリゼさせます。次に豚バラ肉を強火でカリッと焦げ目がつくまで焼きます。","ko":"팬에 기름을 두르고 완자를 올려 중불에서 속까지 익히며 표면을 노릇하게 굽습니다. 이어서 삼겹살을 센 불에서 겉면이 바삭하고 고소하게 구워냅니다."},"durationSeconds":300,"image":"/images/vn/bun-cha-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 195°C (385°F) for 10 mins","instructionOverride":{"zh-TW":"【氣炸鍋炭烤風】：炸籃鋪烘焙紙，肉丸與五花肉片分開放，195°C 烤 6 分鐘，翻面再烤 4 分鐘至焦香四溢，多餘油脂完全被濾出！","en":"【Air Fryer Method】: Line basket with parchment. Air fry patties & belly at 195°C (385°F) for 6 mins, flip and fry 4 more mins until sizzling with crisp charred edges.","vi":"【Nồi chiên không dầu】: Xếp chả vào nồi ở 195°C trong 6 phút, lật mặt nướng thêm 4 phút cho xém vàng thơm lừng.","ja":"【ノンフライヤー】：195°Cで6分加熱し、裏返してさらに4分。余分な脂が落ちて炭火焼きのような香ばしさに！","ko":"【에어프라이어】：195°C에서 6분 조리 후 뒤집어 4분 더 굽습니다. 기름은 쏙 빠지고 불맛 가득 노릇해집니다."}}]},{"stepNumber":3,"title":{"zh-TW":"調製溫熱酸甜青木瓜魚露汁","en":"Prepare Warm Sweet-Sour Papaya Dipping Broth","vi":"Pha nước chấm bún chả ấm nóng với đu đủ dưa góp","ja":"温かい青パパイヤ入り甘酢ヌクマムつゆ作り","ko":"따뜻한 파파야 피시소스 국물 만들기"},"instruction":{"zh-TW":"在小湯鍋中將溫水 250ml、魚露 3 大匙、糖 3 大匙、白醋 2.5 大匙微熱混勻融化。將切薄片的青木瓜與胡蘿蔔放入微酸的溫熱魚露湯中浸泡，加入現切蒜末與紅辣椒碎。","en":"Warm 250ml water, 3 tbsp fish sauce, 3 tbsp sugar, and 2.5 tbsp vinegar in a saucepan until dissolved. Pour into small bowls, add thinly sliced green papaya and carrots, finishing with fresh minced garlic and bird’s eye chilies.","vi":"Đun ấm 250ml nước cùng 3 thìa mắm, 3 thìa đường, 2.5 thìa giấm cho tan đều. Múc ra bát, thả lát đu đủ xanh và cà rốt ngâm giòn vào, rắc thêm tỏi ớt băm.","ja":"小鍋にぬるま湯250ml、ヌクマム大さじ3、砂糖大さじ3、酢大さじ2.5を入れて温め溶かします。小鉢に注ぎ、薄切りの青パパイヤと人参、ニンニク、唐辛子を加えます。","ko":"작은 냄비에 미온수 250ml, 피시소스 3큰술, 설탕 3큰술, 식초 2.5큰술을 넣고 미온으로 데워 녹입니다. 그릇에 붓고 얇게 썬 파파야와 당근, 다진 마늘, 고추를 띄웁니다."},"durationSeconds":120,"image":"/images/vn/bun-cha-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"烤肉浸入暖汁，搭配米線與紫蘇生菜享用","en":"Immerse Grilled Pork into Warm Broth & Serve","vi":"Thả thịt nướng vào bát nước chấm, dọn kèm bún và rau sống","ja":"熱々の肉をつゆに浸し、麺とハーブを添えて完成","ko":"따뜻한 육수에 구운 고기를 퐁당 담가 면과 쌈 싸먹기"},"instruction":{"zh-TW":"將熱騰騰的烤肉丸與烤五花肉直接夾入盛著溫熱酸甜汁的碗中！旁邊附上雪白細米線一大盤，以及紫蘇、香薷、生菜葉與炸春捲。用筷子夾一小口米線、一片紫蘇葉，浸入肉汁中一同送入口中，肉香、酸甜與香草清香在口中迸發！","en":"Plunge the sizzling grilled patties and pork belly straight into the warm sweet-sour broth bowl! Serve with a platter of fresh cold rice vermicelli, Vietnamese perilla (tía tô), and crispy spring rolls. Dip noodles and herbs into the savory broth with a slice of meat for the ultimate bite!","vi":"Gắp ngay chả viên và chả miếng nóng hổi thả ngập vào bát nước chấm chua ngọt ấm! Dọn cùng đĩa bún tươi trắng tinh và đĩa rau sống ngập tràn tía tô, kinh giới. Gắp miếng bún cùng lá tía tô chấm đẫm vào bát chả, cắn một miếng là cảm nhận trọn vẹn phong vị Hà Thành!","ja":"焼きたてアツアツの肉団子と豚バラ肉を、温かい甘酢つゆの小鉢にドボンと投入します！別皿に盛った白い米麺ブンと、紫蘇やレタスを添えて完成。麺とハーブをつゆに浸し、お肉と一緒に口いっぱいに頬張ります！","ko":"갓 구워 지글지글한 고기 완자와 삼겹살을 따뜻한 새콤달콤 육수 볼에 풍덩 담급니다! 접시에 담은 차가운 쌀국수 면과 깻잎(자소엽), 상추를 곁들입니다. 면과 채소를 육수에 푹 적셔 고기와 함께 싸 먹으면 최고의 감동을 줍니다!"},"durationSeconds":60,"image":"/images/vn/bun-cha-step4.jpg"}],"troubleshooting":[{"id":"bun-cha-dry-patties","problem":{"zh-TW":"肉丸口感乾柴、硬邦邦缺乏肉汁","en":"Pork patties turned dry, dense, and tough","vi":"Chả viên bị khô xác, cứng đơ không có độ béo ngậy","ja":"肉団子がパサパサで硬くなってしまった","ko":"고기 완자가 퍽퍽하고 육즙 없이 딱딱해요"},"cause":{"zh-TW":"使用的絞肉太瘦（純瘦肉缺乏油脂），或煎烤時間過久水分流失。","en":"Used too lean pork without enough fat, or overcooked.","vi":"Dùng thịt nạc quá nạc không có mỡ, hoặc nướng quá lửa.","ja":"赤身肉ばかりで脂身が足りなかったか、焼きすぎ。","ko":"기름기 없는 살코기만 썼거나 너무 오래 구웠기 때문입니다."},"solution":{"zh-TW":"必須選用 30% 肥肉的梅花肉或五花肉絞肉，攪拌時順同一方向打入少許焦糖水與油，煎至表面焦黃即可，不可過度烘烤。","en":"Ensure at least 30% fat ratio in the pork mince. Whip vigorously with marinade to retain moisture.","vi":"Nhất định phải chọn thịt vai có 30% mỡ, quết thịt dẻo với nước hàng để giữ độ mọng nước.","ja":"脂身が30%ほど混ざった豚ひき肉を使い、粘りが出るまでよく練ることでジューシーに仕上がります。","ko":"반드시 지방이 30% 정도 섞인 고기를 사용하고, 끈기가 날 때까지 잘 치대어 육즙을 가두세요."}}],"proTips":[{"zh-TW":"河內傳統必備靈魂香草：吃 Bún Chả 絕對不能沒有「紫蘇葉 (Tía tô)」與「香薷 (Kinh giới)」！紫蘇微澀帶辛香的芳香烴，能奇蹟般解去五花肉與肉丸的炭烤油脂感，讓整頓午餐無比清爽！","en":"Crucial culinary pairing: Bún Chả must be eaten with Vietnamese perilla (Tía tô) and Kinh giới balm! Their citrus-peppery notes cut right through the rich pork fat with breathtaking freshness.","vi":"Rau thơm linh hồn: Ăn bún chả nhất định phải có rau tía tô và kinh giới! Hương thơm thanh mát của hai loại thảo mộc này giúp cân bằng vị béo của thịt nướng một cách kỳ diệu.","ja":"必須のハーブ：ブンチャーには「紫蘇（ティア・トー）」と「キンゾイ（香薷）」が欠かせません！独特の爽快な香りが豚肉の脂っこさを完全にリセットしてくれます。","ko":"필수 허브 팁: 분짜를 먹을 때는 베트남 자소엽(깻잎)과 킨조이 허브가 필수입니다! 상큼한 허브 향이 고기의 기름진 맛을 완벽하게 잡아줍니다."}]},{"country":"vn","id":"goi-cuon","slug":"goi-cuon","title":{"zh-TW":"越式鮮蝦豬肉水晶生春捲","en":"Vietnamese Fresh Summer Rolls (Gỏi Cuốn)","vi":"Gỏi Cuốn Tôm Thịt Sài Gòn","ja":"エビと豚肉の生春巻き（ゴイ・クオン）","ko":"월남쌈 / 새우 돼지고기 생 스프링롤 (고이꾸온)"},"subtitle":{"zh-TW":"透光米紙裹鮮甜海蝦・五花肉薄片與濃郁花生海鮮蘸醬","en":"Translucent Rice Paper with Prawns, Pork Belly & Peanut Hoisin Dip","vi":"Bánh tráng dẻo dai cuốn tôm tươi đỏ au, chấm tương đậu phộng béo bùi","ja":"透き通るライスペーパーに浮かぶ鮮やかなエビと濃厚ピーナッツダレ","ko":"투명한 라이스페이퍼 속 붉은 새우와 수육, 고소한 땅콩 해선장 소스"},"tagline":{"zh-TW":"CNN 全球 50 大美食名榜前列，清新無油、晶瑩剔透的熱帶生機之卷","en":"Ranked among CNN’s World’s 50 Best Foods—refreshing, oil-free, and bursting with garden crispness","vi":"Món cuốn thanh mát nức tiếng năm châu, sự kết hợp hoàn hảo giữa tôm thịt và rau vườn","ja":"CNN世界美食ランキング常連。ハーブと海老がぎっしり詰まったヘルシーな宝石","ko":"CNN 선정 세계 50대 음식에 빛나는 기름기 없이 산뜻한 건강식의 대명사"},"heroImage":"/images/vn/goi-cuon.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":10,"defaultServings":2,"caloriesPerServing":320,"category":"rollsSnacks","dietaryTags":["classic","glutenFree","pescatarian"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"南部・湄公河三角洲與西貢","en":"Southern Vietnam / Mekong Delta & Saigon","vi":"Miền Nam / Đồng bằng sông Cửu Long","ja":"南部・メコンデルタおよびサイゴン","ko":"베트남 남부 / 메콩델타 및 사이공"},"famousStreetMarkets":[{"zh-TW":"西貢范五老街 (Phố Phạm Ngũ Lão)","en":"Pham Ngu Lao Street Carts","vi":"Phố đi bộ Phạm Ngũ Lão","ja":"ファングーラオ通り","ko":"호찌민 팜응라오 거리"},{"zh-TW":"檳城市場小吃攤 (Chợ Bến Thành)","en":"Ben Thanh Market Food Row","vi":"Chợ Bến Thành","ja":"ベンタイン市場","ko":"벤탄 시장 음식 코너"}],"historyStory":{"zh-TW":"Gỏi Cuốn（字面意為「沙拉捲」）起源於越南南部湄公河水網平原。當地終年溫暖濕潤，盛產水稻與豐富的新鮮野菜。不同於油炸春捲，生春捲完全不用一滴油，以水浸軟的薄米紙包裹當日捕撈的鮮蝦、水煮五花肉、燙熟細米線與薄荷、九層塔，沾食以海鮮醬、花生碎炒製的濃稠甜鹹蘸醬，清爽無負擔。","en":"Gỏi Cuốn literally means ‘salad roll’, born from the lush, herb-rich waterways of the Mekong Delta. Unlike deep-fried spring rolls, this is a completely guilt-free, raw celebration of translucent rice paper enveloping sweet poached prawns, tender pork belly slices, soft vermicelli, fresh spearmint, and chives, served with savory-sweet peanut hoisin sauce.","vi":"Gỏi cuốn là món ăn dân dã bắt nguồn từ miền Nam sông nước. Với khí hậu nhiệt đới quanh năm, người dân chuộng các món cuốn thanh nhẹ không dầu mỡ. Từng con tôm đỏ au cuộn cùng thịt ba chỉ luộc, bún tươi và hẹ dài qua lớp bánh tráng mỏng tang, chấm cùng tương đậu phộng béo bùi.","ja":"ベトナム南部メコンデルタの豊かな水と温暖な気候が生んだ極上ヘルシーフード。揚げ春巻きと異なり油を一切使わず、水で戻したライスペーパーで茹でたてのエビ、豚バラ肉、ブン（米麺）、ミントやニラを巻いて作ります。","ko":"메콩델타의 풍요로운 자연에서 유래된 건강한 롤 요리입니다. 기름에 튀기지 않고 투명한 라이스페이퍼에 삶은 새우와 돼지고기 수육, 생허브를 말아 땅콩 호이신 소스에 푹 찍어 먹습니다."},"vietScript":"Gỏi Cuốn Tôm Thịt","vietPhonetics":"Goy Kwoon Tom Teet","audioPronunciationText":"Cho tôi một đĩa gỏi cuốn tôm thịt chấm tương đậu phộng!"},"ingredients":[{"id":"rice-paper","name":{"zh-TW":"越式圓形薄米紙 (Bánh tráng 22cm 直徑)","en":"Vietnamese Round Rice Paper Wrappers (22cm)","vi":"Bánh tráng dẻo mỏng cuộn gỏi","ja":"ベトナムライスペーパー（薄手・丸型）","ko":"베트남 라이스페이퍼 (원형 22cm)"},"amount":8,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Bánh tráng cuốn gỏi","vietPronunciation":"Bahn Trahng Kwoon Goy"},{"id":"fresh-prawns","name":{"zh-TW":"新鮮大白蝦或草蝦 (帶殼水煮後橫向剖半)","en":"Fresh Tiger Prawns (Poached & halved lengthwise)","vi":"Tôm sú tươi luộc chín bổ đôi","ja":"新鮮な海老（ボイルして縦半分にスライス）","ko":"신선한 새우 (삶은 뒤 세로로 반 가른 것)"},"amount":8,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Tôm luộc bổ đôi","vietPronunciation":"Tom Loo-ok"},{"id":"pork-belly-boiled","name":{"zh-TW":"五花肉塊 (清水加紅蔥頭煮熟薄切)","en":"Pork Belly (Gently boiled & thinly sliced)","vi":"Thịt ba chỉ luộc chín thái mỏng","ja":"茹で豚バラ肉の薄切り","ko":"삶은 돼지 삼겹 수육 (얇게 썬 것)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","vietName":"Thịt ba rọi luộc","vietPronunciation":"Teet Bah Roy"},{"id":"rice-vermicelli","name":{"zh-TW":"越式細米線 (煮熟瀝乾放涼)","en":"Cooked Thin Rice Vermicelli (Bún)","vi":"Bún tươi sợi nhỏ","ja":"茹でた細米麺（ブン）","ko":"삶은 가는 쌀국수 면"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","vietName":"Bún tươi","vietPronunciation":"Boon Teu-oy"},{"id":"garlic-chives","name":{"zh-TW":"新鮮韭菜 (每捲保留一根露在捲外代表西貢特色)","en":"Fresh Garlic Chives (Stems sticking out)","vi":"Lá hẹ tươi dài","ja":"ニラ（先端を巻いた端から覗かせる伝統スタイル）","ko":"실부추 (끝부분이 롤 밖으로 삐져나오게 연출)"},"amount":8,"unitMetric":"stalk","unitUS":"stalk","vietName":"Lá hẹ","vietPronunciation":"Lah Heh"},{"id":"fresh-herbs-platter","name":{"zh-TW":"九層塔、新鮮綠薄荷、綠皺葉生菜葉","en":"Fresh Thai Basil, Spearmint & Green Leaf Lettuce","vi":"Rau húng quế, húng lủi, xà lách","ja":"バジル、スペアミント、レタス","ko":"타이바질, 스피아민트, 상추"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Rau thơm húng lủi","vietPronunciation":"Rao Tom Hoong Loo-ee"},{"id":"peanut-dipping-sauce","name":{"zh-TW":"花生海鮮蘸醬：海鮮醬 3 大匙、無糖花生醬 1.5 大匙、溫水 3 大匙、蒜蓉辣椒末、碎熟花生","en":"Peanut Hoisin Dip: 3 tbsp Hoisin, 1.5 tbsp Creamy Peanut Butter, 3 tbsp warm water, garlic chili & crushed roasted peanuts","vi":"Tương đậu phộng: Tương đen, bơ đậu phộng, tỏi phi, ớt băm, đậu phộng rang giã dập","ja":"ピーナッツホイシンダレ：ホイシンソース大さじ3、ピーナッツバター大さじ1.5、ぬるま湯、刻みピーナッツ","ko":"땅콩 해선장 딥: 해선장 3큰술, 무가당 피넛버터 1.5큰술, 미온수 3큰술, 다진 마늘, 으깬 땅콩 분태"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Tương chấm gỏi cuốn","vietPronunciation":"Teu-ong Chahm Goy Kwoon"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"白灼鮮蝦五花肉與蝦身橫向剖半","en":"Poach Prawns & Pork Belly, Slice Prawns in Half","vi":"Luộc tôm thịt chín tới & bổ đôi thân tôm","ja":"海老と豚肉の茹で上げ・海老の縦半分カット","ko":"새우와 삼겹살 삶기 및 새우 세로로 반 가르기"},"instruction":{"zh-TW":"小鍋中加水、幾片薑與拍扁紅蔥頭煮沸。放入五花肉塊慢火煮 12 分鐘至熟透，撈出冰鎮後切成極薄薄片。接著將鮮蝦放入原鍋煮 2 分鐘至全身變紅彎曲，撈出浸泡冰水。剝去蝦殼並剔除蝦線，用銳利刀鋒從蝦背橫剖成兩片（露出鮮紅漂亮的蝦身剖面備用）。","en":"Boil water with sliced ginger and shallots. Simmer pork belly for 12 mins until cooked through, plunge into ice water and slice thinly. In the same water, poach prawns for 2 mins until bright orange, shock in ice water, peel, and slice horizontally into two halves.","vi":"Đun sôi nước với gừng và hành tím. Luộc chín thịt ba chỉ trong 12 phút, ngâm nước đá rồi thái mỏng. Luộc tôm trong 2 phút đến khi đỏ au, ngâm nước đá bóc vỏ, bỏ chỉ lưng rồi dùng dao bén xẻ dọc thân tôm làm đôi.","ja":"生姜とエシャロットを入れた湯で豚バラ肉を12分茹で、氷水に取ってから薄切りにします。同じ湯で海老を2分ボイルし、氷水で冷まして殻をむきます。背わたを取り、包丁で縦半分にスライスします（断面の赤い色が外側から美しく見えます）。","ko":"생강과 샬롯을 넣은 끓는 물에 삼겹살을 12분간 삶아 찬물에 식힌 뒤 얇게 썹니다. 새우를 2분간 데쳐 얼음물에 담근 뒤 껍질을 벗기고 세로로 반을 가릅니다."},"durationSeconds":180,"image":"/images/vn/goi-cuon-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"調製濃醇越式花生海鮮沾醬","en":"Simmer Glossy Peanut Hoisin Dipping Sauce","vi":"Nấu tương chấm đậu phộng béo bùi sánh mịn","ja":"コク深いピーナッツホイシンダレ作り","ko":"고소하고 걸쭉한 땅콩 해선장 소스 만들기"},"instruction":{"zh-TW":"小鍋中熱少許油爆香蒜末。加入海鮮醬、純花生醬與溫水，微火攪拌均勻至微滾濃稠。關火倒入醬料小碟中，表面撒上厚厚一層烘焙碎花生與生辣椒碎。","en":"Heat 1 tsp oil in a tiny saucepan and sauté minced garlic. Add hoisin sauce, peanut butter, and warm water. Stir on low heat until velvety smooth. Pour into dip ramekins, topped with roasted crushed peanuts and chili.","vi":"Phi thơm tỏi băm trong chảo nhỏ. Cho tương đen, bơ đậu phộng và nước ấm vào khuấy đều trên lửa nhỏ đến khi sốt sánh sệt. Múc ra chén, rắc nhiều đậu phộng rang giã dập và ớt băm.","ja":"小鍋に油を熱しニンニクを炒めます。ホイシンソース、ピーナッツバター、ぬるま湯を加え、弱火で混ぜてとろみをつけます。器に盛り、刻みピーナッツと唐辛子をたっぷり振ります。","ko":"작은 냄비에 마늘을 볶다가 해선장, 피넛버터, 미온수를 넣고 약불에서 걸쭉해질 때까지 저어줍니다. 종지에 담고 으깬 땅콩과 고추를 얹습니다."},"durationSeconds":120,"image":"/images/vn/goi-cuon-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"米紙沾水與黃金擺盤順序","en":"Hydrate Rice Paper & Strategic Ingredient Layering","vi":"Làm ướt bánh tráng & kỹ thuật xếp lớp nghệ thuật","ja":"ライスペーパーの戻し方と具材の美しい重ね方","ko":"라이스페이퍼 적시기 및 비주얼 레이어링"},"instruction":{"zh-TW":"準備一盤溫水。拿一張米紙快速浸入水中 2 秒立刻取出平鋪在案板上（剛取出時紙仍偏硬，它會在包捲過程中慢慢吸收殘留水分變軟，切忌久泡！）。在米紙靠近自己的一側先鋪生菜葉、薄荷、九層塔、適量米線與五花肉片。而在米紙遠端中間位置，將 3 片半邊鮮蝦「紅面朝下」平放排成一列。","en":"Dip a dry sheet of rice paper in lukewarm water for just 2 seconds—do not soak! Lay it flat on a clean board (it will soften as you work). On the bottom third, layer lettuce, mint, Thai basil, a small pinch of vermicelli, and pork slices. In the upper middle third, lay 3 shrimp halves in a neat row, vibrant orange sides facing DOWN.","vi":"Nhúng nhanh bánh tráng vào đĩa nước ấm 2 giây rồi trải phẳng ra thớt sạch (không ngâm lâu bánh sẽ nát). Ở 1/3 phía dưới, xếp xà lách, rau thơm, bún tươi và vài lát thịt ba chỉ. Ở khoảng giữa phía trên, xếp 3 nửa con tôm úp mặt đỏ au xuống dưới thành hàng thẳng.","ja":"ぬるま湯にライスペーパーをサッと2秒だけくぐらせて清潔なまな板の上に広げます（浸けすぎ厳禁！）。手前側にレタス、ミント、バジル、少量のブン、豚肉を置きます。中央よりやや奥に、エビ3枚の赤い面を下にして横一列に並べます。","ko":"미온수에 라이스페이퍼를 딱 2초만 살짝 담갔다 뺍니다(오래 담그면 찢어집니다). 몸 쪽 1/3 지점에 상추, 허브, 소량의 쌀국수 면, 돼지고기 수육을 얹습니다. 가운데 위쪽에는 새우 3개의 붉은 면이 바닥을 향하도록 나란히 배치합니다."},"durationSeconds":90,"image":"/images/vn/goi-cuon-step3.jpg","crucialTips":{"zh-TW":"鮮蝦紅面朝下擺放的視覺秘密：捲到最後時，透光米紙剛好覆蓋在鮮蝦上，紅潤飽滿的鮮蝦會清晰透過透明外皮綻放出來！","en":"Placing shrimp orange-side-down ensures they shine brilliantly through the translucent wrapper once rolled.","vi":"Úp mặt đỏ của tôm xuống giúp con tôm hiện lên đỏ rực rỡ xuyên qua lớp bánh tráng trong veo sau khi cuộn.","ja":"エビの赤い面を下にするのがコツ！巻き上がった時に透明な皮から鮮やかな赤色が美しく透けて見えます。","ko":"새우의 붉은 면을 아래로 놓아야 다 말았을 때 투명한 피를 통해 먹음직스럽게 비쳐 보입니다."}},{"stepNumber":4,"title":{"zh-TW":"緊密包捲與插入西貢標誌性韭菜","en":"Roll Tightly & Tuck in Iconic Saigon Chive Stem","vi":"Cuộn tròn chắc tay & cài cọng hẹ xanh mướt","ja":"キュッと巻き込み・トレードマークのニラを添えて完成","ko":"단단하게 말기 및 시그니처 부추 줄기 꽂기"},"instruction":{"zh-TW":"用雙手手指將靠近自己的底層米紙拉起，緊緊包裹住生菜米線肉片。往上翻滾一圈，將左右兩側米紙向內緊密折疊封口。此時放上一根洗淨的長韭菜（讓頂部翠綠部分露在捲外 3-4 公分），繼續向前緊實滾過鮮蝦，利用米紙天然黏性封口！盛盤搭配花生沾醬。","en":"Lift bottom edge of the paper tightly over the filling. Roll forward once, then fold left and right edges inwards snugly. Place a green chive stem across, letting 3-4cm stick out of one side (the Saigon signature look). Roll firmly forward over the shrimp. Seal tightly and serve with peanut sauce!","vi":"Gập mép dưới của bánh tráng lên, cuộn chặt tay qua lớp rau thịt một vòng. Gập hai mép bên hông vào trong. Đặt một cọng hẹ xanh dài thò ra ngoài 3-4cm, tiếp tục cuộn tròn đè qua hàng tôm cho đến hết mép bánh. Xếp ra đĩa cùng chén tương đậu phộng.","ja":"手前の皮を持ち上げ、具材をキュッと締めるようにひと巻きします。左右の端を内側に折りたたみます。ここでニラを1本挟み（端を3cmほど外に飛び出させるのが本場サイゴンスタイル）、エビを包み込むように最後まで転がして密着させます。","ko":"몸 쪽 라이스페이퍼를 당겨 재료를 단단하게 한 바퀴 맙니다. 양옆을 안쪽으로 접어 넣고, 실부추 한 줄기를 끝부분이 3cm 정도 밖으로 삐져나오게 올립니다. 새우를 감싸며 끝까지 팽팽하게 말아 완성합니다."},"durationSeconds":60,"image":"/images/vn/goi-cuon-step4.jpg"}],"troubleshooting":[{"id":"goi-cuon-torn-paper","problem":{"zh-TW":"米紙在包捲時破裂撕開，或者黏手爛成一團","en":"Rice paper tears easily or turns into a sticky, gummy mess","vi":"Bánh tráng bị rách toạc hoặc dính nát bét khi cuộn","ja":"ライスペーパーが破れるか、ベタついて団子状になってしまう","ko":"라이스페이퍼가 찢어지거나 들러붙어 떡이 돼요"},"cause":{"zh-TW":"米紙在溫水中浸泡時間過長，澱粉過度軟化吸水；或者包入的水線、生菜未瀝乾水份。","en":"Soaked too long in water, or fillings were dripping wet.","vi":"Ngâm bánh tráng trong nước quá lâu, hoặc rau bún còn đọng nước.","ja":"水に浸けすぎたか、具材の水切りが不十分だった。","ko":"물에 너무 오래 담갔거나 속재료의 물기를 털지 않았기 때문입니다."},"solution":{"zh-TW":"米紙只需在水中「蜻蜓點水」閃過 1-2 秒立刻拿出！剛平鋪時手感應該是硬挺的，等放好食材時殘留水分正好讓它變得極致柔韌。","en":"Dip for 1-2 seconds only. It should feel firm when laid down; it softens naturally while placing ingredients.","vi":"Chỉ nhúng lướt qua nước 1-2 giây rồi lấy ra ngay. Bánh khi đặt xuống vẫn còn cứng, xếp xong nhân là bánh vừa mềm dẻo hoàn hảo.","ja":"水にくぐらせるのは1〜2秒で十分！置いた時点では硬くてOK。具を乗せている間にちょうど良い柔らかさになります。","ko":"물에 1~2초만 스치듯 적셔 꺼내세요. 도마에 놓았을 때 빳빳해야 재료를 올리는 동안 알맞게 부드러워집니다."}}],"proTips":[{"zh-TW":"如何保持春捲整天不乾裂：若不是現包現吃，可將保鮮膜輕輕蓋在春捲上，上面再覆蓋一條「擰乾的濕廚房紙巾」，常溫可保持 Q 彈潤澤 2-3 小時！切勿直接放入冰箱冷藏，米紙澱粉冷藏後會立刻老化返砂硬化。","en":"Storage secret: If not serving immediately, cover rolls with plastic wrap and a damp paper towel on top. Keep at room temp for 2-3 hours. Never refrigerate, or the rice starch will turn tough and brittle!","vi":"Mẹo giữ gỏi cuốn dẻo mềm: Nếu chưa ăn ngay, phủ màng bọc thực phẩm và một chiếc khăn ẩm lên trên ở nhiệt độ phòng. Tuyệt đối không cho vào tủ lạnh bánh tráng sẽ bị cứng đơ.","ja":"保存の裏技：すぐに食べない場合はラップをしてその上に固く絞った濡れ布巾を被せます。常温で2〜3時間はもっちり感をキープ！冷蔵庫に入れると皮がパキパキに硬くなるので絶対NG。","ko":"보관 꿀팁: 바로 먹지 않을 경우 랩을 씌우고 그 위에 젖은 키친타월을 덮어 상온에 두세요. 냉장고에 넣으면 라이스페이퍼 전분이 굳어 딱딱해지니 절대 냉장 보관하지 마세요."}]},{"country":"vn","id":"banh-xeo","slug":"banh-xeo","title":{"zh-TW":"越式黃金脆皮薑黃椰香煎餅 (班燒)","en":"Crispy Vietnamese Sizzling Crepe (Bánh Xèo)","vi":"Bánh Xèo Giòn Rụm Miền Tây","ja":"ベトナム風お好み焼き（バイン・セオ）","ko":"바삭한 베트남식 코코넛 부침개 (반쎄오)"},"subtitle":{"zh-TW":"入鍋滋滋脆響・薑黃椰奶薄脆粉漿・鮮蝦五花肉與清甜豆芽","en":"Golden Turmeric Coconut Batter with Shrimp, Pork Belly & Bean Sprouts","vi":"Đổ chảo xèo xèo giòn tan, thơm nức nước cốt dừa, ngập tràn tôm thịt","ja":"ジュージュー弾ける音！ココナッツとターメリック香る黄金色の極薄クレープ","ko":"지글지글 소리와 함께 부쳐내는 강황 코코넛 반죽, 새우와 돼지고기 숙주 부침개"},"tagline":{"zh-TW":"咬下咔嚓作響的越南煎餅之后，以芥菜生菜裹捲、蘸滿酸甜魚露水大口吃！","en":"The crackling crown jewel of southern street stalls—wrapped in leafy greens and dunked in Nước Chấm","vi":"Món bánh xèo trứ danh miền sông nước, cuốn rau cải xanh chấm nước mắm chua ngọt","ja":"一口かじれば軽快な音が響く！生野菜で巻いてタレにたっぷり浸すのが本場流","ko":"한 입 베어 물면 바사삭 부서지는 황금빛 반죽, 겨자잎에 싸서 늑참 소스에 푹 찍어 드세요"},"heroImage":"/images/vn/banh-xeo.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":15,"defaultServings":2,"caloriesPerServing":510,"category":"rollsSnacks","dietaryTags":["classic","glutenFree"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"南部・湄公河三角洲 (Miền Tây)","en":"Mekong Delta / Southern Vietnam","vi":"Miền Tây Nam Bộ","ja":"南部・メコンデルタ地方","ko":"베트남 남부 / 메콩델타"},"famousStreetMarkets":[{"zh-TW":"西貢第十郡 (Bánh Xèo 46A Đinh Công Tráng)","en":"Banh Xeo 46A Dinh Cong Trang (Saigon)","vi":"Bánh Xèo 46A Đinh Công Tráng","ja":"サイゴン バインセオ46A","ko":"호찌민 반쎄오 46A"},{"zh-TW":"芹苴水上市場 (Cần Thơ)","en":"Can Tho Floating Market Food Stalls","vi":"Chợ nổi Cái Răng Cần Thơ","ja":"カントー水上マーケット","ko":"껀터 수상시장 노점"}],"historyStory":{"zh-TW":"Bánh Xèo 的「Xèo」字是象聲詞，形容調製好的金黃粉漿倒入滾燙大鐵鍋時發出的「滋——啦——」爆烈聲響！南部湄公河派的特色是餅皮做得像草帽一樣大而極致薄脆，在黏米粉中加入薑黃粉與濃醇椰漿，煎得金黃焦脆，包入鮮蝦、五花肉片與蒸熟綠豆仁。","en":"The name Bánh Xèo mimics the explosive sizzling sound (‘xèo-xèo’) when cold turmeric rice batter hits a blistering cast-iron skillet. Southern style features paper-thin, giant crepes infused with coconut milk and golden turmeric, stuffed with fresh river prawns, pork slices, mung beans, and bean sprouts.","vi":"Tên gọi Bánh Xèo bắt nguồn từ tiếng reo xèo xèo vui tai khi người đầu bếp trút muôi bột vào chảo gang ngập mỡ nóng. Bánh xèo miền Tây to bản như vành nón lá, giòn tan nhờ bột gạo hòa nước cốt dừa và bột nghệ vàng ươm, thơm phức tôm thịt và giá đỗ.","ja":"名前の「セオ」は、熱々の鍋に生地を流し込んだ時にジュワ〜ッと響く音を表しています。南部風は米粉にターメリックとココナッツミルクを加え、大判で極薄のパリパリに焼き上げます。","ko":"반쎄오의 ‘쎄오’는 달궈진 팬에 반죽을 부을 때 나는 ‘치이익(xèo)’ 하는 경쾌한 소리에서 유래했습니다. 쌀가루에 강황과 코코넛 밀크를 섞어 종이처럼 얇고 바삭하게 부쳐냅니다."},"vietScript":"Bánh Xèo Giòn","vietPhonetics":"Bahn Seh-oh Zawn","audioPronunciationText":"Cho tôi một cái bánh xèo giòn nhiều tôm thịt và rổ rau cải xanh!"},"ingredients":[{"id":"rice-flour","name":{"zh-TW":"在來米粉 (黏米粉 Rice Flour)","en":"White Rice Flour","vi":"Bột gạo tẻ","ja":"上新粉（米粉）","ko":"멥쌀가루"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"vietName":"Bột gạo","vietPronunciation":"Boht Gow"},{"id":"cornstarch-tapioca","name":{"zh-TW":"木薯粉或玉米澱粉 (使餅皮極致薄脆不軟塌)","en":"Tapioca Starch or Cornstarch (For extra shatter)","vi":"Bột năng hoặc bột bắp","ja":"タピオカ粉または片栗粉","ko":"타피오카 전분"},"amount":30,"unitMetric":"g","unitUS":"1 oz","vietName":"Bột năng","vietPronunciation":"Boht Nahng"},{"id":"turmeric-powder","name":{"zh-TW":"純薑黃粉 (賦予鮮豔金黃色澤與泥土香氣)","en":"Ground Turmeric Powder","vi":"Bột nghệ vàng","ja":"ターメリックパウダー（秋ウコン）","ko":"강황 가루"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","isKeyFlavor":true,"vietName":"Bột nghệ","vietPronunciation":"Boht Nyeh"},{"id":"coconut-milk","name":{"zh-TW":"濃純椰漿 (Coconut Milk 注入濃郁甜香)","en":"Rich Coconut Milk","vi":"Nước cốt dừa đậm đặc","ja":"ココナッツミルク","ko":"코코넛 밀크"},"amount":120,"unitMetric":"ml","unitUS":"4 fl oz","isKeyFlavor":true,"vietName":"Nước cốt dừa","vietPronunciation":"Neu-oc Coht Zeu-ah"},{"id":"soda-water","name":{"zh-TW":"冰鎮無糖氣泡水或啤酒 (氣泡使麵糊膨脹酥脆極品秘訣)","en":"Ice-Cold Sparkling Water or Cold Beer (Secret for bubbly crunch)","vi":"Nước có ga ướp lạnh hoặc bia","ja":"冷えた炭酸水またはビール（サクサクの極秘裏技）","ko":"차가운 탄산수 또는 맥주 (기포로 바삭함 극대화)"},"amount":150,"unitMetric":"ml","unitUS":"5 fl oz","isKeyFlavor":true,"vietName":"Bia hoặc nước có ga","vietPronunciation":"Bee-ah"},{"id":"pork-belly","name":{"zh-TW":"五花肉薄片","en":"Pork Belly (Thinly sliced)","vi":"Thịt ba chỉ thái lát mỏng","ja":"豚バラ肉薄切り","ko":"삼겹살 얇은 슬라이스"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","vietName":"Thịt ba rọi","vietPronunciation":"Teet Bah Roy"},{"id":"fresh-shrimp","name":{"zh-TW":"新鮮中白蝦 (去泥腸剝殼留尾)","en":"Fresh Medium Prawns","vi":"Tôm đất tươi lột vỏ","ja":"新鮮な小海老","ko":"생 칵테일 새우"},"amount":8,"unitMetric":"piece","unitUS":"piece","vietName":"Tôm tươi","vietPronunciation":"Tom Teu-oy"},{"id":"bean-sprouts","name":{"zh-TW":"新鮮爽脆綠豆芽與蒸熟去皮綠豆仁","en":"Fresh Bean Sprouts & Steamed Split Mung Beans","vi":"Giá đỗ tươi & đậu xanh cà vỏ hấp chín","ja":"もやしと蒸した緑豆","ko":"신선한 숙주나물 및 찐 껍질 벗긴 녹두"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","vietName":"Giá đỗ, đậu xanh","vietPronunciation":"Ziah Doh"},{"id":"mustard-greens","name":{"zh-TW":"包煎餅專用：大片苦芥菜葉 (Cải xanh)、大片生菜葉、紫蘇與薄荷","en":"Wrapping Greens: Mustard Green Leaves (Cải Xanh), Lettuce & Herbs","vi":"Lá cải xanh to, xà lách, rau thơm","ja":"包み用生野菜：カラシナの葉（カイ・サイン）、レタス、ハーブ","ko":"쌈 채소: 겨자잎(카이싼), 상추, 허브"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Lá cải xanh cuốn bánh","vietPronunciation":"Lah Cye Sahn"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調製黃金椰香氣泡粉漿","en":"Whisk Golden Coconut Sparkling Batter","vi":"Pha bột bánh xèo vàng ươm thơm cốt dừa","ja":"ターメリックとココナッツの黄金炭酸生地作り","ko":"강황 코코넛 탄산 반죽 만들기"},"instruction":{"zh-TW":"在大碗中混和在來米粉、木薯粉、薑黃粉與少許鹽。倒入椰漿與冰鎮氣泡水（或冰啤酒），用打蛋器攪拌至無顆粒平滑流動液體。撒入切碎青蔥花，靜置鬆弛 20 分鐘。","en":"In a large bowl, whisk rice flour, tapioca starch, turmeric powder, and a pinch of salt. Pour in coconut milk and ice-cold sparkling water (or beer). Whisk until completely smooth like light cream. Stir in chopped scallions and let rest for 20 mins.","vi":"Trộn đều bột gạo, bột năng, bột nghệ và chút muối trong tô. Rót nước cốt dừa và nước có ga (hoặc bia) lạnh vào khuấy đều tay đến khi bột mịn màng tan hết vón cục. Thêm hành lá thái nhỏ, để bột nghỉ 20 phút.","ja":"ボウルに米粉、タピオカ粉、ターメリック、塩を混ぜます。ココナッツミルクと冷えた炭酸水を注ぎ、ダマがなくなるまでサラサラに混ぜます。刻み青ネギを加え、20分寝かせます。","ko":"볼에 쌀가루, 타피오카 전분, 강황가루, 소금을 섞습니다. 코코넛 밀크와 차가운 탄산수(또는 맥주)를 붓고 묽은 크림 상태가 될 때까지 덩어리 없이 섞은 뒤 쪽파를 넣고 20분간 휴지시킵니다."},"durationSeconds":180,"image":"/images/vn/banh-xeo-step1.jpg","crucialTips":{"zh-TW":"加入「冰氣泡水或冰啤酒」是煎餅輕盈酥脆的靈魂秘密！碳酸氣泡遇熱膨脹，會在餅皮內形成無數微小蜂窩氣孔，冷卻後也不會變韌！","en":"Chilled sparkling water or beer creates tiny micro-bubbles that burst in high heat for an ultra-airy crunch.","vi":"Bia hoặc nước có ga lạnh là bí kíp giúp bánh xèo giòn lâu và rỗ tổ ong xốp tan.","ja":"冷たい炭酸水を入れることで、熱い油に入った瞬間気泡が膨らみ、極上のサクサク食感になります。","ko":"차가운 탄산수나 맥주는 열을 만났을 때 미세한 기포를 만들어 바삭함을 오랫동안 유지해줍니다."}},{"stepNumber":2,"title":{"zh-TW":"爆炒鮮蝦五花肉底料","en":"Sauté Shrimp & Pork in Blistering Skillet","vi":"Xào săn tôm thịt thơm nức mũi","ja":"海老と豚バラ肉の香ばし炒め","ko":"새우와 삼겹살 먼저 볶기"},"instruction":{"zh-TW":"使用不沾大炒鍋（直徑 28-30cm），大火燒熱 1 大匙油。下五花肉片與大蒜碎爆炒出油，放入鮮蝦翻炒至蝦身轉紅八分熟，均勻散佈在鍋底。","en":"Heat 1 tbsp oil in a large 28cm nonstick or cast-iron skillet over high heat. Add sliced pork belly and fry until fat renders. Add prawns, tossing until pink and fragrant, scattering evenly across the pan.","vi":"Làm nóng chảo lớn với 1 thìa dầu ăn trên lửa to. Cho thịt ba chỉ và tỏi vào xào săn ra mỡ, thả tôm vào đảo đều đến khi tôm chuyển màu đỏ au, rải đều khắp đáy chảo.","ja":"フライパンに油大さじ1を強火で熱します。豚バラ肉とニンニクを炒めて脂を出し、海老を加えて赤くなるまでサッと炒め、鍋底全体に広げます。","ko":"큰 팬에 기름 1큰술을 두르고 센 불로 달굽니다. 삼겹살을 볶아 기름을 내고, 새우를 넣어 붉은빛이 돌 때까지 볶은 뒤 팬 바닥에 골고루 펼칩니다."},"durationSeconds":90,"image":"/images/vn/banh-xeo-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"下粉漿搖勻與燜煎至邊緣翹起金黃","en":"Ladle Batter, Swirl Thinly & Crisp the Edges","vi":"Rót bột tráng đều chảo & chiên giòn rụm","ja":"生地を流し込み手早く回し広げ・極薄カリカリに焼く","ko":"반죽 부어 얇게 돌리기 및 바삭하게 굽기"},"instruction":{"zh-TW":"趁鍋溫極高時，舀起一滿大湯勺金黃粉漿（約 100ml）迅速淋入鍋中，立刻雙手握鍋旋轉讓粉漿均勻鋪滿整個鍋壁，形成薄如蟬翼的餅皮！在其中半邊撒上一把綠豆芽與熟綠豆仁。蓋上鍋蓋燜煎 2.5 分鐘讓豆芽蒸熟。揭開鍋蓋，沿著鍋邊淋入 1 小匙油，轉中火繼續煎 2 分鐘，直到餅皮邊緣自然捲翹起酥脆金黃！","en":"While the pan is scorching hot, pour a ladle of golden batter (approx 100ml) into the center. Immediately tilt and swirl the pan to coat bottom and sides in an ultra-thin crepe. Scatter bean sprouts and mung beans across one half. Cover with lid for 2.5 mins to steam through. Remove lid, drizzle 1 tsp oil along the edges, and fry uncovered for 2 mins until the rim crisps and pulls away naturally.","vi":"Khi chảo đang cực nóng, múc một muôi bột đầy (100ml) rót nhanh vào chảo, lập tức nghiêng chảo láng thật mỏng đều khắp thành chảo. Rải giá đỗ và đậu xanh chín lên một nửa mặt bánh. Đậy vung 2.5 phút cho giá chín hơi. Mở vung, rưới 1 thìa dầu ăn men theo vành chảo, chiên tiếp 2 phút đến khi viền bánh tự tróc giòn tan vàng rộm!","ja":"アツアツの鍋に生地をお玉1杯分一気に流し入れ、手早く鍋を回してフチまで極薄に広げます。片側にだけもやしと緑豆を散らします。フタをして2分半蒸し焼きにします。フタを取り、鍋肌から油を小さじ1回し入れ、中火でフチが自然と浮き上がりパリパリになるまでさらに2分焼きます。","ko":"팬이 뜨거울 때 반죽 1국자(약 100ml)를 붓고 즉시 팬을 돌려 얇게 펼칩니다. 한쪽에만 숙주와 녹두를 얹고 뚜껑을 덮어 2.5분간 찝니다. 뚜껑을 열고 가장자리에 기름 1작은술을 둘러 중불에서 가장자리가 바삭하게 들뜰 때까지 2분간 더 부쳐냅니다."},"durationSeconds":300,"image":"/images/vn/banh-xeo-step3.jpg","dangerWarnings":{"zh-TW":"揭開鍋蓋後必須開蓋繼續煎 2 分鐘，讓水氣徹底蒸發並由邊緣油份炸脆！若一直蓋著鍋蓋，水氣回流餅皮會變軟發爛。","en":"Always remove the lid and finish frying uncovered to evaporate moisture completely, achieving that signature crispiness.","vi":"Bắt buộc phải mở vung chiên thêm 2 phút để hơi nước bốc đi hết. Nếu đậy vung suốt bánh sẽ bị nhão ỉu.","ja":"フタを取ってから必ず油を足して水分を飛ばしてください。フタをしたままだと水滴でふやけてしまいます。","ko":"뚜껑을 열고 수분을 날리며 기름에 튀기듯 구워야 합니다. 뚜껑을 계속 닫아두면 수분 때문에 눅눅해집니다."}},{"stepNumber":4,"title":{"zh-TW":"對折半月形起鍋，以芥菜生菜包裹沾汁享用","en":"Fold into Crescent & Wrap with Mustard Greens","vi":"Gập đôi bánh hình bán nguyệt & cuốn rau cải chấm mắm","ja":"半月形に折りたたみ・カラシナで巻いてタレに浸す","ko":"반달 모양으로 접기 및 겨자잎에 싸서 먹기"},"instruction":{"zh-TW":"用鍋鏟將沒鋪豆芽的另一半餅皮翻折過來，折成半月形。此時餅皮酥脆硬挺，滑入大盤中。吃法：撕下一小塊酥脆煎餅，放進一片大苦芥菜葉 (Cải xanh) 與生菜葉中，加入薄荷九層塔，像包烤肉一樣捲成捲，沾取滿滿酸甜魚露水 (Nước Chấm)，芥菜的微苦辛香完美化解煎餅油香！","en":"Use a spatula to fold the crepe in half into a crescent. Slide onto a platter. Dining ritual: Tear off a golden crispy wedge, wrap inside a broad mustard green leaf (cải xanh) with lettuce and mint, roll up snugly, and dunk deeply into a bowl of garlic-chili fish sauce dip (Nước Chấm).","vi":"Dùng xẻng gập đôi bánh lại thành hình bán nguyệt giòn rụm rồi trượt ra đĩa lớn. Cách ăn sành điệu: Dùng tay bẻ một góc bánh xèo nóng giòn, đặt lên lá cải xanh cay nồng cùng xà lách và rau thơm, cuộn chặt tay rồi chấm ngập vào bát nước mắm tỏi ớt chua ngọt!","ja":"フライ返しで半分に折りたたみ、半月形にして大皿に滑らせます。本場の食べ方：手でちぎったバインセオを、少しピリッとするカラシナの葉やレタスの上に乗せ、ハーブと一緒にロールして甘酢ヌクマムダレに豪快にディップ！","ko":"뒤집개로 반을 접어 반달 모양으로 만듭니다. 접시에 담아낸 뒤 가위나 손으로 바삭한 반쎄오를 잘라 알싸한 겨자잎과 상추 위에 올리고 허브와 함께 쌈을 싸서 새콤달콤한 늑참 소스에 푹 찍어 드세요!"},"durationSeconds":60,"image":"/images/vn/banh-xeo-step4.jpg"}],"troubleshooting":[{"id":"banh-xeo-not-crispy","problem":{"zh-TW":"煎餅外皮軟趴趴、不酥脆，像可麗餅一樣軟塌","en":"Crepe is soft, limp, and lacks crunch","vi":"Vỏ bánh xèo bị mềm xèo, ỉu như bánh crepe không có độ giòn","ja":"生地がクレープのように柔らかく、パリッとしたサクサク感がない","ko":"반죽이 바삭하지 않고 팬케이크처럼 흐물흐물해요"},"cause":{"zh-TW":"1. 下粉漿時鍋溫不夠高；2. 粉漿倒得過厚；3. 揭開鍋蓋後沒有加小匙油繼續煎至水氣完全揮發。","en":"1. Pan was not hot enough; 2. Poured batter too thick; 3. Didn’t fry uncovered with oil at the end.","vi":"1. Chảo chưa đủ độ nóng khi đổ bột; 2. Bột tráng quá dày; 3. Không mở vung rưới dầu để chiên giòn.","ja":"1. 鍋の温度が低かった。2. 生地の層が厚すぎた。3. 最後にフタを取って油で焼き切らなかった。","ko":"1. 팬의 온도가 낮았거나 2. 반죽을 너무 두껍게 둘렀거나 3. 뚜껑을 열고 기름으로 바삭하게 마무리하지 않았기 때문입니다."},"solution":{"zh-TW":"鍋子必須燒到微冒油煙才能下粉漿，下鍋時要有劇烈的「滋啦」聲。粉漿倒入後立刻旋轉鍋身讓厚度薄如紙張，最後開蓋務必沿鍋邊補少許油炸脆。","en":"Pan must be smoking hot for the loud sizzle. Swirl rapidly for paper-thin coating, and finish with a drizzle of oil uncovered.","vi":"Chảo phải thật nóng bốc khói nhẹ, tráng bột thật mỏng tang và mở vung rưới thêm chút dầu ở viền bánh.","ja":"煙がうっすら立つくらい強火で熱し、生地を入れたら秒速でフライパンを回します。最後はフタを取って油でカリッと焼き上げてください。","ko":"팬에서 연기가 살짝 날 만큼 달군 뒤 반죽을 붓고 즉시 얇게 돌려야 합니다. 마지막에는 뚜껑을 열고 기름을 둘러 바삭하게 구워내세요."}}],"proTips":[{"zh-TW":"老饕靈魂吃法：越式煎餅一定要用「苦芥菜葉 (Lá cải xanh)」包著吃！芥菜帶有類似芥末的淡淡微辛嗆香，與肥美椰香五花肉煎餅形成天作之合，解膩又過癮！","en":"Southern dining secret: Always wrap Bánh Xèo inside broad Mustard Green leaves (Lá cải xanh)! The wasabi-like herbal punch cuts right through the rich coconut pork oils with thrilling balance.","vi":"Đỉnh cao ẩm thực miền Tây: Bánh xèo nhất định phải cuốn cùng lá cải xanh cay! Vị cay hăng nhẹ như mù tạt của cải xanh quyện cùng bánh xèo béo ngậy tạo nên hương vị bùng nổ khó quên.","ja":"通の食べ方：バインセオは「カラシナの葉（カイ・サイン）」で巻くのが鉄則！ワサビのようなピリッとしたほのかな辛みが、ココナッツのコクと脂っこさを爽快に包み込んでくれます。","ko":"현지인 먹방 팁: 반쎄오는 반드시 쌉싸름하고 알싸한 ‘겨자잎(카이싼)’에 싸서 드세요! 와사비처럼 은은하게 코를 찌르는 알싸함이 기름진 고소함을 완벽하게 감싸줍니다."}]},{"country":"vn","id":"bun-bo-hue","slug":"bun-bo-hue","title":{"zh-TW":"順化宮廷香茅辣牛肉豬腳米線","en":"Hue Imperial Spicy Lemongrass Beef Noodle Soup (Bún Bò Huế)","vi":"Bún Bò Huế Cung Đình","ja":"フエ名物 ピリ辛レモングラス牛肉うどん（ブン・ボー・フエ）","ko":"후에 정통 매콤 레몬그라스 소고기 쌀국수 (분보후에)"},"subtitle":{"zh-TW":"胭脂紅辣椒油・濃郁香茅蝦醬高湯・厚切牛腱與滑嫩豬蹄","en":"Crimson Chili Annatto Broth with Lemongrass, Beef Shank & Pork Knuckle","vi":"Nước dùng đỏ au màu dầu điều, thơm lừng mắm ruốc sả cây, bắp bò giòn sần sật","ja":"深紅の自家製ラー油とレモングラス蝦醤スープ・極太丸米麺と牛スネ肉","ko":"선홍빛 고추기름과 레몬그라스 새우젓 육수, 쫄깃한 소 사태와 굵은 쌀국수"},"tagline":{"zh-TW":"越南古都最霸氣熱烈的宮廷味覺衝擊，辣、鮮、濃、香在舌尖奔騰","en":"The bold, regal masterwork of central Vietnam—fiery lemongrass broth with thick round noodles","vi":"Đệ nhất mỹ vị xứ thần kinh, cay nồng đậm đà khó quên","ja":"旧王都フエの宮廷料理から生まれた、刺激的な辛味とハーブが織りなす最高傑作","ko":"베트남 고도 후에의 궁중 미식, 깊은 불맛과 얼큰함이 매력적인 굵은 면발 쌀국수"},"heroImage":"/images/vn/bun-bo-hue.jpg","difficulty":"hard","prepTimeMinutes":30,"cookTimeMinutes":70,"defaultServings":4,"caloriesPerServing":590,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"中部・古都順化 (Thừa Thiên Huế)","en":"Central Vietnam / Imperial City of Hue","vi":"Miền Trung / Cố đô Huế","ja":"中部・古都フエ","ko":"베트남 중부 / 고도 후에"},"famousStreetMarkets":[{"zh-TW":"順化東霸市場 (Chợ Đông Ba)","en":"Dong Ba Market Alleys","vi":"Chợ Đông Ba","ja":"ドンバ市場","ko":"후에 동바 시장"},{"zh-TW":"順化香江河畔夜市 (Sông Hương)","en":"Perfume River Night Stalls","vi":"Bến thuyền Sông Hương","ja":"フォーン川沿い屋台","ko":"흐엉강변 야시장"}],"historyStory":{"zh-TW":"順化曾為越南阮朝古都，宮廷廚師們為了滿足皇家挑剔的味蕾，創造出層次極其豐富繁複的 Bún Bò Huế。與清淡雅緻的北越牛肉粉不同，順化米線選用像烏龍麵般粗圓彈牙的米粉，並以大量拍碎香茅段、發酵蝦醬 (Mắm ruốc) 與胭脂樹籽炒出紅亮香辣紅油，豪邁加入燉至軟爛的牛腱、豬腳與豬血糕。","en":"Once the seat of the Nguyen Dynasty emperors, Hue’s royal kitchen masters crafted Bún Bò Huế to captivate royal palates. Unlike delicate Hanoi pho, this dish features thick, round slippery noodles submerged in a fiery, multi-layered broth perfumed with bruised lemongrass stalks, fermented shrimp paste (mắm ruốc), and vibrant ruby annatto oil.","vi":"Bún Bò Huế là tuyệt tác xuất phát từ chốn cung đình triều Nguyễn. Món ăn nổi bật bởi sợi bún to tròn mướt mát, hòa quyện trong nồi nước dùng thơm nồng sả cây đập dập, đậm đà vị mắm ruốc Huế đặc trưng và sắc đỏ rực rỡ của màu dầu điều, ăn kèm bắp bò hoa và móng giò giòn ngọt.","ja":"かつて阮朝の都だった古都フエの宮廷料理人が生み出した傑作。細麺ではなくうどんのような太い丸米麺を使い、叩いたレモングラス、ベトナム特有の蝦醤（マム・ルオック）、紅のベニノキ油を贅沢に効かせたスパイシーで奥深いスープが特徴です。","ko":"응우옌 왕조의 수도였던 후에의 궁중 요리사들이 왕실을 위해 탄생시킨 명작입니다. 일반 쌀국수와 달리 우동처럼 굵고 둥근 면발을 사용하며, 으깬 레몬그라스와 새우 발효장(맘루억), 붉은 안나토유를 더해 칼칼하고 깊은 감칠맛을 냅니다."},"vietScript":"Bún Bò Huế","vietPhonetics":"Boon Baw Hway","audioPronunciationText":"Cho tôi một tô bún bò Huế bắp giò đầy đủ cay nhiều!"},"ingredients":[{"id":"beef-shank","name":{"zh-TW":"金錢牛腱肉 (Bắp bò 帶筋有嚼勁)","en":"Beef Shank / Heel Muscle","vi":"Bắp bò hoa","ja":"牛スネ肉","ko":"소 사태 / 아롱사태"},"amount":500,"unitMetric":"g","unitUS":"1.1 lb","isKeyFlavor":true,"vietName":"Bắp bò hoa","vietPronunciation":"Bahp Baw Hwah"},{"id":"pork-knuckle","name":{"zh-TW":"豬腳圈或前豬蹄 (燉出膠質骨香)","en":"Pork Knuckle / Trotter (Sliced)","vi":"Móng giò heo chặt khúc","ja":"豚足輪切り","ko":"돼지 족발 링 슬라이스"},"amount":400,"unitMetric":"g","unitUS":"14 oz","vietName":"Móng giò heo","vietPronunciation":"Mawng Zyo Heo"},{"id":"thick-bun-noodles","name":{"zh-TW":"粗圓順化米粉 (Sợi bún to 粗彈Q勁)","en":"Thick Round Bun Rice Noodles","vi":"Bánh bún sợi to Huế","ja":"太丸米麺（ブン・ボ・フエ用）","ko":"분보후에 전용 굵은 쌀국수 면"},"amount":500,"unitMetric":"g","unitUS":"1.1 lb","isKeyFlavor":true,"vietName":"Bún bò sợi to","vietPronunciation":"Boon Baw Suh-ee Toh"},{"id":"lemongrass-stalks","name":{"zh-TW":"新鮮香茅 (整支刀背拍扁捆成束燉湯)","en":"Fresh Lemongrass Stalks (Bruised & tied)","vi":"Sả cây đập dập bó tròn","ja":"生レモングラス（叩いて束ねたもの）","ko":"생 레몬그라스 줄기 (칼등으로 으깬 것)"},"amount":6,"unitMetric":"stalk","unitUS":"stalk","isKeyFlavor":true,"vietName":"Sả cây đập dập","vietPronunciation":"Sah Cye"},{"id":"mam-ruoc-hue","name":{"zh-TW":"順化特產蝦醬 (Mắm ruốc Huế 靈魂發酵鹹鮮)","en":"Hue Fermented Shrimp Paste (Mắm Ruốc Huế)","vi":"Mắm ruốc Huế đặc sản","ja":"フエ特産 シュリンプペースト（マム・ルオック）","ko":"후에 전통 발효 새우장 (맘 루억)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"vietName":"Mắm ruốc Huế","vietPronunciation":"Mahm Zoo-ok Hway","substitute":{"substituteName":{"zh-TW":"泰國蝦醬或特級魚露","en":"Thai shrimp paste or high-grade fish sauce","vi":"Mắm tôm Bắc hoặc nước mắm cốt","ja":"タイ産シュリンプペースト（ガピ）または魚醤","ko":"태국 카피(새우장) 또는 액젓"},"ratio":"1:1","explanation":{"zh-TW":"順化蝦醬需先用 100ml 溫水融化靜置 15 分鐘，只取上方澄清水倒入湯中，沉澱殘渣捨棄","en":"Dissolve paste in 100ml warm water, let settle, and pour ONLY the clear fragrant liquid into broth.","vi":"Khuấy tan mắm ruốc với nước ấm, để lắng cặn rồi chỉ lấy phần nước trong chắt vào nồi.","ja":"ぬるま湯で溶いて上澄み液だけをスープに加えることで、エグ味のない上品なコクになります。","ko":"미온수 100ml에 풀어 15분간 가라앉힌 뒤 윗물만 육수에 넣고 찌꺼기는 버리세요."},"whereToBuy":{"zh-TW":"東南亞雜貨店或亞裔超市專區","en":"Vietnamese specialty stores or Amazon","vi":"Chợ hoặc siêu thị","ja":"ベトナム食材店","ko":"베트남 식료품 마트"}}},{"id":"annatto-chili-oil","name":{"zh-TW":"胭脂樹紅籽油 (Dầu điều) 與炒香茅辣椒醬","en":"Red Annatto Oil & Sautéed Lemongrass Chili Sauce (Satế)","vi":"Dầu màu điều & ớt sả sa tế","ja":"紅のアナトー油＆レモングラスサテ辣椒醤","ko":"붉은 안나토유 및 레몬그라스 사테 칠리 소스"},"amount":2.5,"unitMetric":"tbsp","unitUS":"2.5 tbsp","isKeyFlavor":true,"vietName":"Dầu điều sa tế","vietPronunciation":"Zow Deew Sah Teh"},{"id":"garnishes","name":{"zh-TW":"配菜：薄切洋蔥圈、香蔥、芭蕉花絲 (Bắp chuối)、薄荷、檸檬角","en":"Garnishes: Sliced Onions, Scallions, Banana Blossom, Mint, Lime","vi":"Bắp chuối bào, giá sống, rau húng, chanh tươi","ja":"バナナの花のスライス、ミント、生ライム","ko":"바나나꽃 채, 숙주, 민트, 라임 조각"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Hoa chuối bào, rau sống","vietPronunciation":"Hwah Chu-oy"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"焯水牛腱豬蹄與拍香整支香茅","en":"Blanch Meats & Bruise Lemongrass Stalks","vi":"Chần sơ thịt bắp giò & đập dập bó sả","ja":"肉の下茹でとレモングラスの仕込み","ko":"고기 초벌 삶기 및 레몬그라스 손질"},"instruction":{"zh-TW":"大鍋冷水放入牛腱與豬腳塊，大火滾沸 5 分鐘撈出沖洗乾淨。香茅切去老葉，用刀背狠狠拍扁釋放精油，折成三折用棉繩捆好。順化蝦醬加入 100ml 溫水化開靜置 15 分鐘。","en":"Blanch beef shank and pork knuckles in boiling water for 5 mins, drain and rinse well. Trim lemongrass and smash stalks firmly with a cleaver to release aromatic oils, tied into a bundle. Stir shrimp paste in 100ml warm water; let sediment settle.","vi":"Chần bắp bò và móng giò trong nước sôi 5 phút, vớt ra rửa sạch bọt bẩn. Sả cây cắt bớt gốc lá, dùng sống dao đập dập thật mạnh để tinh dầu ứa ra rồi bó tròn lại. Khuấy tan mắm ruốc với 100ml nước ấm để lắng.","ja":"牛スネ肉と豚足を熱湯で5分茹でてアク抜きし、流水で洗います。レモングラスの根元を包丁の背で強打して香り成分を引き出し、タコ糸で束ねます。マムルオックをぬるま湯に溶いて静置します。","ko":"소 사태와 족발을 끓는 물에 5분간 데쳐 불순물을 씻어냅니다. 레몬그라스는 칼등으로 강하게 으깨어 향을 깨운 뒤 끈으로 묶습니다. 맘루억(새우젓)을 미온수 100ml에 풀어 찌꺼기를 가라앉힙니다."},"durationSeconds":240,"image":"/images/vn/bun-bo-hue-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"慢火清燉香茅骨湯與濾取精華","en":"Simmer Lemongrass Broth & Add Filtered Shrimp Essence","vi":"Ninh nước dùng sả & chắt nước mắm ruốc thơm lừng","ja":"レモングラスと上澄み蝦醤でじっくり煮込む","ko":"레몬그라스와 맑은 새우젓 육수 은근히 끓이기"},"instruction":{"zh-TW":"在 3.5 公升沸水中放入拍碎香茅捆、焯好牛腱與豬腳。轉微火慢燉 45 分鐘，將順化蝦醬沉澱後的「純淨上層澄清蝦水」慢慢沿鍋邊淋入。繼續燉煮 20 分鐘至牛腱用筷子能輕易穿透。撈出牛腱切薄片備用。","en":"In 3.5L water, add lemongrass bundles, beef shank, and knuckles. Simmer gently for 45 mins. Carefully ladle ONLY the top clear liquid from the shrimp paste mixture into the pot. Simmer 20 more mins until shank is tender. Remove shank to slice.","vi":"Cho sả bó, bắp bò và móng giò vào 3.5L nước đun sôi rồi hạ nhỏ lửa ninh 45 phút. Chắt phần nước mắm ruốc trong veo trên mặt đổ vào nồi nước dùng. Ninh tiếp 20 phút đến khi thịt bắp mềm xiên đũa qua được, vớt bắp bò ra thái lát.","ja":"水3.5Lにレモングラス束、牛スネ、豚足を入れ弱火で45分煮込みます。静置しておいたマムルオックの澄んだ上澄みだけをそっと注ぎます。さらに20分煮て牛スネ肉が柔らかくなったら取り出してスライスします。","ko":"물 3.5L에 레몬그라스, 고기들을 넣고 약불에서 45분간 은근히 끓입니다. 가라앉힌 새우젓의 맑은 윗물만 살며시 부어줍니다. 20분 더 삶아 사태가 부드러워지면 건져 얇게 썹니다."},"durationSeconds":3600,"image":"/images/vn/bun-bo-hue-step2.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"High Pressure: 35 mins + Quick Release","instructionOverride":{"zh-TW":"【電子壓力鍋版】：內膽放入肉類、香茅捆、蝦醬澄清汁與水 2.5 公升，高壓 35 分鐘。開蓋後加入紅辣油調味，牛腱軟嫩入口即化！","en":"【Instant Pot Method】: Pressure cook meats, lemongrass, and clarified shrimp liquid with 2.5L water on High for 35 mins. Stir in ruby annatto chili oil when done.","vi":"【Nồi áp suất】: Nấu cao áp 35 phút cùng sả và nước mắm ruốc trong. Xả van mở nắp cho dầu điều sa tế vào.","ja":"【電気圧力鍋】：高圧35分セット。自然減圧後、鮮やかなアナトー辣油を加えて仕上げます。","ko":"【인스턴트팟】：고압 35분 조리 후 감압합니다. 붉은 안나토유와 사테소스를 넣고 끓여냅니다."}}]},{"stepNumber":3,"title":{"zh-TW":"炒製亮紅胭脂辣椒油注入高湯","en":"Infuse Broth with Fiery Crimson Annatto Chili Oil","vi":"Thắng dầu màu điều & phi thơm ớt sa tế tạo màu đỏ rực rỡ","ja":"深紅のアナトーラー油を仕上げに回し入れる","ko":"붉은 안나토 고추기름을 둘러 비주얼과 매콤함 완성"},"instruction":{"zh-TW":"小鍋熱 2 大匙油，下胭脂樹紅籽小火炸 2 分鐘出色後濾掉紅籽，原紅油加入蒜末、紅蔥碎與朝天椒粉爆香成「順化紅油 (Sa tế)」。將紅油整勺淋入滾沸的高湯中！整鍋湯瞬間綻放鮮紅油亮、香氣撲鼻的華麗宮廷色澤。","en":"Warm 2 tbsp oil with annatto seeds on low heat for 2 mins until blood-orange, discard seeds. In this red oil, fry minced garlic, shallots, and chili powder into fiery Satế. Pour this glorious red elixir directly into the bubbling stockpot, creating Hue’s iconic shimmering red surface.","vi":"Làm nóng dầu ăn với hạt điều màu 2 phút để lấy màu đỏ thắm rồi vớt bỏ hạt. Cho tỏi ớt băm vào phi thơm thành sa tế sả ớt đỏ au. Đổ toàn bộ chảo sa tế vào nồi nước dùng đang sôi để tạo nên màu sắc cung đình rực rỡ!","ja":"小鍋でアナトー種子を熱して深紅の色を抽出し、種を濾します。ニンニクと唐辛子粉を加えて特製サテオイルを作ります。これを沸騰した大鍋のスープに一気に回し入れ、フエ伝統の紅い輝きを完成させます。","ko":"팬에 기름을 두르고 안나토 씨를 볶아 붉은 기름을 낸 뒤 씨를 걸러냅니다. 다진 마늘과 고춧가루를 볶아 사테소스를 만든 뒤 끓는 육수에 한 바퀴 둘러 붉은빛의 화려한 국물을 완성합니다."},"durationSeconds":180,"image":"/images/vn/bun-bo-hue-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"燙粗米線、碼肉澆紅湯，搭配芭蕉花絲","en":"Blanch Thick Bun, Ladle Broth & Garnish","vi":"Chần bún sợi to, chan nước dùng đỏ rực & ăn kèm hoa chuối","ja":"太丸米麺を盛り・紅いスープを注ぎハーブを添える","ko":"굵은 면 삶기, 붉은 육수 붓기 및 바나나꽃 채 곁들이기"},"instruction":{"zh-TW":"將粗米線沸水燙 30 秒盛入預熱大碗。鋪上切片厚牛腱、一塊嫩豬腳，撒滿薄切紫洋蔥絲與蔥花。舀起滾燙的鮮紅香茅蝦醬高湯淋滿碗內！附上一大盤新鮮芭蕉花絲、豆芽、九層塔與青檸角，趁熱大口嗦粉！","en":"Blanch thick round rice noodles for 30 secs, place in deep warmed bowls. Crown with tender beef shank slices, a succulent pork knuckle, raw purple onion ribbons, and scallions. Ladle piping-hot crimson broth over everything. Serve with shredded banana blossom, mint, and fresh lime.","vi":"Chần bún sợi to trong 30 giây rồi cho vào tô lớn. Xếp từng lát bắp bò hoa, móng giò heo giòn béo, rắc hành tây thái mỏng và hành hoa. Múc nước dùng đỏ au sôi sục chan ngập tô bún. Dọn kèm đĩa hoa chuối bào sợi giòn tan, giá sống và chanh ớt tươi.","ja":"太丸米麺を30秒湯通しして器に盛ります。薄切り牛スネ肉、煮込み豚足、紫玉ねぎ、青ネギをトッピング。アツアツの真っ赤なスープをたっぷり注ぎます。バナナの花の千切りやミントを山盛り添えていただきます！","ko":"굵은 면을 30초간 데쳐 그릇에 담습니다. 얇게 썬 소 사태, 쫄깃한 족발, 자색 양파채, 쪽파를 얹고 펄펄 끓는 붉은 육수를 넉넉히 붓습니다. 바나나꽃 채와 숙주, 라임을 곁들여 푸짐하게 즐기세요!"},"durationSeconds":60,"image":"/images/vn/bun-bo-hue-step4.jpg"}],"troubleshooting":[{"id":"bun-bo-hue-overly-fishy","problem":{"zh-TW":"湯頭蝦醬味過濃嗆鼻、帶有刺鼻腥味或發苦","en":"Broth has an overwhelming, pungent, or muddy shrimp odor","vi":"Nước dùng bị nồng gắt mùi mắm ruốc, có vị chát đắng","ja":"シュリンプペーストの匂いが強すぎて臭みが出てしまった","ko":"새우젓 냄새가 너무 강하고 텁텁하며 쓴맛이 나요"},"cause":{"zh-TW":"直接將蝦醬整塊挖入湯鍋中未經沈澱，連同底部發酵黑渣一同煮進湯裡。","en":"Dumped raw shrimp paste directly into the pot without settling the sediments.","vi":"Múc thẳng cả bã mắm ruốc vào nồi mà không hòa tan lọc lấy nước trong.","ja":"ペーストをそのまま鍋に投入し、底の沈殿物まで一緒に煮込んでしまった。","ko":"새우젓을 가라앉히지 않고 통째로 넣어 찌꺼기까지 같이 끓였기 때문입니다."},"solution":{"zh-TW":"順化蝦醬必須先用 100ml 溫水徹底化開，靜置 15 分鐘待黑渣完全沈在碗底，只取上方澄澈的淡紅澄清汁淋入鍋中，香氣極其雅緻高貴！","en":"Always dissolve in warm water, rest 15 mins, and add ONLY the clarified top liquid.","vi":"Bắt buộc hòa tan mắm ruốc với nước ấm, chờ lắng 15 phút rồi chỉ gạn lấy phần nước trong thơm dịu.","ja":"必ずぬるま湯で溶いて15分置き、底の黒い沈殿物を捨てて上澄みだけを使うのが鉄則です。","ko":"반드시 미온수에 풀어 15분간 가라앉힌 뒤 맑은 윗물만 넣어야 비린내 없이 깊은 감칠맛이 납니다."}}],"proTips":[{"zh-TW":"順化米線靈魂生菜——「芭蕉花絲 (Bắp chuối)」：順化當地絕不單吃豆芽，而是將新鮮紫色芭蕉花切成細如髮絲的薄圈浸泡檸檬水。芭蕉花微澀爽脆的口感能完美包裹紅辣油，是順化宮廷料理的頂級靈魂！","en":"Imperial signature accompaniment: True Bún Bò Huế is defined by shredded purple Banana Blossom (Bắp chuối)! Soaked in lime water for crispness, its subtle earthy crunch clings to the spicy annatto oil with regal perfection.","vi":"Linh hồn rau ghém xứ Huế: Ăn bún bò Huế chuẩn vị là phải có hoa chuối bào sợi mỏng ngâm chanh giòn rụm! Vị chát thanh của hoa chuối làm dịu đi cái cay nồng của sa tế, đưa món ăn lên tầm nghệ thuật.","ja":"フエ伝統の添え野菜：本場フエでは「バナナの花の千切り（バップ・チュオイ）」が欠かせません！ライム水にさらしたシャキシャキのほのかな渋みが、ピリ辛ラー油と奇跡のハーモニーを生み出します。","ko":"후에 정통 고명 팁: 분보후에는 ‘바나나꽃 채(밥추오이)’를 곁들여야 완벽합니다! 레몬물에 담가 떫은맛을 뺀 아삭한 바나나꽃이 매콤한 고추기름을 머금어 잊을 수 없는 식감을 선사합니다."}]},{"country":"vn","id":"com-tam","slug":"com-tam","title":{"zh-TW":"西貢經典碎米飯佐蜜汁香茅烤豬排","en":"Saigon Broken Rice with Lemongrass Pork Chop (Cơm Tấm)","vi":"Cơm Tấm Sườn Bì Chả Sài Gòn","ja":"サイゴン名物 砕き米の豚骨付きロース肉ご飯（コム・タム）","ko":"사이공 정통 깨진 쌀밥과 숯불 돼지갈비 구이 (껌승)"},"subtitle":{"zh-TW":"焦糖蜜汁香茅大豬排・蒸蛋肉餅・彈牙肉絲豬皮與翠綠蔥油","en":"Caramel Lemongrass Pork Chop with Steamed Egg Meatloaf & Scallion Oil","vi":"Sườn nướng mật ong sả óng ả, chả trứng béo mềm, bì giòn sần sật, mỡ hành","ja":"香ばしい骨付き豚ロース・蒸し卵ミートローフ・豚皮和えとネギ油","ko":"불향 가득 숯불 돼지갈비, 부드러운 달걀 고기찜, 돼지껍데기 무침과 파기름"},"tagline":{"zh-TW":"胡志明市無人不知的傳奇庶民早餐，平民碎米到米其林星級名菜的華麗蛻變","en":"The beloved all-day heartbeat of Saigon streets—from humble fractured grains to culinary perfection","vi":"Món ăn quốc hồn quốc túy của người dân phương Nam, ngập tràn phong vị đường phố","ja":"朝から晩までサイゴンっ子の胃袋を支えるソウルフード。砕け米独特のパラパラ食感","ko":"아침부터 밤까지 사이공 골목을 지키는 소울푸드, 고슬고슬한 밥과 달콤 짭조름한 돼지갈비의 환상 케미"},"heroImage":"/images/vn/com-tam.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":25,"defaultServings":2,"caloriesPerServing":640,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"南部・胡志明市 (西貢)","en":"Southern Vietnam / Saigon","vi":"Miền Nam / Sài Gòn","ja":"南部・サイゴン（ホーチミン市）","ko":"베트남 남부 / 사이공"},"famousStreetMarkets":[{"zh-TW":"西貢第三郡 (Cơm Tấm Ba Ghiền - 米其林推薦)","en":"Com Tam Ba Ghien (Michelin Bib Gourmand)","vi":"Cơm Tấm Ba Ghiền","ja":"コムタム・バーギエン","ko":"호찌민 바기엔 껌승"},{"zh-TW":"西貢第一郡 (Cơm Tấm Cali)","en":"Com Tam Cali (District 1)","vi":"Cơm Tấm Cali","ja":"コムタム・カリ","ko":"호찌민 껌땀 캘리"}],"historyStory":{"zh-TW":"Cơm Tấm 誕生於舊時代湄公河三角洲農村。在碾米過程中脫落碎裂的「斷裂米 (Broken Rice)」，過去因賣不出好價錢，多由貧苦農民與黃包車夫留作自食。然而西貢人發現碎米吸水少、質地乾爽鬆軟，蒸熟後帶有獨特堅果米香，搭配炭火焦糖香茅大豬排 (Sườn)、五花肉絲蒸蛋肉餅 (Chả trứng)、脆豬皮絲 (Bì) 與滾燙翠綠蔥油 (Mỡ hành)，成為名震東南亞的平民盛宴。","en":"Historically made from fractured rice grains damaged during the milling process, Cơm Tấm was once the humble food of poor rice farmers and cyclo drivers who couldn’t sell imperfect rice. Saigonese culinary genius transformed these dry, fluffy broken grains with smoky lemongrass grilled pork chops (Sườn), steamed egg meatloaf (Chả trứng), thinly shredded pork skin (Bì), and hot scallion oil (Mỡ hành).","vi":"Cơm tấm xưa kia là thức ăn của người lao động nghèo vùng Nam Bộ, dùng hạt gạo tấm gãy vụn sau khi xay xát. Với sự tài hoa của người Sài Gòn, hạt gạo tấm tơi xốp ngát hương đã kết hợp cùng sườn cốt lết nướng than hoa vàng rộm, miếng chả trứng bùi béo, bì thái sợi và mỡ hành bóng bẩy, trở thành món ăn danh bất hư truyền.","ja":"元々は精米時に砕けて売り物にならなかった米（砕き米）を貧しい人々が食べていたのが始まり。水分が少なくパラリと炊き上がる独特の食感に、炭火で焼いた甘辛ポークチョップ、蒸し卵ミートローフ、ネギ油が絶妙にマッチします。","ko":"도정 과정에서 부서져 상품 가치가 없던 ‘깨진 쌀’을 가난한 인력거꾼들이 먹던 것에서 시작되었습니다. 수분이 적어 고슬고슬한 밥 위에 불향 가득한 돼지갈비와 달걀 고기찜, 파기름을 얹어 먹는 사이공 최고의 대표 요리입니다."},"vietScript":"Cơm Tấm Sườn Bì Chả","vietPhonetics":"Cohm Tahm Seu-on Bee Chah","audioPronunciationText":"Cho tôi một dĩa cơm tấm sườn bì chả nhiều mỡ hành!"},"ingredients":[{"id":"broken-rice","name":{"zh-TW":"越式碎米 (Gạo tấm 顆粒細碎口感乾爽鬆香)","en":"Vietnamese Broken Jasmine Rice (Gạo Tấm)","vi":"Gạo tấm thơm dẻo","ja":"ベトナム産 砕き米（ガオ・タム）","ko":"베트남 깨진 자스민 쌀 (가오땀)"},"amount":200,"unitMetric":"g","unitUS":"7 oz","isKeyFlavor":true,"vietName":"Gạo tấm","vietPronunciation":"Gow Tahm","substitute":{"substituteName":{"zh-TW":"一般泰國香米 (煮飯時減少 15% 水量保持乾爽)","en":"Jasmine Rice cooked with 15% less water","vi":"Gạo lài miên bớt nước khi nấu","ja":"ジャスミンライス（水を15%減らして硬めに炊く）","ko":"자스민 쌀 (물을 15% 적게 잡아 고슬고슬하게 짓기)"},"ratio":"1:1","explanation":{"zh-TW":"碎米煮熟顆粒極小且粒粒分明，一般米煮稍乾硬即可接近口感","en":"Cook regular long-grain rice slightly firm and dry.","vi":"Nấu gạo thường khô ráo hạt để mô phỏng độ tơi của gạo tấm.","ja":"通常のお米を少し固めにパラパラに炊き上げます。","ko":"일반 자스민 쌀을 물을 살짝 덜 넣고 고슬고슬하게 지어주세요."},"whereToBuy":{"zh-TW":"東南亞超市或網購","en":"Asian supermarkets or Amazon","vi":"Cửa hàng gạo","ja":"アジア食材店","ko":"아시안 마트"}}},{"id":"pork-chops","name":{"zh-TW":"帶骨豬里肌排或梅花排 (厚度 1.2 公分)","en":"Bone-In Pork Loin Chops (1.2cm thick)","vi":"Sườn cốt lết heo có xương","ja":"骨付き豚ロース肉（厚さ1.2cm）","ko":"뼈 있는 돼지 등심/목살 찹 (두께 1.2cm)"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Sườn cốt lết","vietPronunciation":"Seu-on Coht Leht"},{"id":"pork-marinade","name":{"zh-TW":"烤排骨蜜汁醃料：香茅碎、紅蔥蒜末、煉乳 1 大匙、魚露 2 大匙、老抽 1 小匙、五香粉少許","en":"Pork Marinade: Minced Lemongrass, Garlic, 1 tbsp Condensed Milk, 2 tbsp Fish Sauce, Dark Soy & Five Spice","vi":"Gia vị ướp sườn: Sả băm, tỏi hành, sữa đặc 1 thìa, nước mắm 2 thìa, ngũ vị hương","ja":"漬けダレ：刻みレモングラス、練乳大さじ1、ヌクマム大さじ2、ニンニク、五香粉少々","ko":"양념장: 다진 레몬그라스, 연유 1큰술, 피시소스 2큰술, 마늘, 오향분 약간"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Nước sốt ướp sườn","vietPronunciation":"Neu-oc Soht Eup"},{"id":"cha-trung-meatloaf","name":{"zh-TW":"越式蒸蛋肉餅 (絞肉、冬粉、木耳、蛋黃液蒸熟)","en":"Steamed Egg Meatloaf (Chả Trứng with pork, glass noodles & wood ear)","vi":"Chả trứng hấp thịt băm nấm mèo","ja":"ベトナム風蒸し卵ミートローフ（チャー・チュン）","ko":"베트남식 달걀 고기찜 (짜쯩)"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","vietName":"Chả trứng hấp","vietPronunciation":"Chah Teu-ong Hahp"},{"id":"scallion-oil","name":{"zh-TW":"翠綠蔥油：青蔥花浸入滾燙熱油加少許鹽 (Mỡ hành)","en":"Scallion Oil: Sliced Green Onions Scalded with Hot Oil (Mỡ Hành)","vi":"Mỡ hành thơm lừng","ja":"熱油をかけた万能ネギ油（モー・ハン）","ko":"뜨거운 기름에 지진 파기름 (머한)"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"vietName":"Mỡ hành","vietPronunciation":"Maw Hahn"},{"id":"garnishes-side","name":{"zh-TW":"醃酸甜紅白蘿蔔絲 (Đồ chua)、大黃瓜片、番茄切片、單面荷包蛋","en":"Pickled Daikon & Carrot, Cucumber Slices, Fresh Tomato, Sunny-Side-Up Egg","vi":"Đồ chua, dưa leo, cà chua, trứng ốp la lòng đào","ja":"なます、きゅうり、トマト、半熟目玉焼き","ko":"무 당근 피클, 오이, 토마토, 반숙 계란후라이"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Dưa leo, trứng ốp la","vietPronunciation":"Zeu-ah Leo, Teu-ong"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"煉乳香茅蜜汁醃漬帶骨豬排","en":"Marinate Pork Chops with Lemongrass & Condensed Milk","vi":"Ướp sườn cốt lết với sả và sữa đặc thơm mềm","ja":"練乳とレモングラスで豚肉を柔らかく漬け込む","ko":"연유와 레몬그라스 특제 양념에 돼지갈비 재우기"},"instruction":{"zh-TW":"用肉槌將帶骨豬排兩面輕輕拍鬆斷筋。在醃料中加入「1 大匙越式煉乳」、魚露、香茅碎、蒜蓉與五香粉抓勻（煉乳的乳糖能軟化肉質，並在烘烤時形成迷人的紅潤焦糖色殼！），冷藏醃漬 30 分鐘。","en":"Tenderize pork chops lightly with a meat mallet. Mix marinade with 1 tbsp condensed milk, fish sauce, minced lemongrass, garlic, and five-spice. (Condensed milk tenderizes fibers and creates an irresistible golden-red caramelized glaze!). Marinate for 30 mins.","vi":"Dùng búa đập nhẹ hai mặt miếng sườn cốt lết cho mềm thớ thịt. Cho sả băm, tỏi hành, nước mắm và đặc biệt là 1 thìa sữa đặc Ông Thọ vào bóp đều tay (sữa đặc giúp sườn mềm mọng nước và lên màu cánh gián tuyệt đẹp khi nướng). Ướp 30 phút.","ja":"ミートハンマーで肉を叩いて筋切りします。練乳大さじ1、ヌクマム、レモングラス、ニンニク、五香粉を揉み込みます（練乳が肉を極上に柔らかくし、焼いた時に美しい照りを出します！）。30分漬け込みます。","ko":"돼지갈비를 고기 망치로 가볍게 두드려 연하게 만듭니다. 양념에 연유 1큰술, 피시소스, 레몬그라스, 마늘, 오향분을 넣고 조물조물 버무립니다(연유는 육질을 부드럽게 하고 구울 때 환상적인 캐러멜 색을 냅니다). 30분간 재워둡니다."},"durationSeconds":180,"image":"/images/vn/com-tam-step1.jpg","crucialTips":{"zh-TW":"西貢老饕主廚不傳秘方：醃肉時加入一匙「煉乳」！比單純加糖更能讓肉排鎖住肉汁，軟嫩多汁完全不乾柴。","en":"Saigon chef secret: A tablespoon of condensed milk tenderizes the meat far better than plain sugar, keeping it incredibly juicy.","vi":"Bí mật của các quán cơm tấm Sài Gòn: Một thìa sữa đặc trong sốt ướp giúp sườn mềm ngọt mọng nước mà không bị khô xác.","ja":"サイゴンの名店の隠し味：砂糖の代わりに「練乳」を使うことで、パサつかずジューシーに焼き上がります。","ko":"사이공 유명 식당의 비밀 팁: 설탕 대신 ‘연유’를 1큰술 넣으면 고기가 놀랍도록 촉촉하고 부드러워집니다."}},{"stepNumber":2,"title":{"zh-TW":"炭烤或氣炸焦糖香茅豬排","en":"Grill or Air Fry Pork Chop to Caramelized Perfection","vi":"Nướng sườn vàng ươm thơm lừng khói","ja":"骨付き豚肉を香ばしくジューシーに焼き上げる","ko":"불향 가득 돼지갈비 굽기"},"instruction":{"zh-TW":"條紋鑄鐵鍋熱少許油，放入豬排中大火每面煎 4 分鐘至表面呈現深金黃焦糖色，邊緣微焦香氣四溢。","en":"Heat a ridged grill pan over medium-high heat. Sear pork chops for 4 mins per side until deep golden caramelization forms with smoky charred grill marks.","vi":"Làm nóng chảo nướng với chút dầu, nướng sườn trên lửa vừa mỗi mặt 4 phút đến khi sườn chín vàng óng ả xém cạnh.","ja":"グリルパンを熱し、片面4分ずつ中火で両面に香ばしい焦げ目がつくまでじっくり焼き上げます。","ko":"팬을 달구어 양면을 4분씩 중불에서 굽습니다. 겉면이 짙은 갈색으로 캐러멜라이징되며 불향이 가득 배도록 익힙니다."},"durationSeconds":300,"image":"/images/vn/com-tam-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 190°C (375°F) for 12 mins","instructionOverride":{"zh-TW":"【氣炸鍋排骨版】：氣炸鍋預熱 190°C，豬排刷少許油放入，烤 8 分鐘翻面再烤 4 分鐘，出鍋肉汁滿溢且表皮焦脆！","en":"【Air Fryer Pork Chop】: Air fry at 190°C (375°F) for 8 mins, flip and fry 4 more mins. Sizzling, caramelized, and supremely tender inside.","vi":"【Nồi chiên không dầu】: Nướng ở 190°C trong 8 phút, lật mặt nướng thêm 4 phút cho chín đều vàng ươm.","ja":"【ノンフライヤー】：190°Cで8分加熱し、裏返して4分。表面はカリッと香ばしく、中は驚くほどジューシーに！","ko":"【에어프라이어】：190°C에서 8분 조리 후 뒤집어 4분 더 굽습니다. 겉은 바삭하고 속은 육즙 가득 완성됩니다."}}]},{"stepNumber":3,"title":{"zh-TW":"蒸熟碎米飯與沖淋翠綠蔥油","en":"Steam Broken Rice & Scald Scallion Oil","vi":"Nấu cơm tấm thơm dẻo & làm mỡ hành xanh mướt","ja":"砕き米をパラリと炊き・熱々ネギ油を作る","ko":"고슬고슬 밥 짓기 및 파기름 만들기"},"instruction":{"zh-TW":"碎米淘洗乾淨，加入清水（米水比例 1:1.1）蒸煮熟透，出鍋用飯勺撥散保持顆粒鬆爽。小碗放入切細青蔥花與少許鹽，燒熱 3 大匙油澆在蔥花上激發蔥香，製成西貢翠綠蔥油 (Mỡ hành)。","en":"Rinse broken rice gently, steam with water (1:1.1 ratio) until fluffy and dry. In a small bowl of chopped scallions and a pinch of salt, pour 3 tbsp scorching hot oil to create sizzling scallion oil (Mỡ hành).","vi":"Vo sạch gạo tấm, nấu với tỉ lệ nước 1:1.1 cho cơm chín tơi xốp thơm lừng. Cho hành lá thái nhỏ và chút muối vào bát, đun sôi 3 thìa dầu ăn rồi dội thẳng vào bát hành để làm mỡ hành xanh ngắt.","ja":"砕き米を洗い、水（米1：水1.1の割合）でパラリと炊き上げます。小鉢の刻みネギに熱々の油大さじ3をジュワッと注ぎ、鮮やかなネギ油（モー・ハン）を作ります。","ko":"깨진 쌀을 씻어 물(1:1.1 비율)을 붓고 고슬고슬하게 밥을 짓습니다. 쪽파에 뜨거운 기름 3큰술을 부어 향긋한 파기름(머한)을 만듭니다."},"durationSeconds":180,"image":"/images/vn/com-tam-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"裝盤擺設：大排、蒸蛋、流心煎蛋與淋蔥油","en":"Plate Broken Rice Platter with Chops, Egg & Scallion Oil","vi":"Bày đĩa cơm tấm thập cẩm ngập tràn topping","ja":"砕き米にご馳走トッピングとネギ油をたっぷりかけて完成","ko":"플레이팅: 밥 위에 갈비, 달걀찜, 계란후라이 얹고 파기름 끼얹기"},"instruction":{"zh-TW":"用小碗將碎米飯倒扣盛在平盤中央，在米飯頂部豪邁淋上 2 大匙翠綠蔥油。旁邊依序擺上一整塊大烤豬排、切塊的越式蒸蛋肉餅 (Chả trứng)、一顆單面半熟流心煎蛋、酸甜紅白蘿蔔絲與黃瓜片。吃時將甜酸魚露水均勻澆在飯與肉排上，拌著蛋黃蔥油大口享用！","en":"Mound broken rice in the center of a wide plate and crown generously with sizzling scallion oil. Arrange the golden lemongrass pork chop, sliced steamed egg meatloaf, a sunny-side-up egg, pickled veggies, and fresh cucumbers around. Drizzle with sweet fish sauce dip and dig in!","vi":"Xới cơm tấm ra đĩa, rưới đẫm 2 thìa mỡ hành bóng bẩy lên mặt cơm. Bày miếng sườn cốt lết vàng ươm, miếng chả trứng hấp, quả trứng ốp la lòng đào, đồ chua và dưa leo xung quanh. Rưới nước mắm chua ngọt lên khắp đĩa và thưởng thức trọn vẹn hương vị Sài Gòn!","ja":"平皿の中央にご飯を盛り、熱々のネギ油をたっぷり回しかけます。巨大な豚肉、蒸し卵ミートローフ、半熟目玉焼き、なます、きゅうりを贅沢に盛り付けます。甘酸っぱいヌクマムダレを回しかけて豪快に召し上がれ！","ko":"접시 중앙에 밥을 담고 향긋한 파기름을 듬뿍 끼얹습니다. 숯불 갈비, 달걀 고기찜, 반숙 계란후라이, 피클, 오이를 둘러 담습니다. 달콤새콤한 늑참 소스를 밥과 고기 위에 둘러 맛있게 비벼 드세요!"},"durationSeconds":60,"image":"/images/vn/com-tam-step4.jpg"}],"troubleshooting":[{"id":"com-tam-mushy-rice","problem":{"zh-TW":"碎米飯煮出來黏爛成糊狀，失去粒粒分明的鬆香口感","en":"Broken rice turned mushy, sticky, and lost its fluffy separate grains","vi":"Cơm tấm bị nhão nhoét, dính nát mất đi độ tơi xốp","ja":"ご飯がベチャついて団子状になってしまった","ko":"밥이 질척거리고 떡처럼 뭉쳐버렸어요"},"cause":{"zh-TW":"碎米顆粒極小且吸收水分速度快，加水過多或浸泡時間太長。","en":"Added too much water or soaked the broken rice before cooking.","vi":"Cho quá nhiều nước hoặc ngâm gạo lâu trước khi nấu.","ja":"水が多すぎたか、炊く前に長く浸水させてしまった。","ko":"물을 너무 많이 넣었거나 쌀을 미리 불려두었기 때문입니다."},"solution":{"zh-TW":"碎米煮前絕不可長時間浸泡！洗淨瀝乾後立即入鍋，米水比例嚴格保持 1:1 到 1:1.1，煮好後立刻開蓋用筷子撥鬆散散水氣。","en":"Do not soak broken rice. Keep water ratio strictly 1:1 to 1:1.1. Fluff immediately upon cooking.","vi":"Không ngâm gạo tấm trước khi nấu. Nấu đúng tỉ lệ nước 1:1.1 và xới tơi ngay khi chín.","ja":"浸水は不要です。水加減は1：1〜1.1にとどめ、炊き上がったらすぐにフタを開けてほぐしてください。","ko":"쌀을 불리지 말고 씻자마자 물을 1:1.1 비율로 맞춰 짓고, 밥이 다 되면 바로 주걱으로 저어 수분을 날리세요."}}],"proTips":[{"zh-TW":"神仙吃法：用筷子輕輕戳破半熟煎蛋的金黃蛋黃，讓濃稠蛋液流淌在滾燙的碎米飯與蔥油上，再舀一勺特製酸甜魚露水拌勻，每顆米粒包裹著蛋香與蔥香，好吃到停不下來！","en":"Saigon dining ritual: Pierce the runny yolk so it cascades over hot broken rice and sizzling scallion oil. Drizzle sweet fish sauce over the top and stir for pure heaven!","vi":"Nghệ thuật ăn cơm tấm: Chọc vỡ lòng đỏ trứng ốp la chảy tràn vào hạt cơm tấm quyện cùng mỡ hành béo ngậy, rưới thìa nước mắm chua ngọt rồi xúc một thìa đầy ắp đưa vào miệng!","ja":"至福の食べ方：半熟目玉焼きの黄身を割り、アツアツのご飯とネギ油の上にトロリと絡ませます。甘酸っぱいタレをかけて一緒に頬張るのが本場サイゴンの醍醐味！","ko":"현지인 먹방 팁: 반숙 노른자를 톡 터뜨려 고슬고슬한 밥과 파기름 위에 흐르게 한 뒤, 늑참 소스를 살짝 뿌려 비벼 드셔보세요!"}]},{"country":"vn","id":"cha-gio","slug":"cha-gio","title":{"zh-TW":"越式黃金酥脆炸春捲 (北越 Nem Rán / 南越 Chả Giò)","en":"Vietnamese Crispy Fried Spring Rolls (Chả Giò / Nem Rán)","vi":"Chả Giò Giòn Rụm / Nem Rán Hà Nội","ja":"ベトナム伝統の揚げ春巻き（チャー・ゾー / ネム・ザン）","ko":"베트남식 바삭한 튀김 스프링롤 (짜조 / 넴란)"},"subtitle":{"zh-TW":"蕾絲薄脆起泡米紙・黑木耳冬粉豬肉餡・清爽生菜包裹沾魚露","en":"Blistered Crackling Rice Paper with Pork, Glass Noodles & Wood Ear","vi":"Vỏ ram giòn tan rôm rốp, nhân thịt nấm mèo miến dong đậm đà thơm phức","ja":"気泡が弾ける極薄ライスペーパー・豚肉ときくらげのジューシーな餡","ko":"기포가 송송 맺혀 바사삭 부서지는 라이스페이퍼, 돼지고기와 목이버섯 당면 소"},"tagline":{"zh-TW":"外皮比中式春捲更薄脆十倍的舌尖驚艷，每一口都在唇齒間喀嚓碎裂","en":"Ten times crispier than ordinary egg rolls—shattering crackle with a savory aromatic heart","vi":"Món ăn không thể thiếu trong mâm cỗ Tết và bữa cơm gia đình Việt","ja":"普通の中華春巻きとは別次元のサクサク感！一度食べたら病みつきになる国民的おつまみ","ko":"일반 춘권보다 10배는 더 바삭한 라이스페이퍼 튀김의 정수, 입안 가득 퍼지는 고소함"},"heroImage":"/images/vn/cha-gio.jpg","difficulty":"easy","prepTimeMinutes":25,"cookTimeMinutes":15,"defaultServings":4,"caloriesPerServing":380,"category":"rollsSnacks","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"全越南北通行 (北部稱 Nem Rán，南部稱 Chả Giò)","en":"Nationwide (Northern ‘Nem Rán’, Southern ‘Chả Giò’)","vi":"Toàn quốc (Miền Bắc gọi Nem Rán, miền Nam gọi Chả Giò)","ja":"ベトナム全土（北部はネム、南部はチャーゾー）","ko":"베트남 전역 (북부는 넴란, 남부는 짜조)"},"famousStreetMarkets":[{"zh-TW":"河內老街 (Nem Rán Hàng Quạt)","en":"Hang Quat Spring Roll Alley (Hanoi)","vi":"Nem Rán Hàng Quạt","ja":"ハノイ ハンクアット通り","ko":"하노이 항꽛 넴란 골목"},{"zh-TW":"胡志明市 (Chả Giò Sài Gòn)","en":"Saigon Street Food Night Markets","vi":"Chợ Tân Định","ja":"サイゴン市場","ko":"호찌민 떤딘 야시장"}],"historyStory":{"zh-TW":"越式炸春捲自古便是越南農曆新年 (Tết) 與婚宴盛席不可或缺的頭盤大菜。它與一般中式春捲皮（小麥麵粉製）最大的不同，在於採用特製薄米紙或蔴紙 (Bánh tráng rế / Bánh đa nem) 包裹。下油鍋後，米紙澱粉受高溫迅速膨脹，形成成千上萬顆微小的酥脆金色氣泡，質地極致輕盈酥鬆，完全不吸油膩。","en":"A centerpiece of Vietnamese Lunar New Year (Tết) feasts and street stalls alike. The magical secret lies in using specialized rice paper wrappers (Bánh tráng nem/ram) instead of thick wheat flour sheets. Upon hitting hot oil, the rice starch blisters instantly into millions of micro-crispy bubbles, achieving an astonishing crackle without retaining heavy oil.","vi":"Nem rán là món ăn truyền thống không thể thiếu trong mâm cỗ ngày Tết cổ truyền của người Việt. Khác với vỏ bò bía bột mì, nem rán Việt Nam dùng bánh đa nem hoặc bánh tráng rế. Khi rán ngập dầu hoặc nồi chiên, vỏ bánh phồng rộp li ti giòn tan rôm rốp, để lâu vẫn không bị ỉu.","ja":"ベトナムの正月（テト）やお祝いの席に欠かせない伝統料理。小麦粉の皮ではなく専用のライスペーパーを使うことで、油で揚げた時に表面に無数の細かな気泡が立ち、信じられないほどの軽やかなサクサク感に仕上がります。","ko":"베트남 설날(뗏) 명절 상차림에 빠질 수 없는 국민 명절 요리입니다. 밀가루 피 대신 쌀가루 라이스페이퍼를 사용하여 튀겼을 때 표면에 수많은 미세한 기포가 생기며 극강의 바삭함을 자랑합니다."},"vietScript":"Chả Giò / Nem Rán","vietPhonetics":"Chah Zyo / Nehm Rahn","audioPronunciationText":"Cho tôi một đĩa nem rán giòn chấm nước mắm chua ngọt!"},"ingredients":[{"id":"spring-roll-wrappers","name":{"zh-TW":"越式專用炸春捲薄米紙 (Bánh đa nem 或 Bánh tráng bía)","en":"Vietnamese Spring Roll Rice Wrappers (Bánh đa nem)","vi":"Bánh đa nem hoặc bánh ram Hà Tĩnh","ja":"ベトナム揚げ春巻き専用ライスペーパー","ko":"짜조 전용 튀김용 라이스페이퍼"},"amount":16,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Vỏ ram cuốn nem","vietPronunciation":"Vaw Rahm Kwoon Nehm"},{"id":"ground-pork","name":{"zh-TW":"細豬絞肉 (肥二瘦八)","en":"Ground Pork (20% fat)","vi":"Thịt nạc vai xay","ja":"豚ひき肉","ko":"다진 돼지고기"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"vietName":"Thịt heo băm","vietPronunciation":"Teet Heo Bahm"},{"id":"wood-ear-mushrooms","name":{"zh-TW":"乾黑木耳 (泡發切細絲帶來彈脆口感)","en":"Dried Wood Ear Mushrooms (Soaked & finely shredded)","vi":"Nấm mèo / mộc nhĩ ngâm nở thái sợi","ja":"きくらげ（水で戻して千切り）","ko":"목이버섯 (불려서 곱게 채 썬 것)"},"amount":30,"unitMetric":"g","unitUS":"1 oz","isKeyFlavor":true,"vietName":"Mộc nhĩ nấm mèo","vietPronunciation":"Mawhk Ngee"},{"id":"glass-noodles","name":{"zh-TW":"越式綠豆冬粉 (泡軟剪成 2 公分小段吸收肉汁)","en":"Cellophane Glass Noodles (Soaked & cut to 2cm)","vi":"Miến dong ngâm mềm cắt ngắn","ja":"緑豆春雨（戻して2cmに切る）","ko":"녹두 당면 (불려서 2cm 길이로 자른 것)"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","vietName":"Miến dong","vietPronunciation":"Mee-en Zong"},{"id":"crab-or-shrimp","name":{"zh-TW":"蝦仁丁或蟹肉碎 (增加海味鮮甜)","en":"Minced Prawns or Crabmeat","vi":"Tôm tươi băm nhỏ hoặc thịt cua","ja":"刻みエビまたはカニ肉","ko":"잘게 다진 새우 살"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","vietName":"Tôm băm","vietPronunciation":"Tom Bahm"},{"id":"carrot-kohlrabi","name":{"zh-TW":"紅蘿蔔細絲與豆芽 (水分充分擠乾)","en":"Finely Shredded Carrots & Bean Sprouts (Squeezed dry)","vi":"Cà rốt & củ đậu bào sợi vắt ráo","ja":"人参ともやしの千切り（水気を絞る）","ko":"곱게 채 썬 당근과 숙주 (물기 짠 것)"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","vietName":"Cà rốt nạo sợi","vietPronunciation":"Cah Roht"},{"id":"egg-binding","name":{"zh-TW":"雞蛋 1 顆 (取蛋黃黏合肉餡)","en":"1 Whole Egg (Egg yolk for binding)","vi":"1 quả trứng gà (lấy lòng đỏ)","ja":"卵1個（つなぎ用）","ko":"달걀 1개 (결착용)"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Trứng gà","vietPronunciation":"Teu-ong Gah"},{"id":"vinegar-beer-brush","name":{"zh-TW":"刷皮神水：白醋 1 大匙 + 啤酒或糖水 1 大匙 (使米紙起泡酥脆金黃秘技)","en":"Crust Brush Liquid: 1 tbsp vinegar + 1 tbsp beer/sugar water","vi":"Nước giấm pha bia thoa vỏ bánh cho giòn","ja":"皮に塗る特製液：酢大さじ1＋ビール大さじ1","ko":"껍질용 특제 액체: 식초 1큰술 + 맥주 1큰술"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Nước thoa vỏ bánh giòn","vietPronunciation":"Neu-oc Toh-ah"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調拌經典冬粉木耳鮮肉餡","en":"Mix Pork, Prawn, Wood Ear & Glass Noodle Filling","vi":"Trộn đều nhân nem thịt nấm miến đậm đà","ja":"豚肉・きくらげ・春雨の旨味たっぷり餡作り","ko":"고기와 목이버섯 당면 소 버무리기"},"instruction":{"zh-TW":"將豬絞肉、蝦仁丁、木耳絲、冬粉段、胡蘿蔔絲置於盆中。打入 1 顆蛋黃，加入魚露 1.5 大匙、黑胡椒 1 小匙、紅蔥蒜末抓勻。切記：肉餡不可太濕，蔬菜水分必須先擠乾，否則炸時水氣會使米紙破裂！","en":"Combine ground pork, minced prawns, shredded wood ear, glass noodles, and carrots in a bowl. Add 1 egg yolk, 1.5 tbsp fish sauce, 1 tsp pepper, and minced shallots. Crucial tip: Ensure filling is not overly wet—squeeze vegetables dry to prevent bursting while frying!","vi":"Cho thịt xay, tôm băm, mộc nhĩ, miến dong và cà rốt vào âu. Cho lòng đỏ trứng, 1.5 thìa nước mắm, tiêu đen, hành tỏi băm vào trộn đều tay. Lưu ý: Nhân nem không được quá ướt, phải vắt kiệt nước rau củ để nem khi rán không bị bục rách.","ja":"ボウルに豚ひき肉、刻み海老、きくらげ、春雨、人参を合わせます。卵黄、ヌクマム大さじ1.5、黒胡椒、ニンニクを入れてよく混ぜます。注意：野菜の水分は固く絞り、餡が水っぽくならないようにしてください！","ko":"볼에 다진 돼지고기, 새우, 목이버섯, 당면, 당근을 넣습니다. 달걀노른자, 피시소스 1.5큰술, 후추, 마늘을 넣고 골고루 버무립니다. 채소의 물기를 꼭 짜서 소가 질척이지 않게 해야 터지지 않습니다."},"durationSeconds":180,"image":"/images/vn/cha-gio-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"刷脆皮醋水與緊密捲製春捲","en":"Brush Wrapper with Crisp-Liquid & Roll Tightly","vi":"Thoa nước giấm bia & cuộn nem tròn đều tay","ja":"酢水をサッと塗り・しっかりとタイトに巻く","ko":"식초맥주물 바르기 및 단단하게 말기"},"instruction":{"zh-TW":"將薄米紙平鋪在乾淨砧板上，用矽膠刷沾取少許「醋與啤酒調和水」輕刷在米紙表面使其軟化（醋的酸性會分解表面澱粉，炸出時形成無數金色細脆小氣泡！）。在靠近自己的一端放上一長條肉餡，往上緊緊翻折一圈，將左右兩側向內折疊成長方形，順勢向前滾緊成粗細均勻的春捲棒。","en":"Lay rice wrapper on a clean board. Lightly brush with vinegar-beer liquid to soften (vinegar breaks down surface starch to form tiny golden crisp blisters upon frying!). Place a log of filling on the bottom third, fold over once tightly, tuck both sides inwards, and roll forward snugly into a neat cylinder.","vi":"Trải vỏ bánh ram ra thớt sạch, dùng cọ quét một lớp nước giấm pha bia thật mỏng để vỏ mềm dẻo (giấm giúp vỏ nem giòn rụm nổi bọt rộp vàng óng khi rán). Xúc một lượng nhân vừa phải đặt ở mép dưới, cuộn một vòng chặt tay, gấp hai mép bên vào rồi lăn tròn đều về phía trước.","ja":"ライスペーパーを広げ、酢とビールを混ぜた液をハケで薄く塗ってしなやかにします（酢の効果で無数の微小な気泡が立ち、極限までパリパリになります！）。手前に餡を棒状に乗せ、ひと巻きして左右を折り込み、キュッとタイトに転がして包みます。","ko":"라이스페이퍼를 도마에 펴고 식초와 맥주 섞은 물을 붓으로 살짝 발라 부드럽게 합니다(식초는 튀길 때 황금빛 기포를 만들어 극강의 바삭함을 줍니다). 소를 올리고 단단하게 한 번 만 뒤 양옆을 접고 팽팽하게 맙니다."},"durationSeconds":240,"image":"/images/vn/cha-gio-step2.jpg","crucialTips":{"zh-TW":"包春捲切勿捲得太緊繃！內餡受熱會微微膨脹，若裹得死緊下鍋容易爆肚開裂。","en":"Do not wrap too tightly; the filling expands slightly when heated and may burst if over-tightened.","vi":"Không cuộn quá chặt tay, để khoảng hở nhẹ cho nhân nở ra khi rán không bị nứt vỡ.","ja":"きつく巻きすぎないこと！加熱で餡が膨らむため、ある程度の遊びを持たせて巻くのがコツです。","ko":"너무 팽팽하게 말면 튀길 때 속이 팽창하여 터질 수 있으니 살짝 여유를 두세요."}},{"stepNumber":3,"title":{"zh-TW":"低溫定型與高溫復炸極致金黃","en":"Double-Fry Method for Maximum Crackle","vi":"Kỹ thuật rán hai lần giòn rụm rôm rốp","ja":"二度揚げで極限のサクサク感に仕上げる","ko":"두 번 튀겨내는 비법으로 극강의 바삭함 완성"},"instruction":{"zh-TW":"油鍋燒至 150°C（中低溫），輕輕滑入春捲，中小火炸 5-6 分鐘至肉餡全熟且外皮微白硬挺，撈出瀝油 5 分鐘。開大火將油溫拉升至 185°C（高溫），將春捲回鍋進行「二次復炸」45-60 秒，春捲外皮瞬間爆開成無數金黃酥脆的細小微粒，逼出所有殘留油脂！","en":"Heat oil to 150°C (medium-low). Gently slide spring rolls in, frying for 5-6 mins until meat is cooked and skins firm. Remove and rest for 5 mins. Raise oil to 185°C (high heat) and flash-fry for 45-60 secs. The rice crust blisters into thousands of golden crackling bubbles and expels all trapped oil!","vi":"Đun dầu nóng 150°C, thả nem vào rán lửa vừa trong 5-6 phút cho nhân chín và vỏ se cứng lại, vớt ra để ráo 5 phút. Tăng lửa cho dầu sôi già 185°C, thả nem vào rán lại lần hai trong 45-60 giây để vỏ phồng rộp vàng giòn tan và ép hết dầu thừa ra ngoài!","ja":"150°Cの中温の油で5〜6分じっくり揚げて一度取り出します。油の温度を185°Cに上げ、45〜60秒サッと二度揚げ！表面の気泡がカリッと弾け、余分な油が抜けて最高のクリスピー食感に仕上がります。","ko":"150°C 중저온 기름에 5~6분간 튀겨 건져낸 뒤 5분간 기름을 뺍니다. 기름 온도를 185°C로 높여 45~60초간 2차로 빠르게 튀겨냅니다. 표면이 황금빛으로 바사삭 튀겨지며 기름기가 쏙 빠집니다."},"durationSeconds":360,"image":"/images/vn/cha-gio-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 180°C (350°F) 12 mins + 200°C 3 mins","instructionOverride":{"zh-TW":"【氣炸鍋無油酥脆版】：春捲外表均勻刷上一層薄薄植物油（防乾裂）。氣炸鍋 180°C 烤 12 分鐘，翻面並升溫至 200°C 烤 3 分鐘至金黃起泡，健康少油且極度酥脆！","en":"【Air Fryer Crisp】: Lightly brush rolls with vegetable oil. Air fry at 180°C (350°F) for 12 mins, flip and blast at 200°C (400°F) for 3 mins until golden and blistered.","vi":"【Nồi chiên không dầu】: Quét một lớp dầu ăn mỏng lên vỏ nem. Nướng ở 180°C trong 12 phút, lật mặt nướng tiếp ở 200°C trong 3 phút cho vỏ phồng giòn rụm.","ja":"【ノンフライヤー】：表面に薄く油をハケで塗ります。180°Cで12分、裏返して200°Cで3分高温加熱。油っこさゼロで驚くほどパリパリ！","ko":"【에어프라이어】：겉면에 식용유를 살짝 바르고 180°C에서 12분 조리, 뒤집어 200°C에서 3분간 고온 마무리하여 기름 없이 바삭하게 굽습니다."}}]},{"stepNumber":4,"title":{"zh-TW":"生菜薄荷包裹，沾酸甜辣椒魚露享用","en":"Wrap in Crisp Greens & Dip into Nước Chấm","vi":"Cuốn xà lách rau thơm chấm nước mắm chua ngọt","ja":"生レタスとハーブで包み・甘酢タレにディップ","ko":"상추와 허브에 싸서 새콤달콤 늑참 소스에 푹 찍어 먹기"},"instruction":{"zh-TW":"炸好的春捲切成兩半，能清晰看見木耳冬粉與飽滿肉汁。拿一片爽脆生菜葉，放上一片紫蘇與綠薄荷，放進一塊滾燙酥脆炸春捲，捲起來沾滿特調酸甜辣椒蒜蓉魚露水 (Nước Chấm)。生菜的冰涼甘脆與春捲的滾燙爆汁交織，人間極品！","en":"Slice spring rolls diagonally to reveal the glistening filling. Wrap each piece inside a crisp butter lettuce leaf with fresh mint and cilantro. Dunk into tangy garlic-chili Nước Chấm dipping sauce. The contrast of icy crunchy greens and scorching, savory crackle is pure culinary magic!","vi":"Cắt chéo chiếc nem nóng hổi lộ ra phần nhân bóng bẩy. Cuộn miếng nem vào lá xà lách cùng rau húng quế, kinh giới, rồi chấm ngập vào chén nước mắm chua ngọt tỏi ớt cay nồng. Vị thanh mát của rau hòa cùng độ giòn béo của nem tạo nên bản giao hưởng tuyệt vời!","ja":"斜め半分にカットし、シャキシャキのレタスやミントで熱々の揚げ春巻きをくるりと包みます。甘酸っぱいヌクチャムダレにたっぷり浸して口に放り込めば、冷たい野菜と熱い肉汁が最高のマリアージュを奏でます！","ko":"사선으로 반을 잘라 바삭한 소를 확인합니다. 싱싱한 상추와 민트에 뜨거운 짜조를 올리고 돌돌 말아 새콤달콤한 늑참 소스에 푹 찍어 드세요. 아삭한 채소와 육즙의 대비가 환상적입니다!"},"durationSeconds":60,"image":"/images/vn/cha-gio-step4.jpg"}],"troubleshooting":[{"id":"cha-gio-bursting","problem":{"zh-TW":"炸春捲下油鍋不久就爆開破洞，內餡散落在油中","en":"Spring rolls burst or tear open during frying","vi":"Nem bị bục rách, nhân rơi tung tóe trong chảo dầu","ja":"揚げている最中に皮が破れて中身が油に飛び散ってしまった","ko":"튀기는 도중 껍질이 찢어지고 속재료가 터져 나와요"},"cause":{"zh-TW":"1. 餡料水分太多（胡蘿蔔或豆芽未擠乾）；2. 包得太緊，內餡膨脹撐破米紙；3. 油溫太高一下鍋外皮驟熱撕裂。","en":"1. Filling was too watery; 2. Wrapped too tightly; 3. Oil was too scorching at the beginning.","vi":"1. Nhân nem đọng nhiều nước; 2. Cuộn quá chặt; 3. Dầu quá nóng lúc mới thả vào.","ja":"1. 餡の水分が多すぎた。2. きつく巻きすぎた。3. 初期の油温が高すぎた。","ko":"1. 채소의 물기를 덜 짰거나 2. 너무 세게 말았거나 3. 처음 기름 온도가 너무 높았기 때문입니다."},"solution":{"zh-TW":"胡蘿蔔與蔬菜切絲後務必撒少許鹽醃 5 分鐘用力擠乾水分！包捲時保留微小空隙，並以 150°C 中低溫入鍋定型。","en":"Salt and squeeze veggies thoroughly dry. Leave a tiny room when wrapping, and start frying at 150°C.","vi":"Vắt thật kiệt nước rau củ trước khi trộn. Cuộn có độ lỏng nhẹ và thả vào dầu ở nhiệt độ vừa phải 150°C.","ja":"野菜は塩もみして水分を徹底的に絞ってください。少しゆとりを持たせて巻き、150°Cの中温から揚げ始めます。","ko":"채소는 소금에 살짝 절여 물기를 꽉 짜내고, 여유를 두어 만 뒤 150°C의 중저온에서 튀기기 시작하세요."}}],"proTips":[{"zh-TW":"使春捲長時間金黃酥脆的秘密武器——「醋水塗皮」：在薄米紙表面刷上少許稀釋白醋，醋酸會弱化米澱粉鍵結，在油炸時瞬間形成成千上萬個細脆起泡，放涼一小時依然酥脆如玻璃！","en":"Bakery secret for long-lasting crunch: Brushing the wrapper with a touch of vinegar water causes the rice starch to bubble dramatically into millions of crispy blisters that stay crisp for hours!","vi":"Bí quyết giòn tan hàng giờ: Quét chút nước giấm pha loãng lên vỏ ram trước khi cuốn giúp vỏ nem nở bung hàng vạn bọt khí li ti vàng ruộm, để lâu vẫn giòn tan không hề ỉu!","ja":"長時間サクサクを保つプロの技：皮に薄く酢水を塗ることで、揚げた時に表面が気泡状に弾け、冷めてもパリッとした食感が驚くほど長持ちします！","ko":"오랫동안 바삭함을 유지하는 비법: 라이스페이퍼에 식초 물을 살짝 발라 말아주면 튀길 때 수많은 미세 기포가 터지며 몇 시간이 지나도 바삭함을 유지합니다!"}]},{"country":"vn","id":"bo-kho","slug":"bo-kho","title":{"zh-TW":"越式香茅紅燴牛腩 (佐熱脆法包)","en":"Vietnamese Lemongrass Beef Stew (Bò Kho)","vi":"Bò Kho Bánh Mì Truyền Thống","ja":"ベトナム風レモングラス牛すじ煮込み（ボー・コー）","ko":"베트남식 레몬그라스 비프 스튜 (보코)"},"subtitle":{"zh-TW":"法越融合慢燉精華・濃郁香茅八角肉桂茄汁・牛筋軟糯胡蘿蔔清甜","en":"Slow-Braised Beef Shank in Star Anise, Lemongrass & Tomato Aromatics","vi":"Bắp bò gân mềm nhừ ngấm đượm hương sả quế hồi, chấm bánh mì nóng giòn","ja":"八角とレモングラス香る濃厚トマト牛すじ煮込み・焼き立てバゲット添え","ko":"레몬그라스와 팔각, 토마토로 푹 끓여낸 야들야들한 소고기 스튜와 바게트"},"tagline":{"zh-TW":"法式燉牛肉遇上熱帶香茅香料的驚艷變奏，以酥脆法包撕扯沾湯是無上享受","en":"The tropical reincarnation of French beef bourguignon—tearing warm crusty baguette to soak the velvety broth","vi":"Món bò kho thơm nồng nàn góc phố, bữa sáng tuyệt hảo xé bánh mì chấm đẫm","ja":"フランス料理の技法とベトナムのスパイスが織りなす極上シチュー","ko":"프랑스 비프 부르기뇽의 베트남식 열대 재해석, 바삭한 바게트를 푹 적셔 먹는 별미"},"heroImage":"/images/vn/bo-kho.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":60,"defaultServings":4,"caloriesPerServing":520,"category":"soupsStews","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"南部・胡志明市 (西貢)","en":"Southern Vietnam / Saigon","vi":"Miền Nam / Sài Gòn","ja":"南部・サイゴン","ko":"베트남 남부 / 사이공"},"famousStreetMarkets":[{"zh-TW":"西貢第一郡 (Bò Kho Út Nhung)","en":"Bo Kho Ut Nhung (Saigon District 1)","vi":"Bò Kho Út Nhung","ja":"サイゴン1区 ボーコー・ウットニュン","ko":"호찌민 1군 웃늉 보코"},{"zh-TW":"新定市場 (Chợ Tân Định)","en":"Tan Dinh Market Food Alleys","vi":"Chợ Tân Định","ja":"タンディン市場","ko":"떤딘 시장 골목"}],"historyStory":{"zh-TW":"Bò Kho 體現了法式紅酒燉牛肉 (Boeuf Bourguignon) 在熱帶西貢的完美在地化。越南主廚以新鮮香茅草段、八角、肉桂棒、番茄膏與越式純椰子水代替紅酒，慢火細燉帶筋牛肋條與胡蘿蔔。牛筋燉至軟糯如果凍，湯汁濃稠紅亮，撕下一塊熱氣騰騰的酥脆法包浸透湯汁，是全東南亞最銷魂的法包吃法。","en":"A tropical adaptation of French boeuf bourguignon, Bò Kho replaces heavy red wine with bruised lemongrass stalks, whole star anise, cinnamon quills, tomato paste, and fresh coconut water. Beef shank and tendon melt into gelatinous perfection alongside sweet tender carrots. Dipping crusty warm baguette into the deeply spiced sauce is pure comfort.","vi":"Bò kho là sự kết tinh tinh tế giữa món bò hầm kiểu Pháp và gia vị nhiệt đới Việt Nam. Người Sài Gòn thay thế rượu vang bằng sả cây đập dập, hoa hồi, quế chi, cà chua và nước dừa tươi ngọt lành. Từng miếng bắp bò nạm gân hầm mềm rục ngập trong làn nước sốt nâu đỏ sánh ngậy, xé miếng bánh mì nóng giòn chấm ngập vị ngon.","ja":"フランスのブッフ・ブルギニヨンがベトナム南部で進化した郷土料理。ワインの代わりにレモングラス、八角、シナモン、そしてココナッツジュースを使い、牛スネ肉と牛すじをトロトロになるまで煮込みます。パリパリのフランスパンをちぎって濃厚なスープに浸して食べるのがお決まりです。","ko":"프랑스식 소고기 스튜를 베트남 현지 스타일로 재해석한 대표 요리입니다. 와인 대신 으깬 레몬그라스, 팔각, 시나몬, 신선한 코코넛 워터를 넣어 소 사태와 스지를 젤라틴처럼 부드럽게 푹 끓여냅니다."},"vietScript":"Bò Kho Bánh Mì","vietPhonetics":"Baw Kaw Bahn Mee","audioPronunciationText":"Cho tôi một tô bò kho nạm gân và hai ổ bánh mì giòn!"},"ingredients":[{"id":"beef-shank-tendon","name":{"zh-TW":"帶筋牛肋條或牛腱牛筋塊 (切 3.5 公分大塊)","en":"Beef Shank & Tendon (Cut into 3.5cm chunks)","vi":"Nạm bò bắp hoa có gân thái quân cờ","ja":"牛スネ肉・牛すじ肉（大きめ3.5cm角切り）","ko":"소 사태 및 스지/양지머리 (큼직하게 썬 것)"},"amount":600,"unitMetric":"g","unitUS":"1.3 lb","isKeyFlavor":true,"vietName":"Bắp nạm bò có gân","vietPronunciation":"Bahp Nahm Baw"},{"id":"fresh-lemongrass","name":{"zh-TW":"新鮮香茅 (4 支拍扁切段燉煮 + 2 大匙細末炒香)","en":"Fresh Lemongrass (4 stalks bruised + 2 tbsp minced)","vi":"Sả cây đập dập cắt khúc & sả băm","ja":"生レモングラス（叩いてぶつ切り＋みじん切り）","ko":"생 레몬그라스 (으깬 줄기 4개 + 다진 것 2큰술)"},"amount":4,"unitMetric":"stalk","unitUS":"stalk","isKeyFlavor":true,"vietName":"Sả cây đập dập","vietPronunciation":"Sah Cye"},{"id":"carrots-cut","name":{"zh-TW":"紅蘿蔔 (滾刀切滾石塊)","en":"Carrots (Cut into rolling chunks)","vi":"Cà rốt gọt vỏ cắt khúc","ja":"人参（乱切り）","ko":"당근 (큼직하게 썬 것)"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","vietName":"Cà rốt","vietPronunciation":"Cah Roht"},{"id":"coconut-water","name":{"zh-TW":"天然香甜純椰子水 (Nước dừa 使湯頭自然甘甜滑潤)","en":"Fresh Young Coconut Water (Adds natural velvety sweetness)","vi":"Nước dừa xiêm tươi","ja":"ココナッツウォーター（自然な甘みとコクの秘訣）","ko":"코코넛 워터 (자연스러운 단맛)"},"amount":400,"unitMetric":"ml","unitUS":"13.5 fl oz","isKeyFlavor":true,"vietName":"Nước dừa tươi","vietPronunciation":"Neu-oc Zeu-ah Teu-oy"},{"id":"bo-kho-spices","name":{"zh-TW":"香料組：八角 2 顆、肉桂棒 1 支、胭脂樹紅油 2 大匙、番茄膏 2 大匙、五香粉半小匙","en":"Spices: 2 Star Anise, 1 Cinnamon Stick, 2 tbsp Annatto Oil, 2 tbsp Tomato Paste & 0.5 tsp Five Spice","vi":"Gia vị bò kho: Hoa hồi, quế, dầu màu điều, sốt cà chua, ngũ vị hương","ja":"スパイスセット：八角2個、シナモン棒1本、アナトー油、トマトペースト、五香粉","ko":"스파이스: 팔각 2개, 시나몬스틱 1개, 안나토유, 토마토페이스트, 오향분"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Gói vị bò kho","vietPronunciation":"Zia Vee Baw Kaw"},{"id":"crispy-baguette","name":{"zh-TW":"熱騰騰脆皮越式法包或粗米線 (蘸湯主食)","en":"Warm Shatteringly Crisp Baguettes (To dip)","vi":"Bánh mì nóng giòn ăn kèm","ja":"アツアツの焼きたてフランスパン","ko":"따뜻하고 바삭한 바게트"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Bánh mì ăn kèm","vietPronunciation":"Bahn Mee"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"香茅番茄紅油醃漬牛腩大塊","en":"Marinate Beef with Lemongrass, Spices & Annatto","vi":"Ướp thịt bò với gia vị bò kho thơm nức","ja":"レモングラス・スパイス・トマトで牛肉をマリネ","ko":"레몬그라스와 토마토 소스로 소고기 재우기"},"instruction":{"zh-TW":"牛肋條切成 3.5 公分方塊。加入細香茅碎、蒜末、魚露 2 大匙、番茄膏 2 大匙、胭脂樹紅油、五香粉與糖拌勻，抓醃 25 分鐘讓紅亮色澤與辛香精油滲透肉纖維。","en":"Cut beef into generous 3.5cm cubes. Toss with minced lemongrass, garlic, 2 tbsp fish sauce, 2 tbsp tomato paste, annatto oil, five-spice powder, and sugar. Marinate for 25 mins to allow aromatics to infuse deeply.","vi":"Thái thịt bò thành từng khối vuông quân cờ 3.5cm. Cho sả băm, tỏi, 2 thìa nước mắm, sốt cà chua, dầu điều, ngũ vị hương và đường vào bóp đều tay trong 25 phút.","ja":"牛肉を大きめの3.5cm角に切ります。みじん切りレモングラス、ニンニク、ヌクマム大さじ2、トマトペースト、アナトー油、五香粉、砂糖を揉み込み、25分寝かせます。","ko":"소고기를 큼직한 3.5cm 크기로 썹니다. 다진 레몬그라스, 마늘, 피시소스 2큰술, 토마토 페이스트, 안나토유, 오향분, 설탕을 넣고 25분간 재워둡니다."},"durationSeconds":180,"image":"/images/vn/bo-kho-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"高溫爆炒鎖住肉汁與激發八角肉桂香","en":"Sear Marinated Beef & Toast Whole Spices","vi":"Xào săn thịt bò dậy mùi hoa hồi quế sả","ja":"牛肉を強火で炒めて肉汁を閉じ込め・スパイスを香らせる","ko":"센 불에서 소고기 볶아 육즙 가두기 및 향신료 볶기"},"instruction":{"zh-TW":"燉鍋中大火熱油，放入八角、肉桂棒與拍扁的香茅段爆香 1 分鐘。倒入醃好的牛肉大塊大火翻炒 4-5 分鐘，直到表面焦香上色並鎖住肉汁。","en":"Heat 1 tbsp oil in a heavy Dutch oven over high heat. Sauté star anise, cinnamon stick, and bruised lemongrass stalks for 1 min until fragrant. Add marinated beef chunks and sear vigorously for 4-5 mins until richly browned.","vi":"Đun nóng dầu ăn trong nồi lớn trên lửa to, thả hoa hồi, quế và sả đập dập vào phi thơm trong 1 phút. Trút thịt bò đã ướp vào xào đảo mạnh tay trong 4-5 phút cho thịt săn chắc và lên màu cánh gián.","ja":"鍋に油を強火で熱し、八角、シナモン、叩いたレモングラスを1分炒めて香りを立たせます。牛肉を投入し、表面にしっかり焼き色がつくまで4〜5分強火で炒め合わせます。","ko":"냄비에 기름을 두르고 팔각, 시나몬스틱, 으깬 레몬그라스를 1분간 볶아 향을 냅니다. 고기를 넣고 겉면이 노릇해질 때까지 4~5분간 강하게 볶아냅니다."},"durationSeconds":240,"image":"/images/vn/bo-kho-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"注入椰子水慢火燜燉至牛筋軟糯","en":"Simmer with Coconut Water until Tender & Add Carrots","vi":"Ninh mềm với nước dừa tươi & cho cà rốt hầm cùng","ja":"ココナッツウォーターで弱火煮込み・人参投入","ko":"코코넛 워터를 붓고 은근히 조리기 및 당근 투하"},"instruction":{"zh-TW":"倒入 400ml 純椰子水與 400ml 清水，大火煮沸後轉最小火。蓋上鍋蓋慢燉 45 分鐘，此時牛腩已非常軟爛。放入滾刀塊紅蘿蔔，繼續小火慢燉 15 分鐘，直到紅蘿蔔香甜軟糯，湯汁濃稠紅潤。","en":"Pour in 400ml coconut water and 400ml water. Bring to a boil, then cover and drop heat to a gentle simmer for 45 mins until beef is meltingly tender. Add carrot chunks, simmering 15 more mins until carrots are fork-tender and sauce is thick and glossy.","vi":"Đổ 400ml nước dừa xiêm tươi và 400ml nước lọc vào nồi. Đun sôi rồi đậy vung hạ lửa nhỏ nhất ninh trong 45 phút cho thịt bò mềm rục. Cho cà rốt vào ninh tiếp 15 phút đến khi cà rốt chín mềm ngọt nước và nước sốt sánh mịn.","ja":"ココナッツウォーター400mlと水400mlを注ぎ、沸騰したら極弱火に落としてフタをし、45分じっくり煮込みます。牛肉が柔らかくなったら乱切り人参を加え、さらに15分煮込んでスープにとろみをつけます。","ko":"코코넛 워터 400ml와 물 400ml를 붓고 끓어오르면 뚜껑을 덮고 약불에서 45분간 뭉근하게 끓입니다. 고기가 부드러워지면 당근을 넣고 15분 더 끓여 국물이 걸쭉해지도록 완성합니다."},"durationSeconds":3600,"image":"/images/vn/bo-kho-step3.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"High Pressure: 25 mins + Natural Release","instructionOverride":{"zh-TW":"【電子壓力鍋極速版】：在 Sauté 模式炒香香料與牛肉後，倒入椰子水與清水。放入紅蘿蔔塊，設定「High Pressure」高壓 25 分鐘。洩壓開蓋，牛腱牛筋入口即化，比傳統燉煮節省一倍時間！","en":"【Instant Pot Method】: Sauté spices and beef directly in the pot. Add liquids and carrots. Cook on High Pressure for 25 mins, followed by natural release. Melt-in-your-mouth perfection in half the time!","vi":"【Nồi áp suất điện】: Xào săn thịt ở chế độ Sauté, cho nước dừa, nước lọc và cà rốt vào. Nấu High Pressure trong 25 phút. Xả van tự nhiên, thịt gân mềm nhừ thơm phức.","ja":"【電気圧力鍋時短モード】：Sautéモードで肉を炒めた後、水分と人参を入れて高圧25分。自然減圧でフタを開ければ、牛すじがトロトロに！","ko":"【인스턴트팟 고속 모드】：Sauté 모드로 볶은 뒤 수분과 당근을 넣고 고압 25분 조리 후 자연 감압합니다. 스지가 젤리처럼 부드러워집니다."}}]},{"stepNumber":4,"title":{"zh-TW":"撒上香菜九層塔，配酥脆法包撕扯沾汁","en":"Garnish with Basil & Tear Crisp Baguette to Dip","vi":"Rắc húng quế ngò gai & xé bánh mì nóng giòn chấm đẫm","ja":"バジルとパクチーを散らし・焼きたてバゲットに浸して食べる","ko":"바질과 고수 얹고 바삭한 바게트를 소스에 푹 적셔 먹기"},"instruction":{"zh-TW":"將濃郁紅亮的紅燴牛腩盛入深碗中，表面撒上切碎的九層塔、洋蔥絲與少許黑胡椒。旁邊放上剛烤出爐、熱騰騰酥脆的越式法包。用雙手撕開酥脆麵包，將蓬鬆的麵包心按入濃郁香茅牛肉湯汁中，吸飽醬汁送入口中，暖心暖胃！","en":"Ladle the fragrant, brick-red stew into deep bowls, garnished with Thai basil leaves, thin onion ribbons, and fresh black pepper. Serve with fresh, piping-hot crusty baguettes. Tear off a piece of bread and plunge it deeply into the rich, aromatic stew. Pure Vietnamese culinary bliss!","vi":"Múc bò kho nâu đỏ sánh ngậy ra tô, rắc lá húng quế tươi, hành tây chẻ sợi và hạt tiêu đen. Dọn kèm những ổ bánh mì mới nướng giòn rụm. Dùng tay xé miếng bánh mì nóng hổi, chấm ngập vào bát sốt bò kho thơm lừng mùi sả quế, cắn một miếng ngon ngất ngây!","ja":"熱々の深紅のシチューを深皿に盛り付け、バジル、オニオンスライス、黒胡椒を散らします。トーストしたてのパリパリフランスパンをちぎり、濃厚なスープにたっぷり浸して召し上がれ！","ko":"걸쭉하고 붉은 비프 스튜를 볼에 담고 타이바질과 양파채, 후추를 얹습니다. 갓 구운 따끈따끈한 바게트를 곁들입니다. 바게트를 손으로 뜯어 진한 소스에 푹 찍어 드셔보세요!"},"durationSeconds":60,"image":"/images/vn/bo-kho-step4.jpg"}],"troubleshooting":[{"id":"bo-kho-tough-meat","problem":{"zh-TW":"牛腩燉煮時間到了還是硬韌咬不動，牛筋沒有軟糯","en":"Beef cubes are still tough and tendon has not softened","vi":"Thịt bò vẫn còn dai ngoách, gân bò chưa mềm nhừ","ja":"時間が経っても肉や牛すじが硬くて噛み切れない","ko":"조리 시간이 지났는데도 고기와 스지가 질겨요"},"cause":{"zh-TW":"火候開太大湯汁蒸發太快，或者使用的是高結締組織的牛腱肉但燉煮時間不足。","en":"Heat was too high causing liquids to boil off too fast, or high-collagen cut needed more simmer time.","vi":"Đun lửa quá to cạn nước nhanh, hoặc bắp bò gân cần thêm thời gian ninh nhừ.","ja":"火力が強すぎて水分が先に蒸発したか、筋膜の多い部位で時間が足りなかった。","ko":"불이 너무 세서 국물이 졸아들었거나 콜라겐이 많은 부위라 시간이 더 필요하기 때문입니다."},"solution":{"zh-TW":"補入半碗溫水或椰子水，轉最微小的火加蓋燜煮 20-30 分鐘，或直接放入電子壓力鍋壓 15 分鐘，牛筋膠原蛋白在 85°C 慢燉下會徹底軟化成凍狀。","en":"Add 1/2 cup warm coconut water and simmer tightly covered on lowest flame for 20-30 mins, or pressure cook 15 mins.","vi":"Châm thêm nửa bát nước dừa ấm, đậy kín vung đun lửa liu riu thêm 20-30 phút hoặc dùng nồi áp suất.","ja":"ぬるま湯かココナッツ水を足し、極弱火でフタをしてさらに20分煮込むか、圧力鍋を活用してください。","ko":"따뜻한 코코넛 워터를 반 컵 보충하고 약불에서 뚜껑을 덮고 20~30분 더 끓이거나 압력솥을 활용하세요."}}],"proTips":[{"zh-TW":"隔夜更美味的魔力燉肉：Bò Kho 屬於「隔夜神菜」！煮好當天放涼冷藏一晚，隔天重新微火加熱，八角、肉桂與香茅的深層精油會完全滲透進每一絲牛肉纖維，湯頭濃郁度翻倍！","en":"Overnight stew magic: Bò Kho tastes 10x better the next day! Chilling overnight allows the complex lemongrass and star anise oils to thoroughly penetrate every fiber of the beef.","vi":"Bí mật ngon hơn vào ngày hôm sau: Bò kho để qua đêm trong tủ lạnh rồi hâm nóng lại sẽ đậm đà hơn gấp bội phần, khi các tầng hương thơm của quế hồi sả đã ngấm sâu vào từng thớ thịt.","ja":"翌日の魔法：ボーコーは一晩寝かせると格段に美味しくなります！スパイスの香味が肉の奥深くまで浸透し、味が驚くほどまろやかにまとまります。","ko":"하루 숙성의 마법: 보코는 만든 다음 날 먹으면 10배 더 맛있습니다! 하룻밤 두면 레몬그라스와 팔각의 깊은 향이 고기 속까지 배어들어 감칠맛이 폭발합니다."}]},{"country":"vn","id":"canh-chua","slug":"canh-chua","title":{"zh-TW":"湄公河三角洲越式酸辣鮮魚湯","en":"Mekong Sweet & Sour Tamarind Fish Soup (Canh Chua Cá)","vi":"Canh Chua Cá Lóc Miền Tây","ja":"メコン風 タマリンドと鮮魚の甘酸っぱいスープ（カイン・チュア）","ko":"메콩델타 정통 타마린드 생선 새콤달콤 맑은 탕 (까인추아)"},"subtitle":{"zh-TW":"熱帶羅望子天然果酸・鮮鳳梨與秋葵・象耳梗海綿吸汁・炸蒜酥爆香","en":"Tamarind Broth with Fresh Fish, Pineapple, Okra, Elephant Ear Stem & Fried Garlic","vi":"Vị chua thanh mát của me chín, dứa thơm, bạc hà giòn xốp, rắc tỏi phi vàng rộm","ja":"タマリンドの爽やかな酸味とパイナップルの甘み・ハスイモと揚げニンニク","ko":"타마린드의 상큼한 과일 산미와 파인애플, 토란대(박하), 바삭한 마늘 플레이크"},"tagline":{"zh-TW":"湄公河水鄉家庭餐桌的終極靈魂，酸、甜、鮮、辣一氣呵成的開胃解暑神湯","en":"The beloved soothing heartbeat of the southern waterways—balancing fruity tartness, sweetness, and fresh river bounty","vi":"Hương đồng gió nội miền sông nước, giải nhiệt ngày hè đậm đà khó quên","ja":"南国メコンの家庭の味。タマリンドのまろ快な酸味と魚の旨味が染み渡る癒やしのスープ","ko":"베트남 남부 가정식의 정수, 무더위를 한 번에 날려주는 새콤달콤하고 개운한 생선탕"},"heroImage":"/images/vn/canh-chua.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":15,"defaultServings":4,"caloriesPerServing":280,"category":"soupsStews","dietaryTags":["classic","pescatarian","glutenFree"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"南部・湄公河三角洲水鄉 (Đồng bằng sông Cửu Long)","en":"Southern Vietnam / Mekong Delta River Basin","vi":"Miền Tây Nam Bộ / Sông nước Cửu Long","ja":"南部・メコンデルタ水郷地帯","ko":"베트남 남부 / 메콩델타 수향"},"famousStreetMarkets":[{"zh-TW":"芹苴水上集市 (Chợ Nổi Cái Răng)","en":"Cai Rang Floating Market (Can Tho)","vi":"Chợ Nổi Cái Răng","ja":"カイラン水上マーケット","ko":"껀터 카이랑 수상시장"},{"zh-TW":"西貢第八郡水岸大排檔","en":"Saigon Waterfront Canal Restaurants","vi":"Quán ăn bờ kênh Sài Gòn","ja":"サイゴン運河沿い屋台","ko":"호찌민 운하변 포장마차"}],"historyStory":{"zh-TW":"在湄公河九龍江縱橫交錯的水道中，每逢雨季河水暴漲，水岸人家便會撈起鮮活的黑魚 (Cá lóc) 或鯰魚，採摘河畔野生的熟羅望子、菠蘿、秋葵與吸水性極強的「象耳梗 (Bạc hà / 芋梗)」。這道湯將熱帶水果酸甜與河鮮精準平衡，最後一定要撒上炸得焦黃的蒜酥 (Tỏi phi) 與切碎的刺芹，是全東南亞最解熱生津的湯品。","en":"Along the labyrinthine waterways of the Mekong Delta, families harvest sweet river snakehead fish or catfish alongside ripe wild tamarind, pineapples, okra, and spongy elephant ear stems (Bạc hà). The soup achieves a thrilling balance between fruit acidity and rich fish stock, crowned with crispy golden fried garlic and sawtooth herb.","vi":"Canh chua là bản hòa ca của sản vật thiên nhiên hào sảng miền Tây Nam Bộ. Cá lóc đồng tươi roi rói nấu cùng nước cốt me chín chua dịu, lát dứa chua ngọt, quả đậu bắp xanh mướt và những khúc bạc hà xốp mềm hút đẫm nước canh, thơm nức mũi mùi tỏi phi giòn và ngò gai.","ja":"メコン川水系の豊かな恵みから生まれた家庭料理。熟したタマリンドの果実酸にパイナップルの自然な甘み、スープをたっぷり吸い込むハスイモ（象耳茎）を合わせ、仕上げに香ばしい揚げニンニクを散らします。","ko":"메콩델타의 풍요로운 자연산 생선과 열대 과일이 어우러진 전통 국물 요리입니다. 익은 타마린드의 부드러운 산미에 파인애플, 토란대 줄기가 국물을 흠뻑 머금어 국물 한 모금에 온몸이 개운해집니다."},"vietScript":"Canh Chua Cá","vietPhonetics":"Kahn Chu-ah Cah","audioPronunciationText":"Cho tôi một tô canh chua cá lóc nhiều bạc hà giá đỗ!"},"ingredients":[{"id":"fresh-fish","name":{"zh-TW":"鮮魚排或鮮鱸魚塊 (去骨切厚塊)","en":"Fresh White Fish Fillets (Sea Bass, Catfish or Halibut)","vi":"Cá lóc hoặc cá basa tươi cắt khúc","ja":"白身魚（スズキまたはパンガシウス・厚切り）","ko":"신선한 흰살 생선 (농어 또는 메기, 대구)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"vietName":"Cá tươi","vietPronunciation":"Cah Teu-oy"},{"id":"tamarind-pulp","name":{"zh-TW":"越式熟羅望子膏 (溫水泡開取酸汁)","en":"Ripe Tamarind Paste / Pulp (Dissolved in warm water)","vi":"Vắt me chua chín nấu canh","ja":"タマリンドペースト（お湯で溶いて果汁を取る）","ko":"타마린드 페이스트 (미온수에 풀어 즙을 낸 것)"},"amount":2.5,"unitMetric":"tbsp","unitUS":"2.5 tbsp","isKeyFlavor":true,"vietName":"Nước cốt me chua","vietPronunciation":"Neu-oc Coht Meh"},{"id":"fresh-pineapple","name":{"zh-TW":"新鮮鳳梨切片 (提供天然果香甜味)","en":"Fresh Pineapple (Sliced triangles)","vi":"Dứa / Thơm thái lát","ja":"生パイナップル（スライス）","ko":"신선한 파인애플 슬라이스"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"vietName":"Dứa / Thơm","vietPronunciation":"Zeuh / Toh-m"},{"id":"elephant-ear-stem","name":{"zh-TW":"象耳梗 / 芋梗 (Bạc hà 海綿狀吸汁蔬菜)","en":"Elephant Ear Stems (Bạc Hà / Taro Stem slices)","vi":"Cây bạc hà (dọc mùng) tước vỏ thái vát","ja":"ハスイモの茎（スープを吸うスポンジ野菜）","ko":"토란대 줄기 / 박하 (스펀지처럼 국물을 머금는 채소)"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"vietName":"Cây bạc hà (dọc mùng)","vietPronunciation":"Bahk Hah"},{"id":"fresh-okra","name":{"zh-TW":"新鮮秋葵與鮮番茄切塊","en":"Fresh Okra (Sliced diagonally) & Ripe Tomatoes","vi":"Đậu bắp cắt xéo & cà chua bổ múi cau","ja":"オクラ斜め切り＆完熟トマト角切り","ko":"어슷 썬 오크라 및 토마토"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","vietName":"Đậu bắp, cà chua","vietPronunciation":"Doh Bahp"},{"id":"fried-garlic-crisps","name":{"zh-TW":"現炸金黃蒜酥 (Tỏi phi 靈魂香氣起鍋必放)","en":"Golden Crispy Fried Garlic (Tỏi Phi - essential topper)","vi":"Tỏi phi vàng rộm thơm lừng","ja":"カリカリ揚げニンニク（トッピングの必須アイテム）","ko":"바삭하게 튀겨낸 황금 마늘 플레이크 (토이피)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"vietName":"Tỏi phi vàng","vietPronunciation":"Toy Fee"},{"id":"rice-paddy-herb","name":{"zh-TW":"刺芹 (Ngò gai) 與白花菜 / 水芙蓉香草 (Ngò ôm)","en":"Sawtooth Culantro & Rice Paddy Herb (Ngò Ôm with citrus cumin note)","vi":"Ngò gai & rau ngò ôm thái nhỏ","ja":"オオバコエンドロ＆シソクサ（ンゴ・オム）","ko":"쿨란트로 및 벼이삭 허브 (응오옴)"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Rau ngò ôm ngò gai","vietPronunciation":"Naw Ohm, Naw Guy"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"萃取羅望子果酸水與炒香番茄鳳梨","en":"Extract Tamarind Juice & Sauté Pineapple & Tomatoes","vi":"Dầm me lấy nước cốt & xào thơm dứa cà chua","ja":"タマリンド果汁の抽出とパイナップル・トマトのソテー","ko":"타마린드 즙 짜내기 및 파인애플 토마토 볶기"},"instruction":{"zh-TW":"在小碗中將熟羅望子膏加入 150ml 溫熱水，用湯匙搗碎壓出酸汁，過濾出果肉果酸水備用。湯鍋熱少許油，下蒜末、鳳梨片與番茄塊翻炒 2 分鐘，激發果香甜酸汁液。","en":"Mash tamarind pulp in 150ml warm water with a spoon to release the tart amber nectar; strain and discard solids. In a pot, heat 1 tsp oil, sauté minced garlic, pineapple slices, and tomatoes for 2 mins until fragrant.","vi":"Dầm me chín trong 150ml nước ấm cho tan hết thịt me, lọc qua rây lấy phần nước cốt chua. Đun nóng chút dầu trong nồi, phi thơm tỏi rồi trút dứa và cà chua vào xào đều 2 phút cho dậy mùi thơm chua ngọt.","ja":"タマリンドペーストをお湯150mlで溶かし、スプーンで潰して濾します。鍋に油を熱し、ニンニク、パイナップル、トマトを2分炒めて果汁の旨味を引き出します。","ko":"타마린드를 미온수 150ml에 넣고 숟가락으로 으깨어 상큼한 과즙을 걸러냅니다. 냄비에 기름을 두르고 마늘, 파인애플, 토마토를 2분간 볶아 달콤한 과일 향을 냅니다."},"durationSeconds":180,"image":"/images/vn/canh-chua-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"注入清湯滾煮鮮魚塊至恰到好處嫩滑","en":"Simmer Fish in Tamarind Broth until Succulent","vi":"Đổ nước nấu sôi, nêm nước cốt me & cho cá vào nấu chín tới","ja":"タマリンドスープを煮立て・鮮魚をサッと煮る","ko":"타마린드 육수를 붓고 생선을 부드럽게 익히기"},"instruction":{"zh-TW":"向鍋中注入 1 公升清水與羅望子酸汁，加入 2.5 大匙魚露、2 大匙砂糖調成標準湄公河酸甜味。大火煮沸後輕輕滑入厚切鮮魚塊，微火滾煮 4-5 分鐘至魚肉剛熟嫩白（切勿大力攪拌以免魚肉碎散）。","en":"Add 1L water and the tamarind juice to the pot. Season with 2.5 tbsp fish sauce and 2 tbsp sugar for that classic sweet-sour balance. Bring to a rolling boil, slide in fresh fish fillets gently, and simmer on low for 4-5 mins until just tender.","vi":"Rót 1 lít nước lọc và nước cốt me vào nồi. Nêm 2.5 thìa nước mắm ngon và 2 thìa đường cho vừa vị chua ngọt đậm đà. Đun sôi bùng, nhẹ nhàng thả từng khúc cá tươi vào nấu nhỏ lửa 4-5 phút cho cá chín mềm mướt (không đảo mạnh tránh nát cá).","ja":"水1Lとタマリンド果汁を鍋に注ぎ、ヌクマム大さじ2.5、砂糖大さじ2を加えて甘酸っぱく調味します。沸騰したら白身魚を優しく滑り込ませ、弱火で4〜5分身がふっくらするまで煮ます。","ko":"물 1L와 타마린드 즙을 붓습니다. 피시소스 2.5큰술, 설탕 2큰술을 넣어 새콤달콤한 간을 맞춥니다. 끓어오르면 생선을 조심스럽게 넣고 약불에서 4~5분간 부드럽게 익힙니다."},"durationSeconds":300,"image":"/images/vn/canh-chua-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"放入秋葵、象耳梗海綿吸汁蔬菜","en":"Add Okra, Elephant Ear Stems & Bean Sprouts","vi":"Thả đậu bắp, bạc hà & giá đỗ giòn mát","ja":"オクラ・ハスイモ・もやしを投入して一煮立ち","ko":"오크라와 토란대, 숙주를 넣고 살짝 끓이기"},"instruction":{"zh-TW":"魚肉熟透後，下斜切秋葵、切片象耳梗 (Bạc hà) 與一大把綠豆芽。繼續煮 1-2 分鐘，象耳梗的海綿微孔會瞬間吸飽酸甜魚湯，口感脆嫩多汁，立即熄火！","en":"Once fish is cooked, scatter in sliced okra, elephant ear stems, and crisp bean sprouts. Simmer for 1-2 mins only—the spongy stems soak up the tart broth while staying miraculously crunchy. Turn off heat immediately.","vi":"Khi cá đã chín, thả đậu bắp cắt xéo, bạc hà thái vát và giá đỗ tươi vào. Đun sôi thêm 1-2 phút cho bạc hà hút đẫm nước canh chua mà vẫn giữ trọn độ giòn sần sật rồi tắt bếp ngay.","ja":"魚に火が通ったら、斜め切りのオクラ、ハスイモ、もやしを一気に入れます。1〜2分だけサッと煮て、ハスイモがスープを吸ってシャキシャキの状態で火を止めます。","ko":"생선이 익으면 오크라, 어슷 썬 토란대 줄기, 숙주를 넣습니다. 딱 1~2분만 살짝 끓여 스펀지 같은 토란대가 국물을 흠뻑 머금고 아삭할 때 불을 끕니다."},"durationSeconds":120,"image":"/images/vn/canh-chua-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"鋪滿金黃蒜酥與刺芹香草起鍋","en":"Ladle into Bowl, Crown with Crispy Fried Garlic & Herbs","vi":"Múc ra tô rắc đẫm tỏi phi vàng & ngò ôm thơm ngát","ja":"器に盛り付け・香ばしい揚げニンニクとハーブを散らして完成","ko":"그릇에 담고 바삭한 마늘 플레이크와 허브 듬뿍 얹기"},"instruction":{"zh-TW":"將熱湯盛入大碗中。表面撒上切碎的刺芹 (Ngò gai)、白花香草 (Ngò ôm)、幾圈生辣椒圈，最後關鍵：豪邁撒上 2 大匙香脆金黃蒜酥 (Tỏi phi)！蒜酥接觸熱湯發出滋滋微響，蒜香與果酸交織，附上一碟新鮮朝天椒純魚露沾魚肉，配熱白飯享用！","en":"Ladle steaming soup into a deep bowl. Garnish with chopped culantro, rice paddy herbs, and sliced chilies. Crown decisively with 2 tbsp golden crispy fried garlic (tỏi phi). Serve with a side saucer of pure fish sauce with fresh chili slices to dip the tender fish chunks, alongside steamed rice!","vi":"Múc canh chua nóng hổi ra tô lớn. Rắc ngò gai, ngò ôm thái nhỏ, vài lát ớt hiểm đỏ và bước quyết định: Rắc ngập 2 thìa tỏi phi vàng rộm lên trên! Dọn kèm chén nước mắm nguyên chất thả ớt tươi để chấm từng miếng cá béo ngọt cùng cơm trắng.","ja":"大きなボウルに注ぎます。刻んだハーブと輪切り唐辛子を散らし、仕上げにたっぷりの揚げニンニク（トイ・フィ）をトッピング！白身魚をつけるための生唐辛子入り生ヌクマムの小皿と、白ご飯を添えて完成です。","ko":"큰 볼에 담고 쿨란트로와 칠리를 얹은 뒤, 바삭한 마늘 플레이크(토이피)를 듬뿍 뿌려줍니다. 생선을 찍어 먹을 생고추 띄운 피시소스 종지와 따뜻한 밥을 곁들여 드세요!"},"durationSeconds":60,"image":"/images/vn/canh-chua-step4.jpg"}],"troubleshooting":[{"id":"canh-chua-mushy-fish","problem":{"zh-TW":"魚肉煮散爛成碎末，湯色渾濁且有腥味","en":"Fish fell apart into mushy flakes and broth tastes fishy","vi":"Cá bị nát bét vụn ra nước, canh bị tanh","ja":"魚の身が崩れてボロボロになり、スープが生臭くなってしまった","ko":"생선 살이 부서져 국물이 지저분해지고 비린내가 나요"},"cause":{"zh-TW":"下魚時水溫不夠滾沸，或者下魚後大力攪拌把魚肉翻爛。","en":"Water was not boiling when fish was added, or stirred too aggressively.","vi":"Thả cá khi nước chưa sôi bùng, hoặc lấy đũa đảo mạnh tay.","ja":"スープが沸騰していない段階で魚を投入したか、お玉で激しくかき混ぜた。","ko":"물이 펄펄 끓지 않을 때 생선을 넣었거나 숟가락으로 심하게 저었기 때문입니다."},"solution":{"zh-TW":"湯水必須在大滾時才輕輕滑入魚肉，高溫能瞬間凝固魚肉表面蛋白鎖住鮮甜。下魚後轉小火，全程不可用勺子大力翻動！","en":"Slide fish in only at a vigorous boil to sear the surface proteins. Lower heat and do not stir vigorously.","vi":"Nước phải thật sôi mới thả cá vào để bề mặt cá se lại, hạ nhỏ lửa và không khuấy.","ja":"グラグラと沸騰している熱湯に滑り込ませてタンパク質を固め、その後は弱火にしてかき混ぜないのが鉄則です。","ko":"국물이 세차게 끓을 때 생선을 넣어 표면을 굳히고, 약불로 줄인 뒤에는 절대 휘젓지 마세요."}}],"proTips":[{"zh-TW":"神仙點睛之筆——「炸蒜酥 (Tỏi phi)」：湄公河酸辣湯的靈魂秘密在於最後撒上的金黃蒜酥！酥脆焦香的熟蒜油在酸甜湯頭中散開，能瞬間中和羅望子過銳的酸度，讓整碗湯散發極致甘醇的香氣！","en":"Culinary soul of the soup: The crispy fried garlic (Tỏi phi) is non-negotiable! The nutty caramelized garlic oils melt into the tart tamarind broth, softening sharp edges into pure velvety heaven.","vi":"Bí mật thăng hoa hương vị: Canh chua miền Tây không thể thiếu tỏi phi vàng rộm! Lớp tỏi phi béo thơm ngậy khi thả vào nước canh chua sẽ làm dịu đi vị gắt của me, tạo nên dư vị đậm đà ngây ngất.","ja":"味の決め手：カインチュアの命は最後の「揚げニンニク（トイ・フィ）」にあります！ニンニクの香ばしさと油分がタマリンドの強い酸味をまろやかに包み込み、極上のコクをもたらします。","ko":"신의 한 수: 메콩 생선탕의 완성은 바로 ‘바삭한 마늘 플레이크(토이피)’입니다! 고소한 마늘 기름이 타마린드의 날카로운 산미를 부드럽게 감싸주어 깊은 감칠맛을 완성합니다."}]},{"country":"vn","id":"banh-trang-nuong","slug":"banh-trang-nuong","title":{"zh-TW":"大叻夜市「越南披薩」(炭烤米紙煎餅)","en":"Da Lat Street \"Vietnamese Pizza\" (Bánh Tráng Nướng)","vi":"Bánh Tráng Nướng Đà Lạt (Pizza Việt Nam)","ja":"ダラット夜市名物「ベトナム風ピザ」（バイン・チャン・ヌオン）","ko":"달랏 야시장 명물 ‘베트남식 피자’ (반짱느엉)"},"subtitle":{"zh-TW":"炭火酥脆薄米紙・鵪鶉蛋滑嫩・乾蝦米肉鬆・香濃笑牛起司與是拉差辣醬","en":"Grilled Rice Paper with Quail Eggs, Dried Shrimp, Pork Floss, Cheese & Sriracha","vi":"Bánh tráng nướng than hoa giòn tan, trứng cút, tép khô, chà bông, phô mai béo ngậy","ja":"炭火で焼くパリパリのライスペーパー・うずら卵と干しエビ・チーズとシラチャーソース","ko":"숯불에 구워 바삭한 라이스페이퍼, 메추리알, 건새우, 돼지고기 포(차봉), 치즈와 스리라차"},"tagline":{"zh-TW":"涼爽大叻山城夜市的第一排隊神話，酥脆爆香、滿嘴拉絲的極致街頭撫慰","en":"The ultimate night market street sensation from the cool mountain town of Da Lat","vi":"Món ăn vặt đường phố hot nhất xứ sở sương mù, thơm giòn nóng hổi giữa đêm se lạnh","ja":"避暑地ダラットの夜市を熱狂させる屋台フード。炭火の香ばしさととろけるチーズが絶品","ko":"선선한 달랏 고원 야시장의 최고 인기 길거리 간식, 바삭함과 고소함의 극치"},"heroImage":"/images/vn/banh-trang-nuong.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":5,"defaultServings":2,"caloriesPerServing":280,"category":"rollsSnacks","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"中央高原・大叻避暑山城 (Đà Lạt)","en":"Central Highlands / Da Lat Mountain Town","vi":"Tây Nguyên / Thành phố sương mù Đà Lạt","ja":"中央高地・ダラット山岳高原","ko":"베트남 중부 고원 / 달랏"},"famousStreetMarkets":[{"zh-TW":"大叻夜市階梯攤販 (Chợ Đêm Đà Lạt)","en":"Da Lat Night Market Steps","vi":"Chợ Đêm Đà Lạt","ja":"ダラット夜市の階段広場","ko":"달랏 야시장 계단 노점"},{"zh-TW":"春香湖周邊小吃車 (Hồ Xuân Hương)","en":"Xuan Huong Lake Street Carts","vi":"Bờ hồ Xuân Hương","ja":"スアンフーン湖畔","ko":"쑤언흐엉 호수 주변"}],"historyStory":{"zh-TW":"大叻位於海拔 1500 公尺的高原，入夜後氣候清涼甚至帶有寒意。當地攤販在炭火爐前擺出小矮凳，將薄米紙放在炭火鐵網上烘烤，打入鵪鶉蛋、刷上奶油與青蔥，撒上小蝦米、豬肉鬆、香腸丁與笑牛起司 (Laughing Cow Cheese)，最後淋滿美乃滋與是拉差辣醬，對折切塊趁熱吃，外國背包客戲稱為「Vietnamese Pizza (越南披薩)」。","en":"Perched at 1,500 meters altitude, Da Lat gets surprisingly chilly at night. Street vendors set up portable charcoal grills along market stairs, toasting round rice paper over glowing embers while cracking tiny quail eggs on top. Slathered with Laughing Cow cheese, scallion oil, dried baby shrimp, pork floss, mayo, and sriracha, it was crowned ‘Vietnamese Pizza’ by delighted global travelers.","vi":"Đà Lạt se lạnh về đêm là nơi sản sinh ra món bánh tráng nướng trứ danh. Ngồi bên bếp than hồng ấm áp, người bán thoăn thoắt quết bơ, đập 2 quả trứng cút, rải hành lá, tép khô, xúc xích và miếng phô mai Con Bò Cười béo ngậy lên chiếc bánh tráng mỏng. Khi vỏ bánh vàng rộm giòn tan, rưới sốt mayonnaise và tương ớt cay nồng, gấp đôi lại cắn một miếng sướng rơn người.","ja":"標高1500mの高地に位置し、夜になると冷え込むダラット。屋台の炭火網の上でライスペーパーを炙り、うずら卵、ネギ、干しエビ、豚肉のデンブ、そしてベトナムで大人気の「笑う牛」チーズを乗せて焼き上げます。外国人観光客から「ベトナム風ピザ」と呼ばれ大ブームに。","ko":"해발 1500m 고원 도시 달랏의 쌀쌀한 밤바람 속에서 탄생한 최고의 길거리 음식입니다. 숯불 석쇠 위에 라이스페이퍼를 올리고 메추리알, 치즈, 파, 건새우를 올려 구워내어 ‘베트남식 피자’로 불립니다."},"vietScript":"Bánh Tráng Nướng Đà Lạt","vietPhonetics":"Bahn Trahng Neu-ong Dah Laht","audioPronunciationText":"Cho tôi hai cái bánh tráng nướng nhiều phô mai cay cay!"},"ingredients":[{"id":"thick-rice-paper","name":{"zh-TW":"越式大張厚米紙 (專門烤煎餅用，直徑 22cm)","en":"Vietnamese Grilling Rice Paper Wrappers (22cm)","vi":"Bánh tráng dày chuyên nướng than","ja":"ベトナム厚手ライスペーパー（焼き用）","ko":"구이 전용 두툼한 라이스페이퍼"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Bánh tráng nướng","vietPronunciation":"Bahn Trahng Neu-ong"},{"id":"quail-eggs","name":{"zh-TW":"新鮮鵪鶉蛋 (每張餅 2-3 顆，或雞蛋半顆)","en":"Fresh Quail Eggs (2-3 per piece, or 1/2 chicken egg)","vi":"Trứng cút tươi (hoặc trứng gà)","ja":"うずらの生卵（または鶏卵）","ko":"신선한 메추리알 (또는 달걀)"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Trứng cút","vietPronunciation":"Teu-ong Koot"},{"id":"dried-baby-shrimp","name":{"zh-TW":"越式炒香橘紅小蝦米 (Tép khô 鹹香脆口)","en":"Vietnamese Seasoned Dried Red Baby Shrimp (Tép khô)","vi":"Tép sấy khô màu đỏ cam giòn thơm","ja":"ベトナム産 干し小エビ（味付け）","ko":"양념 볶음 건새우 (텝코)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"vietName":"Tép khô sấy","vietPronunciation":"Tehp Koh"},{"id":"pork-floss","name":{"zh-TW":"越式豬肉鬆 (Chà bông / Ruốc 鹹香甘甜)","en":"Pork Floss (Chà bông / Ruốc)","vi":"Chà bông heo (ruốc thịt)","ja":"豚肉のデンブ（肉鬆 / チャー・ボン）","ko":"돼지고기 육포 보푸라기 (차봉)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"vietName":"Chà bông heo","vietPronunciation":"Chah Bawng"},{"id":"laughing-cow-cheese","name":{"zh-TW":"笑牛牌三角起司或馬茲瑞拉起司 (融化濃郁奶香)","en":"Laughing Cow Cheese Wedges or Mozzarella (For creamy melt)","vi":"Phô mai Con Bò Cười (hoặc phô mai sợi)","ja":"「ラ・ヴァシュ・キ・リ（笑う牛）」チーズまたはとろけるチーズ","ko":"래핑카우 삼각 치즈 또는 모짜렐라 치즈"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Phô mai Con Bò Cười","vietPronunciation":"Foh My"},{"id":"scallion-mayo-chili","name":{"zh-TW":"青蔥碎、奶油、美乃滋、是拉差辣椒醬","en":"Chopped Scallions, Butter, Sweet Mayo & Sriracha Chili Sauce","vi":"Hành lá cắt nhỏ, bơ vàng, sốt mayonnaise, tương ớt","ja":"刻み青ネギ、バター、マヨネーズ、シラチャーチリソース","ko":"다진 쪽파, 버터, 마요네즈, 스리라차 칠리소스"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Hành lá, bơ, tương ớt","vietPronunciation":"Hahn Lah, Baw"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"平底鍋乾烤米紙底殼","en":"Toast Dry Rice Paper on Pan","vi":"Đặt bánh tráng lên chảo khô làm nóng","ja":"油をひかずにフライパンでライスペーパーを軽く炙る","ko":"마른 팬에 라이스페이퍼 올려 살짝 굽기"},"instruction":{"zh-TW":"準備一只大平底不沾鍋，中小火預熱，完全不放油！放上一張乾米紙，用手輕輕旋轉米紙 30 秒使其受熱均勻平整，抹上半小匙軟化黃奶油。","en":"Preheat a dry nonstick skillet over medium-low heat—no oil needed! Lay down a sheet of dry rice paper. Rotate gently with your fingertips for 30 secs to flatten and heat evenly, spreading 1/2 tsp softened butter over the surface.","vi":"Làm nóng chảo chống dính trên lửa vừa nhỏ, tuyệt đối không dùng dầu ăn! Đặt bánh tráng khô vào chảo, dùng tay xoay tròn nhẹ trong 30 giây cho bánh phẳng và nóng đều, phết nửa thìa bơ vàng.","ja":"油をひかずにフライパンを弱火で温めます。ライスペーパーを乗せ、手でクルクルと回しながら30秒均一に温め、表面にバター小さじ1/2を薄く塗ります。","ko":"기름을 두르지 않은 팬을 약불로 달굽니다. 라이스페이퍼를 올리고 손으로 살살 돌려가며 30초간 평평하게 데운 뒤 버터 반 작은술을 바릅니다."},"durationSeconds":60,"image":"/images/vn/banh-trang-nuong-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"打入鵪鶉蛋快速刷散並抹化起司","en":"Crack Quail Eggs & Spread with Cheese Wedges","vi":"Đập trứng cút tán đều & dầm phô mai béo ngậy","ja":"うずら卵を割り入れ手早く塗り広げ・チーズを溶かす","ko":"메추리알 깨 넣고 골고루 펴 바르며 치즈 녹이기"},"instruction":{"zh-TW":"直接在米紙正中間打入 2 顆鵪鶉蛋（或 1 顆打散的雞蛋），撒入切碎青蔥花，放上一塊切碎的笑牛起司。用小湯匙背快速將蛋液、青蔥與起司均勻抹開鋪滿整個米紙表面。蛋液受熱會牢牢黏合配料並烘烤至半凝固！","en":"Crack 2 quail eggs directly into the center. Scatter in chopped scallions and place a wedge of Laughing Cow cheese. Quickly use the back of a spoon to whisk and spread the egg, scallions, and cheese across the entire surface. The egg cooks and forms an adhesive savory crust!","vi":"Đập 2 quả trứng cút trực tiếp vào giữa bánh tráng, rắc hành lá và đặt miếng phô mai Con Bò Cười vào. Dùng lưng thìa nhanh tay đánh tan trứng, tán đều phô mai và hành phủ kín mặt bánh. Trứng gặp nhiệt độ sẽ đông lại giữ chặt các nguyên liệu.","ja":"ライスペーパーの中央にうずら卵2個を割り落とし、刻みネギとチーズを加えます。スプーンの背で素早く全体に薄く塗り広げます。卵に火が通り、チーズがトロリと溶けて全体に行き渡ります。","ko":"라이스페이퍼 가운데 메추리알 2개를 깨 넣고 쪽파와 치즈를 올립니다. 숟가락 등으로 빠르게 펴 발라 피 전면에 골고루 코팅시킵니다. 계란이 익으며 접착제 역할을 합니다."},"durationSeconds":90,"image":"/images/vn/banh-trang-nuong-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"撒上小蝦米肉鬆，淋美乃滋與辣醬","en":"Scatter Shrimp & Pork Floss, Drizzle Mayo & Sriracha","vi":"Rải tép khô, chà bông & rưới sốt mayonnaise tương ớt","ja":"干しエビ・デンブを散らし・マヨとチリソースをかける","ko":"건새우와 고기 포 뿌리고 마요네즈와 칠리소스 두르기"},"instruction":{"zh-TW":"在半凝固的蛋面均勻撒上鹹香紅蝦米 (Tép khô)、蓬鬆豬肉鬆 (Chà bông)。擠上交叉網格狀的甜美乃滋與鮮紅是拉差辣椒醬。保持中小火烘烤，米紙底部會慢慢變成金黃焦脆，散發濃郁炭火米香！","en":"Evenly sprinkle dried baby shrimp (tép khô) and fluffy pork floss (chà bông). Zig-zag generously with sweet mayonnaise and spicy sriracha. Keep heat medium-low until the rice paper bottom turns deeply golden and audibly crackles!","vi":"Rải đều tép sấy khô đỏ rực và chà bông heo tơi xốp khắp mặt bánh. Xịt sốt mayonnaise và tương ớt thành hình zíc zắc đẹp mắt. Giữ lửa nhỏ đến khi đáy bánh tráng chuyển màu vàng rộm, giòn rụm phát ra tiếng lách tách vui tai.","ja":"赤い干しエビとポークデンブを均一に散らします。マヨネーズとシラチャーソースをジグザグにたっぷり回しかけます。弱火で底が黄金色にパリパリになるまでじっくり焼きます。","ko":"붉은 건새우와 폭신한 차봉(고기 포)을 골고루 뿌립니다. 마요네즈와 스리라차 칠리소스를 지그재그로 뿌려줍니다. 약불에서 바닥이 황금빛으로 바삭바삭해질 때까지 굽습니다."},"durationSeconds":90,"image":"/images/vn/banh-trang-nuong-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 180°C (350°F) for 4 mins","instructionOverride":{"zh-TW":"【氣炸鍋大叻披薩版】：在炸籃中放入米紙，打入蛋液抹開並撒上全部配料與起司。180°C 氣炸 4 分鐘，出鍋整張脆如洋芋片！","en":"【Air Fryer Vietnamese Pizza】: Assemble all toppings directly on rice paper inside the basket. Air fry at 180°C (350°F) for 4 mins until bottom is potato-chip crispy!","vi":"【Nồi chiên không dầu】: Cho bánh tráng và xếp đầy đủ topping vào khay. Nướng ở 180°C trong 4 phút, bánh phồng giòn tan như bim bim.","ja":"【ノンフライヤー】：具材を乗せたライスペーパーを入れ、180°Cで4分加熱。ポテトチップスのように軽やかにサクサク！","ko":"【에어프라이어】：재료를 올린 라이스페이퍼를 넣고 180°C에서 4분 조리합니다. 감자칩처럼 놀랍도록 바삭바삭해집니다."}}]},{"stepNumber":4,"title":{"zh-TW":"對折半月形，趁熱喀嚓咬下酥脆流心","en":"Fold in Half & Crunch while Scorching Hot","vi":"Gập đôi bánh tráng & cắn một miếng giòn tan rôm rốp","ja":"半分にパタンと折りたたみ・熱々を豪快にかぶりつく","ko":"반으로 접어 바사삭 뜨거울 때 한 입 베어 물기"},"instruction":{"zh-TW":"用夾子將酥脆的米紙對折成半月形，或捲成圓筒狀起鍋。稍微放涼 30 秒（脆度會在此時達到巔峰），拿在手中一口咬下，外皮如脆餅般咔嚓爆裂，內餡融化起司與蝦米肉鬆鹹甜交織，大叻夜市的絕頂美味！","en":"Use tongs to fold the crispy rice paper in half like a taco. Let rest for 30 secs (crunch reaches peak crispiness as it cools slightly). Bite into the crackling shell—molten cheese, savory shrimp, and spicy mayo explode with street food euphoria!","vi":"Dùng kẹp gập đôi chiếc bánh tráng giòn rụm lại thành hình bán nguyệt. Chờ 30 giây cho bánh nguội nhẹ (độ giòn sẽ đạt đỉnh cao nhất), cầm trên tay cắn một miếng giòn tan vỡ vụn, phô mai béo ngậy tan chảy quyện cùng tép sấy mặn mà!","ja":"トングでパタンと半分に折りたたみます。30秒冷ますとパリパリ感がマックスに！手で持って豪快にかぶりつけば、パリッと弾ける皮の中からとろけるチーズとエビの旨味が溢れ出します！","ko":"집게로 반을 타코처럼 접습니다. 30초 정도 한 김 식히면 바삭함이 최고조에 달합니다. 손으로 들고 한 입 베어 물면 바사삭 부서지는 소리와 함께 치즈와 건새우의 풍미가 입안 가득 번집니다!"},"durationSeconds":30,"image":"/images/vn/banh-trang-nuong-step4.jpg"}],"troubleshooting":[{"id":"banh-trang-burned","problem":{"zh-TW":"米紙底部烤焦發黑，但上面的蛋液還沒熟","en":"Bottom of rice paper burned black while egg on top is still raw","vi":"Đáy bánh tráng bị cháy đen thui nhưng trứng bên trên chưa kịp chín","ja":"底のライスペーパーが真っ黒に焦げたのに、上の卵が生のまま","ko":"바닥은 까맣게 탔는데 위의 계란은 아직 안 익었어요"},"cause":{"zh-TW":"鍋底火候太大，米紙極薄容易在 1 分鐘內燒焦。","en":"Flame was too aggressive. Rice paper burns within seconds on high heat.","vi":"Lửa quá to, bánh tráng rất mỏng nên dễ cháy khét.","ja":"火力が強すぎた。薄い皮は強火だと一瞬で焦げ付きます。","ko":"불이 너무 세서 그렇습니다. 얇은 라이스페이퍼는 센 불에서 금방 탑니다."},"solution":{"zh-TW":"全程務必保持「最小微火」！且剛打入蛋液時就要用湯匙背迅速將蛋液薄薄抹開到整張餅，蛋液越薄受熱越快熟，米紙就不會烤焦。","en":"Use lowest possible heat throughout and spread the egg very thinly with the back of a spoon.","vi":"Luôn giữ lửa nhỏ liu riu và dùng thìa tán lớp trứng thật mỏng đều để trứng chín nhanh.","ja":"常に極弱火を保ち、卵を薄く塗り広げることで素早く火を通します。","ko":"반드시 가장 약한 불을 유지하고, 숟가락으로 계란을 얇게 펴 발라야 타지 않고 금방 익습니다."}}],"proTips":[{"zh-TW":"大叻攤販的神級配料——「笑牛牌三角起司 (Phô mai)」：正宗大叻風味一定會放一塊軟質三角形起司抹開！奶香融化在熱辣辣的是拉差辣椒醬與脆米紙中，創造出不可思議的滑順奶甜層次！","en":"Da Lat street magic: The Laughing Cow cheese wedge (Phô mai Con Bò Cười) is essential! As it melts into spicy sriracha and savory shrimp, it yields an unbelievable creamy gourmet richness.","vi":"Linh hồn bánh tráng Đà Lạt: Nhất định phải có một miếng phô mai Con Bò Cười dầm nhuyễn! Vị béo ngậy tan chảy hòa quyện cùng tương ớt cay nồng tạo nên sự khác biệt đẳng cấp.","ja":"名店の味の決め手：「笑う牛」チーズをしっかり溶かすのがポイント！ピリ辛のシラチャーと濃厚チーズが口の中でとろけ合い、極上のストリートグルメへと昇華します。","ko":"달랏 현지 꿀팁: 래핑카우 삼각 치즈를 으깨어 녹이는 것이 핵심입니다! 매콤한 스리라차와 고소한 치즈가 어우러져 중독성 강한 맛을 자랑합니다."}]},{"country":"vn","id":"cao-lau","slug":"cao-lau","title":{"zh-TW":"會安古鎮特產高樓麵","en":"Hoi An Ancient Town Pork Noodles (Cao Lầu)","vi":"Cao Lầu Phố Cổ Hội An","ja":"ホイアン旧市街名物 和え米うどん（カオ・ラウ）","ko":"호이안 고대 도시 명물 비빔 쌀우동 (까오러우)"},"subtitle":{"zh-TW":"筋道粗韌灰黃米麵・秘製五香叉燒肉片・炸脆米皮與濃醇五味滷汁","en":"Chewy Ash-Water Rice Noodles with Spiced Char Siu, Crispy Crackers & Herbs","vi":"Sợi mì tro dẻo dai sần sật, thịt xá xíu đậm đà, da heo tóp mỡ giòn rụm","ja":"コシの強い太麺・秘伝の五香チャーシューとカリカリ揚げライスペーパー","ko":"쫄깃하고 굵은 잿물 쌀면과 특제 오향 차슈, 바삭한 튀김 크래커"},"tagline":{"zh-TW":"傳承四百年的世界遺產級麵食，日本烏龍麵與越南在地食材的跨世紀傳奇","en":"A 400-year UNESCO heritage mystery—a cross-cultural marvel of chewy noodles and herbal greens","vi":"Mỹ vị độc nhất vô nhị chỉ có tại phố cổ Hội An, sự giao thoa văn hóa hàng trăm năm","ja":"日本の伊勢うどんがルーツとも言われる、世界遺産の街ホイアン唯一無二の麺料理","ko":"유네스코 세계문화유산 호이안의 400년 역사를 품은 쫄깃한 면발의 전설"},"heroImage":"/images/vn/cao-lau.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":25,"defaultServings":2,"caloriesPerServing":490,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"中部・會安聯合國世界遺產古鎮 (Hội An)","en":"Central Vietnam / UNESCO Heritage Town of Hoi An","vi":"Miền Trung / Phố Cổ Hội An","ja":"中部・ホイアン世界遺産旧市街","ko":"베트남 중부 / 호이안 고대 도시"},"famousStreetMarkets":[{"zh-TW":"會安古鎮陳富街 (Cao Lầu Thanh)","en":"Cao Lau Thanh (Tran Phu St, Hoi An)","vi":"Cao Lầu Thanh","ja":"ホイアン チャンフー通り","ko":"호이안 쩐푸 거리 까오러우 탄"},{"zh-TW":"會安中央市場 (Chợ Hội An)","en":"Hoi An Central Market Noodle Row","vi":"Chợ Hội An","ja":"ホイアン中央市場","ko":"호이안 중앙시장 국수 골목"}],"historyStory":{"zh-TW":"17 世紀會安作為亞洲繁華國際商港，吸引了大量日本與華人商人。傳說曹樓麵 (Cao Lầu，字面意為「高樓上吃的麵」，過去只有商人和富戶能在二樓雅座享用）受到日本伊勢烏龍麵的啟發，麵條必須用佔婆島 (Cù Lao Chàm) 特產柴木灰水浸泡，再用會安千年巴禮古井 (Giếng Bá Lễ) 的礦泉水揉麵，成就獨特灰黃色澤與極致有嚼勁的粗彈口感。","en":"In the 17th century, Hoi An was a bustling international maritime trading post teeming with Japanese and Chinese merchants. Legend connects Cao Lầu (meaning ‘High Pavilion’—historically reserved for wealthy traders dining on second-floor balconies) to Japanese udon. Traditionally made with ash from Cham Islands trees and water from the ancient thousand-year Ba Le Well, creating its famously firm, chewy texture.","vi":"Cao Lầu xuất hiện từ thế kỷ 17 khi Hội An là thương cảng sầm uất. Tên gọi ‘Cao lầu’ nghĩa là món ăn trên lầu cao của các thương nhân quyền quý. Sợi mì cao lầu độc đáo nhờ ngâm nước tro củi Cù Lao Chàm và nhào bằng nước giếng cổ Bá Lễ ngàn năm, tạo nên độ dai dẻo sần sật không nơi nào sao chép được.","ja":"17世紀に朱印船貿易で栄えたホイアンで、日本人街の商人たちが伝えた伊勢うどんが起源とも言われています。チャム島の灰水とバーレー古井戸の水で仕込んだ麺は、独特のコシと弾力を誇ります。","ko":"17세기 국제 무역항이었던 호이안에서 일본 상인들의 우동과 중국 차슈가 결합되어 탄생했습니다. ‘높은 누각에서 먹는 면’이라는 뜻으로, 천년 고우물 물로 반죽한 쫄깃한 면발이 특징입니다."},"vietScript":"Cao Lầu Hội An","vietPhonetics":"Cow Low Hoy Ahn","audioPronunciationText":"Cho tôi hai bát cao lầu thịt xá xíu nhiều tóp mỡ!"},"ingredients":[{"id":"cao-lau-noodles","name":{"zh-TW":"會安特產粗韌高樓麵 (或烏龍麵/粗厚米麵)","en":"Hoi An Cao Lầu Noodles (or thick Chewy Udon/Rice Noodles)","vi":"Sợi mì cao lầu Hội An","ja":"カオラウ太麺（または讃岐うどん）","ko":"까오러우 전용 굵은 쌀우동면 (또는 쫄깃한 우동면)"},"amount":350,"unitMetric":"g","unitUS":"12 oz","isKeyFlavor":true,"vietName":"Mì cao lầu","vietPronunciation":"Mee Cow Low"},{"id":"pork-loin-charsiu","name":{"zh-TW":"豬里肌肉塊 (製作會安五香叉燒肉)","en":"Pork Loin or Shoulder (For spiced Char Siu)","vi":"Thịt nạc vai heo làm xá xíu","ja":"豚肩ロース（五香粉チャーシュー用）","ko":"돼지 안심/목살 (오향 차슈용)"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":true,"vietName":"Thịt xá xíu","vietPronunciation":"Teet Sah See-oo"},{"id":"charsiu-marinade","name":{"zh-TW":"五香叉燒醃汁：五香粉半小匙、醬油 2 大匙、魚露 1 大匙、砂糖 1.5 大匙、大蒜碎、黑胡椒","en":"Char Siu Marinade: Five Spice, Soy Sauce, Fish Sauce, Sugar, Garlic & Black Pepper","vi":"Gia vị ướp xá xíu: Ngũ vị hương, nước tương, nước mắm, đường, tỏi","ja":"チャーシューダレ：五香粉、醤油、ヌクマム、砂糖、ニンニク","ko":"차슈 양념: 오향분, 간장 2큰술, 피시소스 1큰술, 설탕, 마늘, 후추"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Gia vị xá xíu","vietPronunciation":"Zia Vee"},{"id":"crispy-rice-crackers","name":{"zh-TW":"炸脆米皮丁或炸豬皮油渣 (Tóp mỡ 極致酥脆靈魂)","en":"Deep-Fried Rice Paper Crackers or Pork Cracklings (Tóp mỡ)","vi":"Ram chiên giòn / tóp mỡ da heo","ja":"カリカリの揚げライスペーパーまたは油かす","ko":"바삭하게 튀긴 라이스 크래커 또는 돼지껍데기 튀김"},"amount":60,"unitMetric":"g","unitUS":"2.1 oz","isKeyFlavor":true,"vietName":"Ram chiên giòn","vietPronunciation":"Rahm Chee-en"},{"id":"fresh-herbs-hoi-an","name":{"zh-TW":"新鮮山野菜：薄荷、芫荽、水芥菜葉、生豆芽 (燙半熟鋪底)","en":"Hoi An Garden Herbs: Spearmint, Cilantro, Mustard Greens & Parboiled Sprouts","vi":"Rau sống Trà Quế: Húng lủi, cải con, giá đỗ chần","ja":"チャクエ村のフレッシュハーブ、サッと茹でたもやし","ko":"짜꾸에 허브 모둠 (민트, 어린잎, 살짝 데친 숙주)"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Rau sống Trà Quế","vietPronunciation":"Rao Trah Kway"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"五香醬油醃漬與慢火燜煎叉燒肉","en":"Marinate & Braise Five-Spice Char Siu Pork","vi":"Ướp thịt & rim xá xíu đậm đà cánh gián","ja":"五香粉で豚肉をマリネし・香ばしく照り煮にする","ko":"오향 차슈 양념에 재워 조려내기"},"instruction":{"zh-TW":"豬里肌肉加入五香粉、蒜末、醬油、魚露與砂糖抓醃 20 分鐘。小鍋熱油，下醃好的豬肉塊大火煎至四面微焦，倒入剩餘醃汁與 100ml 清水，加蓋小火燜煨 20 分鐘。撈出叉燒肉切薄片，鍋底濃醇肉汁留作高樓麵靈魂拌醬！","en":"Toss pork with five-spice, garlic, soy sauce, fish sauce, and sugar; rest 20 mins. Sear pork in a pan until browned on all sides, add marinade and 100ml water. Cover and braise on low for 20 mins until tender. Slice char siu thinly, keeping the rich pan sauce as the dressing!","vi":"Ướp thịt với ngũ vị hương, tỏi, nước tương, nước mắm và đường trong 20 phút. Áp chảo thịt vàng đều các mặt, đổ nước ướp và 100ml nước vào đậy vung rim nhỏ lửa 20 phút. Vớt thịt thái lát mỏng, giữ lại phần nước sốt đậm đà trong chảo.","ja":"豚肉を五香粉や調味料で20分マリネします。表面をこんがり焼き、水100mlを加えて弱火で20分蒸し煮にします。薄切りにし、鍋に残った濃厚なタレを和えダレとして使います。","ko":"돼지고기를 오향분 양념에 20분간 재웁니다. 겉면을 노릇하게 구운 뒤 양념과 물 100ml를 붓고 약불에서 20분간 조려냅니다. 고기는 얇게 썰고, 남은 국물은 비빔 소스로 사용합니다."},"durationSeconds":240,"image":"/images/vn/cao-lau-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"炸製香脆米皮丁與蒸熱高樓麵條","en":"Deep-Fry Crispy Crackers & Steam Chewy Noodles","vi":"Chiên giòn bánh ram tóp mỡ & hấp nóng mì cao lầu","ja":"ライスペーパーをカリカリに揚げ・麺を蒸気で温める","ko":"라이스 크래커 튀기기 및 쫄깃한 면 삶기"},"instruction":{"zh-TW":"將厚米紙剪成 2 公分小正方形，入 180°C 油鍋炸 10 秒至金黃酥脆撈出。另起蒸鍋或沸水，將高樓麵條蒸或燙 1 分鐘至柔韌微彈，切勿過度久煮以免失去標誌性嚼勁。","en":"Cut thick rice paper into 2cm squares and deep-fry in 180°C oil for 10 secs until crispy. Steam or blanch Cao Lầu noodles for 1 min until chewy—never overcook, its signature firm bite must be preserved.","vi":"Cắt bánh ram thành miếng vuông 2cm, chiên ngập dầu 10 giây cho phồng giòn vàng rụm. Trụng nhanh sợi mì cao lầu qua nước sôi 1 phút cho mì mềm dẻo dai sần sật.","ja":"ライスペーパーを2cm角に切り、油で10秒サッと揚げてクルトン状にします。麺は熱湯で1分サッと湯通しし、独自の力強いコシを残します。","ko":"라이스페이퍼를 작게 잘라 180°C 기름에 10초간 바삭하게 튀겨냅니다. 면은 끓는 물에 딱 1분간 살짝 데쳐 특유의 쫄깃한 식감을 살립니다."},"durationSeconds":180,"image":"/images/vn/cao-lau-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"豆芽鋪底、碼肉、撒炸脆丁，淋濃郁五香肉汁","en":"Assemble Platter: Sprouts, Noodles, Char Siu & Sauce","vi":"Trình bày: Lót giá đỗ, xếp mì, thịt xá xíu, ram giòn & rưới nước sốt","ja":"もやしを敷き・麺・チャーシュー・揚げ皮を盛りタレを回しかける","ko":"숙주 깔기, 면과 차슈, 크래커 얹고 특제 소스 끼얹기"},"instruction":{"zh-TW":"碗底鋪上一把燙熱爽脆綠豆芽與薄荷香菜。放上熱氣騰騰的筋道高樓麵，整齊碼上切薄片的五香叉燒肉片，豪邁撒上一大把金黃香脆米皮丁。最後舀起 2-3 大匙燜肉留下的濃醇五香肉汁淋在麵上！用筷子徹底翻拌，每一根麵條裹滿微甜濃香肉汁，伴隨著脆丁的爆裂聲享用！","en":"Line bowl bottom with warm bean sprouts and herbs. Mound chewy noodles on top, flanked by tender char siu slices and a handful of golden crackers. Drizzle 2-3 tbsp rich braising sauce over the top. Toss vigorously—every strand gleams with savory spice, punctuated by shattering crunch!","vi":"Lót giá đỗ chần giòn dưới đáy tô. Cho mì cao lầu lên trên, xếp đều từng lát thịt xá xíu nâu bóng, rải đầy ram chiên giòn rụm. Múc 2-3 thìa nước sốt xá xíu đậm đà rưới đều lên mặt mì. Trộn đều tay và thưởng thức ngay độ dẻo dai thơm lừng!","ja":"器の底にもやしとハーブを敷き、麺を乗せます。チャーシューと揚げライスペーパーをトッピングし、煮汁を大さじ2〜3杯回しかけます。全体を豪快にかき混ぜて、奥深いスパイスと食感のコントラストを堪能します！","ko":"그릇 바닥에 데친 숙주와 허브를 깔고 면을 얹습니다. 얇게 썬 오향 차슈와 바삭한 크래커를 듬뿍 올리고, 조림 소스 2~3큰술을 끼얹습니다. 골고루 비벼서 한 입 가득 즐기세요!"},"durationSeconds":60,"image":"/images/vn/cao-lau-step3.jpg"}],"troubleshooting":[{"id":"cao-lau-soggy-noodles","problem":{"zh-TW":"高樓麵煮得過於軟爛，失去了標誌性的粗韌彈牙嚼勁","en":"Noodles turned mushy and lost their firm, chewy texture","vi":"Sợi mì bị nhũn nát, mất đi độ dai dẻo sần sật đặc trưng","ja":"麺が柔らかくなりすぎて、カオラウ特有の強いコシが失われた","ko":"면이 너무 푹 퍼져서 특유의 쫄깃한 식감이 사라졌어요"},"cause":{"zh-TW":"在熱水中燙煮時間超過 2 分鐘，高樓麵本身含水量低只需回溫。","en":"Boiled too long in hot water. Cao Lau noodles need only a 60-second reheat.","vi":"Chần trong nước sôi quá 2 phút, sợi mì chỉ cần hâm nóng nhanh.","ja":"熱湯に長く浸けすぎた。温める程度で十分です。","ko":"끓는 물에 너무 오래 삶았기 때문입니다. 1분 이내로 가볍게 데우기만 하세요."},"solution":{"zh-TW":"滾水中僅需燙 45-60 秒即可撈出瀝乾！若使用烏龍麵代換，請挑選標註「讃岐極太 / 彈性韌度高」的規格。","en":"Blanch for 45-60 seconds max. If using udon, choose firm Sanuki style.","vi":"Chỉ chần 45-60 giây rồi vớt ráo nước ngay.","ja":"茹で時間は45〜60秒にとどめて湯切りします。うどんで代用する場合はコシの強い讃岐うどんを選びます。","ko":"딱 45~60초만 데쳐 물기를 빼세요. 우동면으로 대체할 경우 사누키 우동처럼 쫄깃한 면을 고르세요."}}],"proTips":[{"zh-TW":"會安古鎮不傳秘密：高樓麵絕不是湯麵，而是「濃汁乾拌麵」！碗底只留 2-3 大匙極度濃醇的五香滷肉汁，吃的時候每一根麵條恰好將肉汁吸收殆盡，碗底不留多餘湯水，才是最地道的吃法！","en":"Hoi An insider fact: Cao Lầu is strictly a dry tossing noodle, NOT a soup! Only 2-3 tablespoons of concentrated five-spice jus sit at the bottom, just enough for the chewy noodles to soak up every drop.","vi":"Bí mật phố cổ: Cao lầu không phải là món bún nước, mà là món mì trộn sốt cạn! Dưới đáy tô chỉ có 2-3 thìa sốt xá xíu đậm đà vừa đủ để sợi mì hút trọn vị ngon mà không hề lõng bõng nước.","ja":"ホイアン通の常識：カオラウはスープ麺ではなく「汁なし和え麺」です！底にある大さじ2〜3杯の濃厚なタレを麺全体に絡め切って食べるのが正統派スタイル。","ko":"호이안 현지인 상식: 까오러우는 국물 국수가 아닌 ‘자작한 비빔국수’입니다! 바닥에 자작하게 깔린 2~3큰술의 진한 소스가 면발에 싹 스며들도록 비벼 먹는 것이 정석입니다."}]},{"country":"vn","id":"mi-quang","slug":"mi-quang","title":{"zh-TW":"峴港廣南黃金薑黃海鮮拌麵","en":"Da Nang Turmeric Pork & Prawn Noodles (Mì Quảng)","vi":"Mì Quảng Tôm Thịt Đà Nẵng","ja":"ダナン・クアンナム名物 ターメリック海鮮和え麺（ミークアン）","ko":"다낭 광남 명물 강황 새우 돼지고기 비빔면 (미꽝)"},"subtitle":{"zh-TW":"亮黃薑黃寬扁米麵・濃縮大蝦五花肉精華高湯・黑芝麻脆烤米餅","en":"Vibrant Turmeric Flat Noodles with Simmered Prawns, Quail Eggs & Black Sesame Rice Cracker","vi":"Sợi mì vàng óng màu nghệ, nước nhưỡng tôm thịt đậm đà, bánh tráng mè nướng giòn","ja":"鮮やかな黄色い平米麺・エビと豚肉の濃厚な少量スープ・黒ごま煎餅","ko":"노란 강황 납작 쌀국수와 자작하고 진한 새우 돼지고기 육수, 고소한 흑임자 라이스 크래커"},"tagline":{"zh-TW":"越南中部的驕傲與靈魂主食，捏碎一片芝麻米餅拌入微量濃湯，香脆驚豔","en":"The beloved pride of central Vietnam—crush a sesame rice cracker over the noodles and toss!","vi":"Món ăn đậm đà bản sắc xứ Quảng, bẻ vụn bánh tráng mè xúc từng đũa mì thơm lừng","ja":"香ばしい黒ごま煎餅をパキパキ割って混ぜる！ダナンが誇る至高の郷土麺","ko":"바삭한 흑임자 쌀과자를 부숴 넣어 비벼 먹는 다낭의 소울푸드"},"heroImage":"/images/vn/mi-quang.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":15,"defaultServings":2,"caloriesPerServing":460,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"中部・峴港與廣南省 (Đà Nẵng & Quảng Nam)","en":"Central Vietnam / Da Nang & Quang Nam Province","vi":"Miền Trung / Đà Nẵng & Quảng Nam","ja":"中部・ダナンおよびクアンナム省","ko":"베트남 중부 / 다낭 및 꽝남성"},"famousStreetMarkets":[{"zh-TW":"峴港草市場 (Chợ Cồn)","en":"Con Market Food Court (Da Nang)","vi":"Chợ Cồn Đà Nẵng","ja":"ダナン コン市場","ko":"다낭 콘 시장"},{"zh-TW":"峴港漢市場周邊 (Chợ Hàn)","en":"Han Market Eateries","vi":"Chợ Hàn Đà Nẵng","ja":"ハン市場周辺","ko":"다낭 한 시장 주변"}],"historyStory":{"zh-TW":"Mì Quảng 起源於 16 世紀廣南省。廣南人性格質樸豪邁，不喜繁瑣清湯，而是將鮮蝦、五花肉、紅蔥頭與薑黃汁小火濃縮煨煮成「極少量濃郁肉汁 (Nước nhưỡng)」。寬扁的薑黃米麵只舀入一淺勺濃湯，頂部撒上烤花生碎、熟鵪鶉蛋，附上一整大片炭火烤熟的黑芝麻米餅 (Bánh tráng mè)。吃時用手將芝麻米餅捏成碎塊拌入麵中，香脆與柔滑交織。","en":"Born in Quang Nam province in the 16th century, Mì Quảng reflects the robust spirit of central Vietnam. Instead of a full bowl of broth, it is bathed in just a shallow ladle of concentrated, turmeric-infused pork and shrimp gravy (nước nhưỡng). Topped with crushed peanuts, quail eggs, and a large crisp black sesame rice cracker (bánh tráng mè) snapped over the bowl.","vi":"Mì Quảng là món ăn gắn liền với đời sống của người dân xứ Quảng từ thế kỷ 16. Khác với các món phở bún chan ngập nước, mì Quảng chỉ chan một muôi nước nhưỡng tôm thịt thật đậm đà xâm xấp đáy bát, rắc đậu phộng rang giã dập và bẻ vụn chiếc bánh tráng mè nướng giòn rụm xúc ăn cùng.","ja":"16世紀のクアンナム地方で誕生。たっぷりのスープではなく、具材の旨味を凝縮させた少量の濃厚ダレ（ヌック・ニュオン）を絡めて食べるのが最大の特徴。大判の黒ごまライスクラッカーをバキバキと割ってトッピングし、食感のコントラストを楽しみます。","ko":"16세기 꽝남성에서 유래된 중부 베트남의 명물 국수입니다. 국물을 가득 붓는 쌀국수와 달리, 새우와 돼지고기를 진하게 졸인 양념 국물을 자작하게 부어 흑임자 라이스 크래커를 부숴 넣어 비벼 먹습니다."},"vietScript":"Mì Quảng Đà Nẵng","vietPhonetics":"Mee Kwahng Dah Nahng","audioPronunciationText":"Cho tôi hai tô mì Quảng tôm thịt thêm bánh tráng mè nướng!"},"ingredients":[{"id":"turmeric-noodles","name":{"zh-TW":"金黃薑黃寬扁河粉 (Mì Quảng 鮮黃滑順)","en":"Turmeric Flat Rice Noodles (Wide yellow ribbon noodles)","vi":"Sợi mì Quảng vàng tráng nghệ","ja":"ターメリック平米麺（ミークアン麺）","ko":"강황 납작 쌀국수 면"},"amount":350,"unitMetric":"g","unitUS":"12 oz","isKeyFlavor":true,"vietName":"Mì Quảng vàng","vietPronunciation":"Mee Kwahng Vahng"},{"id":"prawns-pork-belly","name":{"zh-TW":"鮮蝦 8 隻 (去頭留尾) + 五花肉片 150g","en":"Fresh Prawns (8 pcs) + Pork Belly slices (150g)","vi":"Tôm đất tươi & thịt ba chỉ thái mỏng","ja":"生海老（殻むき）＋豚バラ肉薄切り","ko":"생새우 8마리 + 삼겹살 슬라이스 150g"},"amount":250,"unitMetric":"g","unitUS":"8.8 oz","isKeyFlavor":true,"vietName":"Tôm thịt nấu mì Quảng","vietPronunciation":"Tom Teet"},{"id":"turmeric-shallot-oil","name":{"zh-TW":"薑黃粉、紅蔥碎、大蒜、魚露、老抽、花生油","en":"Turmeric Powder, Shallots, Garlic, Fish Sauce, Peanut Oil","vi":"Bột nghệ, củ nén (hoặc hành tỏi), dầu phộng, nước mắm","ja":"ターメリック、エシャロット、ピーナッツ油、ヌクマム","ko":"강황가루, 샬롯, 피넛오일, 피시소스"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Gia vị kho tôm thịt","vietPronunciation":"Zia Vee"},{"id":"black-sesame-cracker","name":{"zh-TW":"炭烤黑芝麻米餅 (Bánh tráng mè 烘烤酥脆香氣撲鼻)","en":"Grilled Black Sesame Rice Cracker (Bánh Tráng Mè)","vi":"Bánh tráng mè nướng giòn rụm","ja":"焼き黒ごまライスクラッカー","ko":"구운 흑임자 라이스 크래커"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Bánh tráng mè nướng","vietPronunciation":"Bahn Trahng Meh"},{"id":"quail-eggs-peanuts","name":{"zh-TW":"水煮鵪鶉蛋 4 顆、烘焙碎花生 2 大匙、新鮮青檸生辣椒","en":"Boiled Quail Eggs, Crushed Roasted Peanuts, Lime & Chili","vi":"Trứng cút luộc, đậu phộng rang giã dập, chanh ớt","ja":"茹でうずら卵、砕きピーナッツ、生ライム、生唐辛子","ko":"삶은 메추리알 4개, 으깬 볶음 땅콩, 라임, 생고추"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Trứng cút, đậu phộng","vietPronunciation":"Teu-ong Koot"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"炒香鮮蝦五花肉與濃縮熬煮黃金肉汁","en":"Simmer Concentrated Pork & Prawn Gravy (Nước Nhưỡng)","vi":"Kho rim tôm thịt đậm đà nấu nước nhưỡng vàng óng","ja":"エビと豚肉の濃厚な旨味ダレ（ヌック・ニュオン）作り","ko":"새우와 돼지고기를 볶아 진한 강황 육수(늑느엉) 졸이기"},"instruction":{"zh-TW":"鍋中熱 2 大匙花生油，下紅蔥蒜末炒香。放入五花肉片與鮮蝦大火爆炒，加入薑黃粉 1 小匙、魚露 2 大匙、糖 1 大匙上色翻炒 3 分鐘。倒入 300ml 骨湯或水，小火滾煨 10 分鐘，濃縮成鮮甜無比、金黃透亮的少許精華肉汁 (Nước nhưỡng)。","en":"Heat 2 tbsp peanut oil, sauté shallots and garlic. Add pork and prawns, seasoning with 1 tsp turmeric powder, 2 tbsp fish sauce, and 1 tbsp sugar. Pour in 300ml stock and simmer on low for 10 mins into an intensely savory, golden concentrated gravy (Nước nhưỡng).","vi":"Làm nóng 2 thìa dầu phộng, phi thơm hành tỏi. Cho thịt ba chỉ và tôm vào xào săn, nêm 1 thìa bột nghệ, 2 thìa nước mắm, 1 thìa đường đảo đều cho lên màu vàng óng. Đổ 300ml nước dùng vào đun nhỏ lửa 10 phút để thu được nồi nước nhưỡng tôm thịt đậm đà.","ja":"ピーナッツ油でエシャロットとニンニクを炒めます。豚肉とエビを加え、ターメリック、ヌクマム、砂糖で味付け。スープ300mlを加えて弱火で10分煮詰め、濃厚な黄金色のタレを仕上げます。","ko":"팬에 피넛오일을 두르고 마늘을 볶다가 고기와 새우, 강황가루, 피시소스 2큰술, 설탕을 넣고 볶습니다. 육수 300ml를 붓고 약불에서 10분간 졸여 진한 황금빛 소스(늑느엉)를 완성합니다."},"durationSeconds":240,"image":"/images/vn/mi-quang-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"燙黃金寬麵、澆入少量濃湯與盛盤","en":"Blanch Turmeric Noodles & Ladle Shallow Gravy","vi":"Chần mì vàng, chan nước nhưỡng xâm xấp đáy bát","ja":"黄色い平米麺を湯通しし・濃厚ダレを少量回しかける","ko":"강황 면 데치기 및 자작하게 소스 국물 붓기"},"instruction":{"zh-TW":"將薑黃寬麵在滾水中燙 20 秒，瀝乾放入碗中。舀入熟透的鮮蝦、五花肉片與剝殼熟鵪鶉蛋。舀起半湯勺（約 60-80ml）金黃濃縮肉汁淋在麵底——記住：廣南麵絕對不可淹沒麵條，只需浸到麵條高度的 1/3 即可！","en":"Blanch turmeric noodles for 20 secs, drain and place in wide bowls. Arrange cooked prawns, tender pork belly, and quail eggs on top. Ladle only 1/2 ladle (approx 60-80ml) of the concentrated turmeric gravy into the bowl—just enough to wet the bottom third of the noodles!","vi":"Chần sợi mì Quảng trong 20 giây rồi cho vào tô. Gắp tôm, thịt ba chỉ và trứng cút xếp lên trên. Múc nửa muôi (60-80ml) nước nhưỡng tôm thịt chan xâm xấp đáy tô—đặc trưng của mì Quảng là không chan ngập nước.","ja":"ターメリック麺を20秒湯通しして器に盛ります。エビ、豚肉、うずら卵を乗せ、お玉半分（約70ml）の濃厚ダレを底に注ぎます（決してスープで麺を浸さないのが本場の流儀！）。","ko":"강황 면을 20초간 데쳐 그릇에 담습니다. 새우, 돼지고기, 메추리알을 얹고, 진한 육수 반 국자(약 70ml)를 면의 1/3 높이까지만 자작하게 부어줍니다."},"durationSeconds":120,"image":"/images/vn/mi-quang-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"撒花生碎、捏碎黑芝麻米餅拌食","en":"Crush Black Sesame Cracker, Scatter Peanuts & Toss","vi":"Bẻ vụn bánh tráng mè, rắc đậu phộng rang & trộn đều","ja":"黒ごま煎餅をバキバキと割り入れ・ピーナッツと豪快に混ぜる","ko":"흑임자 라이스 크래커를 부숴 넣고 땅콩 뿌려 비벼 먹기"},"instruction":{"zh-TW":"撒上厚厚一大匙香脆碎花生、蔥花與生辣椒圈。拿一片烤香脆的黑芝麻米餅 (Bánh tráng mè)，用雙手直接在碗上方捏碎成大小不一的脆塊撒在麵頂！擠上新鮮青檸汁，用筷子徹底攪拌，讓每根麵條沾滿肉汁，咬到芝麻米餅時卡茲作響！","en":"Garnish with a generous tablespoon of crushed roasted peanuts, scallions, and chili slices. Take a crisp black sesame rice cracker (Bánh Tráng Mè) and snap it directly over the bowl with your hands into crunchy bite-sized shards. Squeeze fresh lime, toss thoroughly, and savor the glorious interplay of silky noodles and shattering sesame crunch!","vi":"Rắc thật nhiều đậu phộng rang giã dập, hành hoa và ớt tươi. Cầm chiếc bánh tráng mè nướng giòn rụm, dùng tay bẻ vụn trực tiếp vào bát mì! Vắt chút chanh tươi, dùng đũa trộn đều cho từng sợi mì ngấm sốt đậm đà, cắn phải miếng bánh tráng mè giòn tan bùi béo!","ja":"たっぷりの砕きピーナッツと青ネギ、唐辛子を散らします。香ばしい黒ごまライスクラッカーを両手でバキバキと豪快に割ってボウルの中に散らします！生ライムを絞り、全体をよく混ぜて、モチモチとカリカリの二重奏を堪能します！","ko":"볶음 땅콩 분태와 쪽파, 고추를 듬뿍 얹습니다. 바삭한 흑임자 쌀과자(반짱메)를 손으로 와사삭 부숴 그릇 위에 뿌려줍니다! 라임을 짜 넣고 골고루 비벼서 쫄깃한 면과 고소한 크래커의 완벽한 조화를 즐기세요!"},"durationSeconds":60,"image":"/images/vn/mi-quang-step3.jpg"}],"troubleshooting":[{"id":"mi-quang-too-much-soup","problem":{"zh-TW":"湯水加得像一般河粉一樣多，導致味道寡淡被稀釋","en":"Added too much broth like regular soup pho, diluting the flavor","vi":"Chan quá nhiều nước làm mì bị lõng bõng nhạt nhẽo","ja":"フォーのようにスープをなみなみ注いでしまい、味が薄まってしまった","ko":"국물을 일반 쌀국수처럼 너무 많이 부어 싱거워졌어요"},"cause":{"zh-TW":"廣南麵是「拌麵 (Tossed noodles)」不是「湯麵 (Soup noodles)」，湯汁本質是濃縮調味肉汁。","en":"Mì Quảng is a dry-tossed dish. The broth is meant to be a concentrated coating sauce.","vi":"Mì Quảng là món mì trộn sốt sánh, không phải bún nước.","ja":"ミークアンは汁だく麺ではなく、濃厚なタレを絡めて食べる「和え麺」です。","ko":"미꽝은 국물 요리가 아니라 자작한 소스에 비벼 먹는 비빔면입니다."},"solution":{"zh-TW":"肉汁只需舀半大勺（淹沒碗底約 1-2 公分即可），讓麵條、芝麻餅與花生充分吸收濃汁拌勻。","en":"Only ladle 60-80ml of gravy—just enough to wet the bottom third of the bowl.","vi":"Chỉ chan nửa muôi nước nhưỡng vừa đủ ướt đáy tô để trộn đều.","ja":"タレは底に1〜2cmほど溜まる程度（約70ml）にとどめ、しっかり和えて食べます。","ko":"소스 국물은 바닥에 1~2cm 정도만 자작하게 깔리도록 반 국자만 넣으세요."}}],"proTips":[{"zh-TW":"極致吃法——「用芝麻米餅當湯匙」：廣南在地人吃 Mì Quảng 時，會掰下一整塊較大的黑芝麻米餅，像湯匙一樣直接舀起薑黃麵條與鮮蝦肉片一口送入嘴裡，雙重麥香與芝麻香爆發！","en":"Da Nang eating secret: Locals snap off a large flat shard of the black sesame cracker and use it literally as an edible spoon to scoop up the turmeric noodles and shrimp in one crunchy mouthful!","vi":"Thú ăn độc đáo của người Quảng: Bẻ một miếng bánh tráng mè to, dùng như chiếc thìa xúc trọn cả mì, tôm thịt và rau sống đưa vào miệng nhai giòn tan rôm rốp!","ja":"地元ダナン流の裏技：大きめに割った黒ごま煎餅をスプーン代わりにして、麺とエビを一緒にすくって口へ運ぶのが本場の粋な食べ方！","ko":"다낭 현지인 먹방 팁: 큼직한 흑임자 과자 조각을 숟가락처럼 활용해 면과 새우를 얹어 한 입에 바삭하게 떠먹는 것이 정석입니다!"}]},{"country":"vn","id":"ca-phe-trung","slug":"ca-phe-trung","title":{"zh-TW":"河內傳奇蛋黃卡布奇諾 (雞蛋咖啡)","en":"Hanoi Legendary Egg Coffee (Cà Phê Trứng)","vi":"Cà Phê Trứng Hà Nội","ja":"ハノイ伝統のエッグコーヒー（カフェ・チュン）","ko":"하노이 전설의 에그 커피 (카페쯩)"},"subtitle":{"zh-TW":"棉花糖般金黃雲朵蛋霜・濃苦熱羅布斯塔黑滴濾・熱水浴保溫","en":"Velvety Whipped Egg Yolk Foam over Piping Hot Dark Robusta Coffee","vi":"Lớp kem trứng đánh bông mịn như mây, cốt cà phê phin đen đậm đà ngâm bát nước nóng","ja":"マシュマロのように濃密な卵黄カスタード泡とビターな深煎りロブスタ抽出液","ko":"구름처럼 쫀득하고 부드러운 달걀 커스터드 크림과 진한 핀 드립 커피"},"tagline":{"zh-TW":"物資匱乏年代誕生的世界咖啡奇蹟，喝一口如品嚐液態提拉米蘇般的極致絲滑","en":"Born during milk shortages—a world-renowned liquid tiramisu elixir from Hanoi Old Quarter","vi":"Kiệt tác cà phê phố cổ Hà Nội, bồng bềnh ngọt ngào say đắm lòng người","ja":"牛乳不足の時代にハノイのバーテンダーが生んだ奇跡。まるで飲むティラミス！","ko":"우유가 부족하던 시절 탄생한 기적의 커피, 마시는 티라미수라 불리는 극상의 부드러움"},"heroImage":"/images/vn/ca-phe-trung.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":5,"defaultServings":2,"caloriesPerServing":220,"category":"dessertsDrinks","dietaryTags":["classic","vegetarian","glutenFree"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"北部・河內老城區 (Giảng Cafe)","en":"Northern Vietnam / Hanoi Old Quarter (Cafe Giảng)","vi":"Miền Bắc / Phố cổ Hà Nội (Cà Phê Giảng)","ja":"北部・ハノイ旧市街（カフェ・ジャン）","ko":"베트남 북부 / 하노이 구시가지 (카페 장)"},"famousStreetMarkets":[{"zh-TW":"河內阮友勛街 (Cà Phê Giảng - 創始老店)","en":"Cafe Giang (Nguyen Huu Huan, Hanoi)","vi":"Cà Phê Giảng (39 Nguyễn Hữu Huân)","ja":"カフェ・ジャン（創業店）","ko":"카페 장 (에그커피 원조)"},{"zh-TW":"還劍湖周邊 (Hồ Hoàn Kiếm)","en":"Hoan Kiem Lake Cafes","vi":"Khu vực Hồ Gươm","ja":"ホアンキエム湖周辺","ko":"호안끼엠 호수 주변 카페"}],"historyStory":{"zh-TW":"1946 年第一次印度支那戰爭期間，河內法式大都會飯店 (Sofitel Legend Metropole) 調酒師阮文江 (Nguyễn Văn Giảng) 面臨鮮奶極度短缺的困境。他靈機一動，用新鮮生蛋黃加上煉乳與砂糖，高速打發成厚重綿密如慕斯卡士達般的「蛋霜」，倒在剛滴濾出的滾燙羅布斯塔黑咖啡上。蛋霜的甘甜乳脂完美馴服了深焙咖啡的焦苦，自此誕生名震全球的「河內雞蛋咖啡」。","en":"Invented in 1946 during the First Indochina War by Mr. Nguyễn Văn Giảng, a bartender at Hanoi’s historic Sofitel Legend Metropole Hotel. Faced with an acute condensed milk shortage, he ingeniously whisked raw egg yolks with sugar and a splash of condensed milk into an airy custard sabayon, floating it atop piping-hot dark drip robusta coffee.","vi":"Cà phê trứng ra đời năm 1946 bởi cụ Nguyễn Văn Giảng, nguyên là bartender của khách sạn Metropole Hà Nội. Trong thời kỳ thiếu thốn sữa đặc, cụ đã sáng tạo dùng lòng đỏ trứng gà đánh bông mịn thay thế cho sữa, rót lên ly cà phê phin đen đậm đặc. Lớp kem trứng béo ngậy ngọt ngào hòa cùng vị đắng thơm nồng của cà phê đã trở thành huyền thoại.","ja":"1946年、名門ホテル「メトロポール」のバーテンダーだったグエン・ヴァン・ジャン氏が、戦時中の牛乳不足を乗り切るために考案。卵黄と練乳をホイップして濃厚なカスタードクリームを作り、熱いブラックコーヒーの上に浮かべたのが始まりです。","ko":"1946년 메트로폴 호텔의 바텐더였던 응우옌 반 장 씨가 우유 부족 사태를 극복하기 위해 신선한 달걀노른자를 휘핑해 연유와 함께 진한 핀 커피 위에 얹으며 탄생했습니다."},"vietScript":"Cà Phê Trứng","vietPhonetics":"Cah Feh Teu-ong","audioPronunciationText":"Cho tôi hai ly cà phê trứng nóng ngâm bát nước sôi!"},"ingredients":[{"id":"egg-yolks","name":{"zh-TW":"新鮮優質生蛋黃 2 顆 (徹底去除蛋白)","en":"Fresh High-Quality Egg Yolks (Separated cleanly)","vi":"2 lòng đỏ trứng gà tươi sạch","ja":"新鮮な卵黄2個（白身を完全に除く）","ko":"신선한 생 달걀노른자 2개 (흰자 완벽 분리)"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Lòng đỏ trứng gà","vietPronunciation":"Lawng Daw Teu-ong"},{"id":"condensed-milk","name":{"zh-TW":"壽星公越式甜煉乳 (Sữa đặc Ông Thọ)","en":"Vietnamese Sweetened Condensed Milk (Lonestar / Ông Thọ)","vi":"Sữa đặc Ông Thọ","ja":"練乳（コンデンスミルク）","ko":"베트남 연유"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"vietName":"Sữa đặc Ông Thọ","vietPronunciation":"Seu-ah Dahk"},{"id":"robusta-coffee","name":{"zh-TW":"得勒省深焙羅布斯塔咖啡粉 (用 Phin 濾壺萃取 80ml 濃黑咖啡)","en":"Dark Roast Vietnamese Robusta Coffee (Brewed via Phin to 80ml)","vi":"Cà phê bột Robusta Đắk Lắk nguyên chất","ja":"ダクラク産ロブスタ深煎りコーヒー粉（フィン抽出80ml）","ko":"베트남 다크 로부스타 원두 (핀으로 추출한 진한 커피 80ml)"},"amount":25,"unitMetric":"g","unitUS":"0.9 oz","isKeyFlavor":true,"vietName":"Cà phê Robusta pha phin","vietPronunciation":"Cah Feh Roh-boo-stah"},{"id":"vanilla-rum","name":{"zh-TW":"香草精或白朗姆酒 (去除蛋腥味秘訣)","en":"Vanilla Extract or Drops of White Rum (Removes egginess)","vi":"Tinh chất vani hoặc vài giọt rượu rum","ja":"バニラエッセンスまたはラム酒少々（卵臭さ消し）","ko":"바닐라 익스트랙 또는 럼주 몇 방울 (비린내 제거)"},"amount":0.5,"unitMetric":"tsp","unitUS":"0.5 tsp","vietName":"Tinh chất vani","vietPronunciation":"Vah-nee"},{"id":"cocoa-powder","name":{"zh-TW":"純無糖黑可可粉 (表面裝飾提味)","en":"Pure Unsweetened Cocoa Powder (For dusting)","vi":"Bột ca cao nguyên chất rắc mặt","ja":"無糖ココアパウダー（仕上げ用）","ko":"무가당 코코아 파우더 (장식용)"},"amount":0.5,"unitMetric":"tsp","unitUS":"0.5 tsp","vietName":"Bột ca cao","vietPronunciation":"Boht Cah Cow"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"用越式 Phin 濾壺滴濾深焙黑咖啡","en":"Slow-Drip Dark Robusta with Phin Filter","vi":"Pha cốt cà phê đen bằng phin truyền thống","ja":"フィン（金属フィルター）で濃厚ブラックを抽出","ko":"베트남 전통 핀 필터로 진한 블랙커피 내리기"},"instruction":{"zh-TW":"在 Phin 滴濾壺中放入 25g 深焙羅布斯塔咖啡粉，輕晃平整，放上壓板微壓。先注入 20ml 沸水（95°C）悶蒸 30 秒潤濕咖啡粉。接著注滿沸水加蓋，讓咖啡一滴滴緩慢滴入玻璃杯中，萃取出約 80ml 香氣厚重、帶有黑巧與焦香的濃縮黑咖啡。","en":"Add 25g dark roast robusta coffee into a Phin filter, level, and place the gravity press on top. Pour 20ml hot water (95°C) to bloom the grounds for 30s. Top up with boiling water, cover, and let it drip slowly for 4-5 mins to extract 80ml of intense, chocolatey black coffee.","vi":"Cho 25g bột cà phê vào phin, lắc nhẹ cho phẳng và gài nhẹ nắp chặn. Rót 20ml nước sôi 95°C ủ trong 30 giây cho cà phê nở đều. Châm đầy nước sôi và đậy nắp, để cà phê nhỏ giọt chậm rãi trong 4 phút thu về 80ml cốt cà phê đen sánh đặc thơm lừng.","ja":"フィンにコーヒー粉25gを入れ、中蓋を軽くセット。お湯20mlを注ぎ30秒蒸らします。その後お湯を満たしてフタをし、4〜5分かけてポタポタと80mlの極濃ブラックを抽出します。","ko":"핀 필터에 원두 25g을 넣고 속 뚜껑을 살짝 누릅니다. 뜨거운 물 20ml를 부어 30초간 불린 후 물을 가득 채워 4분간 천천히 80ml의 진한 커피를 추출합니다."},"durationSeconds":240,"image":"/images/vn/ca-phe-trung-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"高速打發金黃雲朵蛋黃奶霜","en":"Whip Egg Yolks & Condensed Milk into Velvety Cream","vi":"Đánh bông kem trứng vàng ươm mịn như mây","ja":"卵黄と練乳を泡立て器でふわふわのカスタード泡にする","ko":"핸드믹서로 노른자와 연유를 쫀쫀한 크림으로 휘핑하기"},"instruction":{"zh-TW":"在乾燥無水的小碗中放入 2 顆新鮮蛋黃、2 大匙煉乳與 2 滴香草精（去腥）。使用手持電動打蛋器，以高速持續攪打 2.5 至 3 分鐘！蛋黃液會從深橙色逐漸膨脹、乳化變淺，最後形成如絲緞般綿密、提起打蛋頭能拉出尖角且緩慢流動的厚實金黃奶霜。","en":"In a clean bowl, combine 2 egg yolks, 2 tbsp condensed milk, and vanilla. Whip using an electric hand mixer on high speed for 2.5-3 mins. The mixture will triple in volume, transforming from deep orange to a pale yellow, velvety custard foam that holds soft ribbons.","vi":"Cho 2 lòng đỏ trứng, 2 thìa sữa đặc và chút vani vào âu sạch. Dùng máy đánh trứng đánh ở tốc độ cao trong 2.5 - 3 phút. Hỗn hợp sẽ bông xốp gấp ba, chuyển từ màu cam sang vàng nhạt, sánh mịn bồng bềnh như mây mọng.","ja":"ボウルに卵黄2個、練乳大さじ2、バニラを入れます。電動ハンドミキサーの高速で2.5〜3分間一気に泡立てます！カスタード状に白っぽく膨らみ、リボン状に垂れる濃密な泡に仕上げます。","ko":"볼에 노른자 2개, 연유 2큰술, 바닐라를 넣습니다. 핸드믹서 고속으로 2.5~3분간 휘핑합니다. 색이 연한 레몬빛으로 변하며 부피가 3배로 부풀고 쫀쫀한 크림 상태가 됩니다."},"durationSeconds":180,"image":"/images/vn/ca-phe-trung-step2.jpg","crucialTips":{"zh-TW":"打發成功的標誌：蛋霜質地必須像半融化霜淇淋一樣濃稠！如果打發時間不夠，蛋霜倒入咖啡時會直接沈入杯底混成濁湯；打發充足的蛋霜密度小，會像雲朵般神奇浮在黑咖啡表面！","en":"Density test: Properly whipped egg cream must be dense yet airy enough to float effortlessly on top of the black coffee without sinking.","vi":"Đạt chuẩn: Kem trứng phải đủ độ sánh bông xốp để khi rót sẽ bồng bềnh nổi trọn vẹn trên mặt cà phê đen mà không bị chìm lỉm.","ja":"成功のサイン：十分に泡立ったクリームは比重が軽くなり、コーヒーに注いだ時に沈まず雲のようにプカプカと表面に浮かびます！","ko":"성공 포인트: 충분히 휘핑하여 크림의 밀도를 낮춰야 커피 위에 부었을 때 가라앉지 않고 구름처럼 둥둥 뜹니다."}},{"stepNumber":3,"title":{"zh-TW":"注入蛋霜分層，咖啡杯置入熱水浴保溫享用","en":"Layer Foam & Float Cup in Hot Water Bath","vi":"Rót lớp kem trứng bồng bềnh & ngâm bát nước nóng","ja":"クリームを静かに注ぎ・お湯を張った小鉢に浮かべて完成","ko":"크림 붓기 및 찻잔을 따뜻한 물에 중탕하여 서빙"},"instruction":{"zh-TW":"將熱黑咖啡倒入透明玻璃矮杯中（約半杯滿）。用刮刀輕緩將打發好的金黃蛋霜倒在咖啡上方，形成完美的黑黃雙色對比！表面薄薄撒上一層可可粉。河內老店獨門儀式感：將整個咖啡玻璃杯放入盛有一半滾水的小陶瓷碗中（水浴保溫）端上桌！用小茶匙先舀一口如慕斯般溫甜綿密的蛋霜品嚐，再深深插到底部連同苦濃咖啡一同送入口中！","en":"Pour hot black coffee into a transparent glass cup halfway. Gently spoon the golden egg sabayon over the top, creating a breathtaking two-toned contrast. Dust with cocoa powder. Hanoi Cafe Giang ritual: Rest the coffee glass inside a ceramic bowl filled halfway with boiling water (to keep it warm while sipping). Spoon the sweet custard first, then plunge deep to taste the bitter coffee underneath!","vi":"Rót cà phê đen nóng vào nửa ly thủy tinh. Dùng thìa nhẹ nhàng múc lớp kem trứng phủ đầy nửa ly còn lại, tạo nên hai tầng đen-vàng tương phản tuyệt đẹp. Rắc chút bột ca cao lên mặt. Nghi thức Cà Phê Giảng: Đặt ly cà phê vào một chiếc bát sứ có chứa nước sôi nóng hổi để giữ nhiệt. Dùng thìa nhỏ múc từng ngụm kem trứng ngọt ngào hòa cùng cà phê đắng ngắt!","ja":"透明なグラスの半分まで熱いブラックコーヒーを注ぎます。上からふわふわの卵黄クリームをそっと重ね、見事な二層仕立てに。ココアパウダーを振ります。名店カフェ・ジャンの儀式：お湯を張った小鉢の中にグラスごと浮かべて保温しながら提供。スプーンでまずは甘いカスタードを味わい、底の苦いコーヒーと一緒にすくって召し上がれ！","ko":"투명한 잔에 뜨거운 블랙커피를 절반 정도 붓습니다. 그 위에 쫀쫀한 달걀 크림을 조심스럽게 올려 흑과 황의 투톤 레이어를 완성합니다. 코코아 파우더를 솔솔 뿌립니다. 하노이 카페 장 원조 방식대로 뜨거운 물이 담긴 볼에 잔을 중탕하여 온기를 유지하며 티스푼으로 떠먹습니다!"},"durationSeconds":60,"image":"/images/vn/ca-phe-trung-step3.jpg"}],"troubleshooting":[{"id":"ca-phe-trung-eggy-odor","problem":{"zh-TW":"雞蛋咖啡聞起來有明顯生雞蛋腥味，難以入口","en":"Egg coffee tastes raw or has an unpleasant eggy smell","vi":"Cà phê trứng bị tanh mùi trứng sống","ja":"生卵独特の生臭さが鼻について飲みにくい","ko":"달걀 비린내가 심하게 나서 마시기 힘들어요"},"cause":{"zh-TW":"1. 雞蛋不夠新鮮；2. 蛋清沒有完全分離（蛋白是腥味的主要來源）；3. 黑咖啡溫度不夠滾燙無法利用餘溫熟化蛋霜。","en":"1. Eggs were not fresh; 2. Incomplete separation of egg white (whites carry the smell); 3. Coffee was not hot enough to gently steam the foam.","vi":"1. Trứng không tươi; 2. Dính lòng trắng trứng (lòng trắng gây tanh); 3. Cà phê không đủ nóng.","ja":"1. 卵の鮮度が悪かった。2. 白身が混ざってしまった（生臭さの原因は白身）。3. コーヒーの温度が低かった。","ko":"1. 계란이 신선하지 않았거나 2. 흰자가 섞였거나(흰자가 비린내의 주원인) 3. 커피가 뜨겁지 않았기 때문입니다."},"solution":{"zh-TW":"只取純蛋黃，並加入幾滴優質香草精或白朗姆酒；黑咖啡必須滾燙萃取，且將杯子浸泡在熱水浴碗中，高溫蒸氣會徹底去腥並將蛋霜溫熟成絲滑卡士達！","en":"Use strictly yolk only, add a splash of rum or vanilla, and ensure the coffee is piping hot in a water bath.","vi":"Tách thật sạch lòng trắng, thêm chút vani hoặc giọt rượu rum, và luôn ngâm ly trong bát nước sôi.","ja":"白身を完全に除き、バニラオイルかラム酒を数滴加えます。必ず熱湯風呂にグラスを浸して温めてください。","ko":"흰자를 완벽히 제거하고 바닐라나 럼주를 몇 방울 넣으세요. 커피를 펄펄 끓여 중탕기에 담아 서빙하면 비린내가 완벽히 사라집니다."}}],"proTips":[{"zh-TW":"河內老字號品嚐禮儀：喝雞蛋咖啡不要一開始就拿攪拌棒攪成整杯混濁的咖啡牛奶！正確喝法是用附帶的小銀匙，先單獨挖一口上層綿甜的蛋黃慕斯，感受濃醇奶香；接著將小匙插到杯底，同時舀起熱咖啡與冷蛋霜，在舌尖感受冷與熱、甜與苦的冰火交融！","en":"Authentic Hanoi etiquette: Never stir the whole cup into a muddy latte! Use the tiny spoon to taste the sweet warm custard foam first, then plunge the spoon deep to capture both black bitter coffee and sweet cream in one heavenly sip.","vi":"Nghệ thuật thưởng thức: Đừng vội khuấy tan ly cà phê! Hãy dùng thìa nhỏ xúc một ngụm kem trứng vàng ươm để cảm nhận độ béo ngọt, rồi cắm thìa sâu xuống đáy múc cả cà phê đắng cùng kem trứng để cảm nhận sự hòa quyện đỉnh cao.","ja":"本場ハノイの飲み方マナー：いきなり全部をかき混ぜてカフェオレにしてしまうのは野暮！スプーンでまず上の温かいカスタード泡だけを味わい、次に底まで深くスプーンを入れて苦いコーヒーと一緒にすくって口へ運びます。","ko":"하노이 정통 에티켓: 처음부터 다 섞어서 마시지 마세요! 작은 스푼으로 달콤한 에그 크림을 먼저 떠먹은 뒤, 스푼을 잔 바닥까지 깊숙이 넣어 쌉싸름한 블랙커피와 크림을 한 번에 떠먹는 것이 정석입니다."}]},{"country":"vn","id":"nom-du-du","slug":"nom-du-du","title":{"zh-TW":"河內老街青木瓜五香牛肉乾涼拌","en":"Hanoi Green Papaya & Beef Jerky Salad (Nộm Đu Đủ Bò Khô)","vi":"Nộm Đu Đủ Bò Khô Hà Nội","ja":"ハノイ名物 青パパイヤと自家製ビーフジャーキーの和え物（ノム・ドゥ・ドゥ）","ko":"하노이 정통 그린 파파야 소고기 육포 샐러드 (놈두두)"},"subtitle":{"zh-TW":"爽脆青木瓜絲・蜜汁五香牛肉乾・香脆炒花生・酸甜生津魚露汁","en":"Crisp Green Papaya with Savory Spiced Beef Jerky, Crushed Peanuts & Sweet Chili Dressing","vi":"Đu đủ bào sợi giòn sần sật, bò khô cay ngọt đậm đà, đậu phộng rang giã dập","ja":"シャキシャキの青パパイヤ・旨辛ビーフジャーキーと香ばしいピーナッツの極上ハーモニー","ko":"아삭한 청파파야 채와 매콤달콤한 소고기 육포, 고소한 땅콩과 상큼한 피시소스"},"tagline":{"zh-TW":"河內老城街邊最受年輕人迷戀的冰涼開胃小吃，酸甜冰脆中帶著牛肉乾的濃郁嚼勁","en":"Hanoi’s favorite afternoon streetside crunch—refreshing, tangy, and deeply addictive","vi":"Món ăn vặt trứ danh của giới trẻ Hà Thành bên hồ Hoàn Kiếm se lạnh","ja":"ハノイ旧市街の路地で愛され続ける国民的スナック。ビールとの相性も抜群","ko":"하노이 호안끼엠 호수 주변을 거닐며 즐기는 최고의 상큼바삭 길거리 샐러드"},"heroImage":"/images/vn/nom-du-du.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":5,"defaultServings":2,"caloriesPerServing":240,"category":"salads","dietaryTags":["classic","glutenFree"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"北部・河內老城區 (Phố Hồ Hoàn Kiếm)","en":"Northern Vietnam / Hanoi Old Quarter","vi":"Miền Bắc / Phố cổ Hà Nội (Phố Hoàn Kiếm)","ja":"北部・ハノイ旧市街ホアンキエム通り","ko":"베트남 북부 / 하노이 구시가지"},"famousStreetMarkets":[{"zh-TW":"河內湖環劍街 (Nộm Long Vi Dung)","en":"Nom Long Vi Dung (Hanoi Shortest Street)","vi":"Nộm Long Vi Dung (Phố Hồ Hoàn Kiếm)","ja":"ハノイ ロンヴィズン","ko":"하노이 롱비중 파파야 샐러드"},{"zh-TW":"同春市場夜市 (Chợ Đồng Xuân)","en":"Dong Xuan Night Market Stalls","vi":"Chợ Đồng Xuân","ja":"ドンスアン夜市","ko":"동쑤언 야시장"}],"historyStory":{"zh-TW":"在河內最短的街道——只有 52 公尺長的「湖環劍街 (Phố Hồ Hoàn Kiếm)」，聚集著傳承數十年的青木瓜沙拉名店。不同於泰國青木瓜沙拉 (Som Tum) 用木臼猛烈搗爛的做法，河內人講究刀工，將堅硬的青木瓜刨成晶瑩細長的脆絲，泡冰水保持極致爽脆，拌入特製蜜汁五香牛肉乾 (Bò khô)、炸牛脾 (Lá lách)、香脆花生粒與新鮮薄荷葉，淋上以醋糖魚露調和的清爽醬汁。","en":"On Hanoi’s shortest street—the 52-meter Ho Hoan Kiem street near the lake—lies Vietnam’s epicentre of Nộm. Unlike Thai Som Tum which is vigorously pounded in a mortar, Hanoi chefs delicately shred raw green papaya into crisp translucent threads, ice-shocked for maximum crunch, topped with sweet-spiced beef jerky, roasted peanuts, mint, and a clear sweet-tart fish sauce vinaigrette.","vi":"Phố Hồ Hoàn Kiếm chỉ dài vỏn vẹn 52 mét nhưng là thủ phủ của món nộm bò khô Hà Thành. Không giã dập trong cối như gỏi đu đủ Thái, người Hà Nội bào đu đủ thành sợi mỏng dài giòn sần sật, trộn cùng thịt bò khô thái lát cay ngọt, lá lách chiên thơm bùi, đậu phộng rang và rau kinh giới thơm nồng, chan nước mắm giấm đường thanh tao.","ja":"ハノイで最も短い通り（全長52m）に名店がひしめく名物料理。タイのソムタムのように叩いて潰すのではなく、氷水にさらした極細の青パパイヤのシャキシャキ感を主役に、甘辛い特製ビーフジャーキーとハーブを合わせます。","ko":"하노이에서 가장 짧은 52m 길이의 호안끼엠 거리에서 유명해진 대표 샐러드입니다. 절구에 빻는 태국 솜땀과 달리, 얇게 채 썰어 얼음물에 담가 아삭함을 극대화한 파파야에 달콤 매콤한 소고기 육포를 곁들입니다."},"vietScript":"Nộm Đu Đủ Bò Khô","vietPhonetics":"Nom Doo Doo Baw Kaw","audioPronunciationText":"Cho tôi hai đĩa nộm đu đủ bò khô đầy đủ nhiều lạc rang!"},"ingredients":[{"id":"green-papaya","name":{"zh-TW":"新鮮未熟青木瓜 (去皮刨細長絲，泡冰水 10 分鐘極致爽脆)","en":"Raw Green Papaya (Peeled & shredded into long threads, iced)","vi":"Đu đủ xanh bào sợi dài ngâm nước đá","ja":"青パパイヤ（千切りにして氷水で締める）","ko":"풋 파파야 (채 썰어 얼음물에 담가 아삭하게 만든 것)"},"amount":300,"unitMetric":"g","unitUS":"10.5 oz","isKeyFlavor":true,"vietName":"Đu đủ xanh bào sợi","vietPronunciation":"Doo Doo Sahn"},{"id":"beef-jerky-spiced","name":{"zh-TW":"越式蜜汁五香軟牛肉乾 (Bò khô 剪成細條)","en":"Vietnamese Spiced Beef Jerky (Bò Khô, snipped into strips)","vi":"Thịt bò khô miếng cay ngọt xé sợi","ja":"ベトナム風甘辛ビーフジャーキー（細切り）","ko":"베트남식 매콤달콤 소고기 육포 (보코)"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"vietName":"Thịt bò khô","vietPronunciation":"Teet Baw Kaw"},{"id":"roasted-peanuts","name":{"zh-TW":"香脆烘焙熟花生粒 (粗碎)","en":"Roasted Peanuts (Coarsely crushed)","vi":"Lạc (đậu phộng) rang giòn giã dập","ja":"香ばしいローストピーナッツ（粗砕き）","ko":"볶은 땅콩 분태"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"vietName":"Lạc rang giã dập","vietPronunciation":"Lahk Zahng"},{"id":"fresh-herbs-mint","name":{"zh-TW":"新鮮綠薄荷、香薷 (Kinh giới) 與芫荽碎","en":"Fresh Spearmint, Kinh Giới Balm & Cilantro","vi":"Rau kinh giới & húng lủi thái nhỏ","ja":"スペアミント、キンゾイ、パクチー","ko":"스피아민트, 킨조이 허브, 고수"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Rau kinh giới húng lủi","vietPronunciation":"Rao Keen Zeu-oy"},{"id":"nom-dressing","name":{"zh-TW":"特調甘爽涼拌汁：白醋 3 大匙、砂糖 3 大匙、魚露 2 大匙、溫水 3 大匙、蒜蓉朝天椒碎","en":"Tangy Dressing: 3 tbsp Vinegar, 3 tbsp Sugar, 2 tbsp Fish Sauce, 3 tbsp Warm Water, Minced Garlic & Chili","vi":"Nước trộn nộm: Giấm thanh, đường, nước mắm, nước lọc, tỏi ớt băm","ja":"特製甘酢ダレ：米酢、砂糖、ヌクマム、ぬるま湯、刻みニンニク・唐辛子","ko":"특제 드레싱: 식초 3큰술, 설탕 3큰술, 피시소스 2큰술, 미온수 3큰술, 다진 마늘, 고추"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"vietName":"Nước trộn nộm chua ngọt","vietPronunciation":"Neu-oc Trown Nom"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"青木瓜刨絲與冰水冰鎮極脆處理","en":"Shred Papaya & Ice-Shock for Crispness","vi":"Bào sợi đu đủ & ngâm nước đá cho giòn tan","ja":"青パパイヤの千切りと氷水締め","ko":"파파야 채 썰기 및 얼음물에 담가 아삭함 살리기"},"instruction":{"zh-TW":"青木瓜削皮去籽，用刨絲器刨成均勻細長絲。立即投入大盆冰塊水中浸泡 10 分鐘，洗去多餘白色乳汁並讓木瓜絲吸收冰水極致收緊變脆！撈出後用乾淨廚房布徹底甩乾水分。","en":"Peel and seed the green papaya. Shred into long thin ribbons using a mandoline. Immediately submerge in an ice water bath for 10 mins to remove bitter sap and shock into peak crispness. Spin and dry thoroughly.","vi":"Gọt vỏ đu đủ xanh, nạo bỏ ruột hạt rồi dùng nạo bào thành sợi dài mỏng. Thả ngay vào chậu nước đá lạnh ngâm 10 phút cho ra hết mủ và sợi đu đủ giòn sần sật. Vớt ra vắt thật ráo nước.","ja":"青パパイヤの皮をむき、スライサーで長い千切りにします。すぐに氷水に10分間放ち、アクを抜くと同時に驚くほどのシャキシャキ感を引き出します。しっかりと水気を切ります。","ko":"풋 파파야의 껍질을 벗기고 씨를 파낸 뒤 채칼로 가늘고 길게 썹니다. 즉시 얼음물에 10분간 담가 떫은 수액을 빼고 아삭함을 극대화한 뒤 물기를 완전히 뺍니다."},"durationSeconds":120,"image":"/images/vn/nom-du-du-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"調製河內甘爽酸甜魚露汁","en":"Whisk Balanced Hanoi Sweet-Tart Vinaigrette","vi":"Pha nước chấm nộm chua ngọt thanh tao","ja":"ハノイ伝統の黄金甘酢ダレ作り","ko":"하노이 스타일 새콤달콤 샐러드 드레싱 만들기"},"instruction":{"zh-TW":"在碗中將白醋 3 大匙、砂糖 3 大匙、溫水 3 大匙攪拌至糖完全溶解。淋入優質魚露 2 大匙，撒入細蒜蓉與切碎鮮紅朝天椒圈，攪勻試味，達到完美的酸甜生津平衡。","en":"Whisk 3 tbsp rice vinegar, 3 tbsp sugar, and 3 tbsp warm water until sugar dissolves. Stir in 2 tbsp fish sauce, finishing with minced garlic and red chili rings. The flavor should be delightfully sweet, sour, and mildly garlicky.","vi":"Hòa tan 3 thìa giấm, 3 thìa đường trong 3 thìa nước ấm. Rót 2 thìa nước mắm ngon vào khuấy đều, thêm tỏi ớt băm nhuyễn để có bát nước sốt nộm chua ngọt thanh nhẹ.","ja":"ボウルに酢大さじ3、砂糖大さじ3、ぬるま湯大さじ3を入れて砂糖を溶かします。ヌクマム大さじ2、ニンニク、唐辛子を加え、爽やかな甘酸っぱさに調味します。","ko":"볼에 식초 3큰술, 설탕 3큰술, 미온수 3큰술을 넣고 설탕을 녹입니다. 피시소스 2큰술, 다진 마늘, 송송 썬 고추를 넣어 새콤달콤하게 완성합니다."},"durationSeconds":90,"image":"/images/vn/nom-du-du-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"堆疊木瓜絲、牛肉乾，撒花生淋汁拌勻","en":"Assemble Papaya, Beef Jerky & Dress Freshly","vi":"Bày nộm: Xếp đu đủ, bò khô, rắc đậu phộng & rưới sốt","ja":"パパイヤを盛り・ビーフジャーキーとピーナッツを散らしてタレをかける","ko":"파파야 담기, 소고기 육포와 땅콩 얹고 소스 뿌려 버무리기"},"instruction":{"zh-TW":"將極脆青木瓜絲盛在大盤中央，上面鋪滿切成細條的蜜汁五香牛肉乾 (Bò khô)。撒入大量切碎的薄荷、香薷與香菜，豪邁撒滿 3 大匙香脆熟碎花生。將調好的酸甜汁沿四周均勻淋下，用筷子快速翻拌幾下即可享用！每一口都是透心涼的爽脆與牛肉乾的濃郁回甜！","en":"Mound shredded green papaya in the center of a serving dish. Pile generously with strips of spiced beef jerky. Scatter fresh mint, Kinh Giới herbs, and 3 tbsp crushed roasted peanuts on top. Drizzle the tangy dressing all over just before serving. Toss immediately and crunch away!","vi":"Gắp đĩa đu đủ xanh giòn rụm vun cao ở giữa đĩa. Xếp đầy ắp từng thớ thịt bò khô xé sợi màu nâu đỏ. Rải nhiều rau kinh giới húng lủi và 3 thìa đậu phộng rang giòn. Rưới đẫm nước sốt chua ngọt lên trên, dùng đũa trộn đều và thưởng thức ngay vị giòn mát cay ngọt!","ja":"冷えたパパイヤをお皿に高く盛り付け、甘辛いビーフジャーキーをたっぷり乗せます。ミントやハーブ、砕きピーナッツ大さじ3を散らします。食べる直前にタレを回しかけ、手早く和えていただきます！","ko":"그릇에 아삭한 파파야 채를 소복이 담고 소고기 육포를 듬뿍 올립니다. 민트와 허브, 볶음 땅콩 분태 3큰술을 뿌려줍니다. 먹기 직전에 드레싱을 둘러 가볍게 비벼서 드세요!"},"durationSeconds":60,"image":"/images/vn/nom-du-du-step3.jpg"}],"troubleshooting":[{"id":"nom-du-du-watery","problem":{"zh-TW":"涼拌菜拌好放一會兒就大量出水，木瓜絲變軟不脆","en":"Salad became watery and papaya lost its crunch after resting","vi":"Nộm bị chảy nhiều nước, sợi đu đủ bị ỉu mềm nhũn","ja":"時間が経つと水っぽくなり、パパイヤがしんなりしてしまった","ko":"시간이 지나자 물이 많이 생기고 파파야가 눅눅해졌어요"},"cause":{"zh-TW":"1. 冰鎮後的木瓜絲未甩乾水分；2. 太早將醬汁淋入涼拌菜中，鹽分造成木瓜脫水。","en":"1. Papaya was not dried well after ice bath; 2. Dressed too early, causing osmosis.","vi":"1. Chưa vắt kiệt nước sau khi ngâm đá; 2. Rưới nước sốt quá sớm làm đu đủ bị ra nước.","ja":"1. 氷水から上げた後の水切りが甘かった。2. 早くからタレを和えて浸透圧で水が出てしまった。","ko":"1. 얼음물에서 건진 뒤 물기를 덜 털었거나 2. 드레싱을 너무 일찍 뿌려 삼투압으로 수분이 빠져나왔기 때문입니다."},"solution":{"zh-TW":"木瓜絲務必用乾淨廚房布或蔬菜脫水機甩得極乾！且「絕對要在上桌吃的那一刻」才淋入醬汁，現拌現吃才能保持玻璃般的清脆！","en":"Spin papaya bone-dry with a salad spinner. Dress ONLY at the very second of serving.","vi":"Vắt thật kiệt nước bằng khăn sạch. Chỉ rưới nước sốt ngay trước khi ăn.","ja":"サラダスピナーで完全に水分を飛ばし、必ず「食べる直前」にタレをかけてください。","ko":"야채 탈수기로 물기를 완벽히 제거하고, 반드시 ‘식탁에 내어 먹기 직전’에 드레싱을 부어 비벼 드세요."}}],"proTips":[{"zh-TW":"河內傳統經典組合——「青木瓜涼拌 + 炭烤豬肉米線 (Bún Chả)」：在河內老城區，老饕們吃午餐時常在 Bún Chả 旁邊點一小盤青木瓜牛肉乾沙拉，酸甜爽脆的木瓜絲能瞬間清除炭火烤肉的油膩，是天生一對！","en":"Hanoi pairing secret: Locals frequently order Nộm alongside Bún Chả. The cold fruity crunch clears your palate between rich smoky bites of grilled pork!","vi":"Cặp đôi hoàn hảo: Người Hà Nội thường ăn nộm bò khô kèm bún chả hoặc nem rán để chống ngấy tuyệt hảo!","ja":"ハノイ通の組み合わせ：ブンチャーや揚げ春巻きのお供にこのパパイヤサラダを合わせるのが大定番。脂っこさをリフレッシュするのに最高です。","ko":"하노이 꿀조합 팁: 분짜나 짜조를 먹을 때 놈두두를 함께 곁들여보세요. 상큼하고 아삭한 맛이 고기의 느끼함을 완벽하게 씻어줍니다."}]},{"country":"vn","id":"che-ba-mau","slug":"che-ba-mau","title":{"zh-TW":"越南經典彩虹三色冰 (椰奶三色甜品杯)","en":"Vietnamese Three-Color Sweet Drink (Chè Ba Màu)","vi":"Chè Ba Màu Sài Gòn","ja":"ベトナム伝統の三色チェー（チェー・バー・マウ）","ko":"베트남식 삼색 코코넛 빙수 / 달콤한 디저트 (째바마우)"},"subtitle":{"zh-TW":"蜜甜紅豆・綿滑黃綠豆沙・翡翠斑蘭果凍條・醇厚椰奶與滿杯碎冰","en":"Sweet Red Beans, Silky Mung Bean Paste, Pandan Jelly & Rich Coconut Cream","vi":"Đậu đỏ ngọt bùi, đậu xanh tán nhuyễn, thạch trân châu lá dứa xanh ngọc, nước cốt dừa","ja":"あずき・滑らかな緑豆あん・翡翠色のパンダンゼリー・濃厚ココナッツミルクと氷","ko":"달콤한 팥, 부드러운 녹두 앙금, 비취빛 판단 젤리, 진한 코코넛 밀크와 간 얼음"},"tagline":{"zh-TW":"熱帶街頭色彩斑斕的消暑皇后，以長匙深深插到底部攪拌，口口甜蜜冰涼","en":"The colorful reigning queen of tropical street desserts—layers of creamy coconut bliss","vi":"Món chè giải nhiệt thanh mát rực rỡ sắc màu của mọi con phố Sài Gòn","ja":"カラフルで見た目も可愛いベトナムの国民的デザート。よく混ぜて召し上がれ！","ko":"알록달록한 색감과 고소한 코코넛 밀크가 어우러진 베트남의 국민 디저트"},"heroImage":"/images/vn/che-ba-mau.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":25,"defaultServings":2,"caloriesPerServing":310,"category":"dessertsDrinks","dietaryTags":["classic","vegetarian","vegan","glutenFree"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"南部・胡志明市 (西貢甜品街)","en":"Southern Vietnam / Saigon Sweet Street Stalls","vi":"Miền Nam / Sài Gòn","ja":"南部・サイゴン（ホーチミン市）","ko":"베트남 남부 / 사이공"},"famousStreetMarkets":[{"zh-TW":"西貢第五郡華人區 (Chè Hà Ký)","en":"Che Ha Ky (Chinatown District 5)","vi":"Chè Hà Ký (Quận 5)","ja":"サイゴン5区 ハーキー中華甘味店","ko":"호찌민 5군 하끼 디저트 전문점"},{"zh-TW":"檳城市場甜品排檔 (Chè Bến Thành)","en":"Ben Thanh Market Sweet Stalls","vi":"Chợ Bến Thành","ja":"ベンタイン市場チェー屋台","ko":"벤탄 시장 째 노점"}],"historyStory":{"zh-TW":"Chè 是越南所有甜湯、甜品、冷熱糖水的統稱。南部氣候四季如夏，冰涼爽口的「Chè Ba Màu (三色甜品)」是最受歡迎的消暑聖品。三色分別代表：紅色的蜜紅豆（象徵幸運）、黃色的綿滑熟綠豆泥（象徵溫潤福氣）、翠綠色的斑蘭葉果凍粉條（象徵生機清涼）。在高玻璃杯中依序疊起三色彩虹，澆上加了少許鹽花提鮮的厚重熱帶椰漿與滿滿碎冰，甜蜜沁心。","en":"‘Chè’ is the overarching Vietnamese term for traditional sweet soups and dessert puddings. In the year-round heat of the south, Chè Ba Màu (literally ‘Three-Color Dessert’) reigns supreme. The vibrant trio represents: red sweetened kidney/adzuki beans (luck), yellow silky mashed mung bean paste (prosperity), and translucent green pandan jelly ribbons (fresh vitality), smothered in salted coconut cream and crushed ice.","vi":"Chè là món tráng miệng truyền thống ăn sâu vào tiềm thức của người Việt. Chè Ba Màu là sự hòa quyện tuyệt mỹ của ba sắc màu may mắn: màu đỏ của đậu đỏ ngọt bùi, màu vàng của đậu xanh đánh nhuyễn mịn màng, và màu xanh ngọc của thạch lá dứa thanh mát. Tất cả ngập trong lớp nước cốt dừa béo ngậy và đá bào mát lạnh.","ja":"「チェー」はベトナムの伝統的な甘味スイーツの総称。年中暑い南部で愛される三色チェーは、赤い小豆（幸運）、黄色い緑豆あん（豊かさ）、緑のパンダンリーフゼリー（爽快感）が鮮やかに層を成し、塩をひとつまみ効かせたココナッツミルクをかけて楽しみます。","ko":"‘째’는 베트남 전통 디저트를 뜻합니다. 째바마우는 붉은 팥(행운), 노란 녹두 앙금(풍요), 초록빛 판단 젤리(활력) 세 가지 색이 어우러져 단짠의 코코넛 크림과 함께 비벼 먹는 여름철 최고의 별미입니다."},"vietScript":"Chè Ba Màu Sài Gòn","vietPhonetics":"Cheh Bah Mow","audioPronunciationText":"Cho tôi hai ly chè ba màu nhiều nước cốt dừa và đá bào!"},"ingredients":[{"id":"red-beans","name":{"zh-TW":"蜜甜紅豆 / 大紅芸豆 (煮透軟糯帶糖蜜甜味)","en":"Sweetened Soft Red Beans / Adzuki","vi":"Đậu đỏ ninh mềm ngào đường","ja":"甘く煮た小豆または金時豆","ko":"달콤하게 조린 팥 / 강낭콩"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":true,"vietName":"Đậu đỏ ngọt","vietPronunciation":"Doh Daw"},{"id":"mung-bean-paste","name":{"zh-TW":"去皮黃綠豆泥 (煮熟加糖攪拌成如卡士達般綿滑豆泥)","en":"Silky Sweetened Mung Bean Paste (Peeled split mung beans)","vi":"Đậu xanh cà vỏ nấu nhuyễn","ja":"滑らかな黄緑豆あん","ko":"부드러운 녹두 앙금"},"amount":120,"unitMetric":"g","unitUS":"4.2 oz","isKeyFlavor":true,"vietName":"Đậu xanh đánh nhuyễn","vietPronunciation":"Doh Sahn"},{"id":"pandan-jelly","name":{"zh-TW":"翡翠斑蘭葉果凍粉條或木薯條 (天然芳香草本綠色)","en":"Green Pandan Jelly Strips (Cendol / Bánh Lọt)","vi":"Thạch lá dứa / bánh lọt xanh thơm","ja":"パンダンリーフゼリー（翡翠色のゼリー細切り）","ko":"초록빛 판단 젤리 국수"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":true,"vietName":"Thạch lá dứa","vietPronunciation":"Tahk Lah Zeu-ah"},{"id":"coconut-cream-sauce","name":{"zh-TW":"特調厚椰漿淋醬：椰漿 150ml + 砂糖 1 大匙 + 鹽花 1/4 小匙 (煮開微濃稠)","en":"Salted Coconut Drizzle: 150ml Coconut Cream + 1 tbsp Sugar + 1/4 tsp Sea Salt (Gently thickened)","vi":"Nước cốt dừa sánh béo dằn chút muối","ja":"塩味を効かせた特製ココナッツクリームソース","ko":"소금을 살짝 가미한 진한 코코넛 크림 소스"},"amount":150,"unitMetric":"ml","unitUS":"5 fl oz","isKeyFlavor":true,"vietName":"Nước cốt dừa chan chè","vietPronunciation":"Neu-oc Coht Zeu-ah"},{"id":"crushed-ice-peanuts","name":{"zh-TW":"細緻碎冰 (滿杯) 與炒熟去皮花生碎","en":"Crushed Ice (Generous mound) & Toasted Peanuts","vi":"Đá bào nhuyễn & đậu phộng rang giòn","ja":"クラッシュアイス山盛り＆炒りピーナッツ","ko":"간 얼음 가득 및 볶음 땅콩 분태"},"amount":1,"unitMetric":"piece","unitUS":"piece","vietName":"Đá bào, đậu phộng","vietPronunciation":"Dah Bow"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"慢火煮透綿密綠豆沙與蜜紅豆","en":"Cook Silky Mung Bean Paste & Sweet Red Beans","vi":"Nấu nhuyễn đậu xanh & ngào đường đậu đỏ","ja":"緑豆あん作りと小豆の甘煮","ko":"부드러운 녹두 앙금과 달콤한 팥 조리기"},"instruction":{"zh-TW":"去皮黃綠豆浸泡 1 小時，加水煮爛後用打蛋器打成細膩柔滑的豆沙糊，加 2 大匙糖微火煮稠放涼。紅豆同樣加糖慢火煮至軟爛綿密放涼備用。","en":"Soak peeled mung beans for 1 hour, simmer in water until soft, and mash with a whisk into a smooth puree with 2 tbsp sugar; let cool. Cook red beans with sugar until tender and syrup-glazed.","vi":"Ngâm đậu xanh 1 giờ, nấu chín mềm rồi dùng phới đánh nhuyễn mịn với 2 thìa đường, đun nhỏ lửa cho sánh lại để nguội. Đậu đỏ nấu chín mềm ngào đường.","ja":"皮むき緑豆を1時間浸水させ、柔らかく煮て泡立て器で滑らかなペースト状にし、砂糖大さじ2を加えて冷まします。小豆も砂糖で柔らかく甘煮にします。","ko":"껍질 벗긴 녹두를 불려 푹 삶은 뒤 설탕 2큰술을 넣고 곱게 으깨어 부드러운 앙금을 만듭니다. 팥도 설탕에 달콤하게 조려 식혀둡니다."},"durationSeconds":300,"image":"/images/vn/che-ba-mau-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"微火調煮帶有微鹹層次的特濃椰奶汁","en":"Simmer Thick Coconut Cream with a Pinch of Salt","vi":"Nấu nước cốt dừa thơm béo dằn chút muối biển","ja":"隠し塩を効かせた濃厚ココナッツクリーム作り","ko":"소금을 살짝 넣어 풍미를 살린 코코넛 소스 끓이기"},"instruction":{"zh-TW":"小鍋中倒入濃純椰漿 150ml，加 1 大匙砂糖與 1/4 小匙海鹽（鹽花是越南甜品畫龍點睛之筆，能引爆椰奶甘甜！）。加入 1 小匙木薯粉水勾薄芡，微火加熱至起微泡濃稠關火放涼。","en":"In a saucepan, warm 150ml coconut cream with 1 tbsp sugar and 1/4 tsp sea salt (the salt is the magic touch that elevates the coconut sweetness!). Stir in 1 tsp tapioca starch slurry to thicken lightly. Let cool.","vi":"Đun 150ml nước cốt dừa với 1 thìa đường và 1/4 thìa muối biển (chút muối giúp vị ngọt của cốt dừa sâu lắng và béo ngậy hơn). Hòa chút bột năng tạo độ sánh nhẹ, đun sôi lăn tăn rồi tắt bếp để nguội.","ja":"小鍋にココナッツクリーム150ml、砂糖大さじ1、天然塩小さじ1/4を入れます（塩気がココナッツの甘みを驚くほど引き立てます！）。少量のタピオカ水溶きを加えてとろみをつけ、冷まします。","ko":"작은 냄비에 코코넛 크림 150ml, 설탕 1큰술, 소금 1/4작은술을 넣습니다(소금이 단맛과 고소함을 극대화합니다). 전분물을 살짝 풀어 걸쭉하게 식혀둡니다."},"durationSeconds":120,"image":"/images/vn/che-ba-mau-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"彩虹分層疊入高杯，覆蓋滿杯碎冰與淋椰奶","en":"Layer the Colors in Tall Glass, Heap Ice & Drizzle Cream","vi":"Tạo tầng màu rực rỡ trong ly cao, phủ đá bào & rưới nước cốt dừa","ja":"グラスに鮮やかに三色を重ね・氷とココナッツを注いで完成","ko":"유리잔에 삼색 레이어 담기, 간 얼음 얹고 코코넛 소스 끼얹기"},"instruction":{"zh-TW":"準備高透明玻璃杯。底層舀入 2-3 大匙蜜紅豆（紅），中層平鋪 2-3 大匙綿密綠豆沙（黃），上層鋪上晶瑩翠綠斑蘭葉果凍條（綠），形成美麗的三色漸層！在杯頂堆上一大座如雪山般的高聳碎冰，豪邁淋上 3-4 大匙特調鹹甜濃椰漿，撒上一小匙脆熟花生粒！附上長柄小匙與粗吸管端上桌，攪拌享用！","en":"Take a tall clear glass. Layer 3 tbsp sweet red beans at the base (Red), followed by 3 tbsp smooth mung bean paste (Yellow), and topped with vibrant green pandan jelly ribbons (Green). Heap with a mountain of finely crushed shaved ice, drenched generously with 3-4 tbsp salted coconut cream and toasted peanuts. Serve with a long sundae spoon and wide boba straw!","vi":"Chuẩn bị ly thủy tinh cao. Múc 3 thìa đậu đỏ vào đáy ly (đỏ), tiếp theo múc 3 thìa đậu xanh tán mịn (vàng), rồi phủ lớp thạch lá dứa xanh mướt lên trên (xanh). Đắp ngọn núi đá bào nhuyễn lên đầy ly, rưới đẫm 3-4 thìa nước cốt dừa béo ngậy và rắc đậu phộng rang giòn. Cắm thìa dài và ống hút lớn, khuấy đều và thưởng thức ngay!","ja":"背の高い透明グラスを用意します。底にあずき（赤）、中間になめらかな緑豆あん（黄）、上に翡翠色のパンダンゼリー（緑）を重ねて見事なグラデーションを作ります。山盛りのクラッシュアイスを乗せ、塩ココナッツクリームをたっぷり回しかけ、ピーナッツをトッピング！長いスプーンでよく混ぜて召し上がれ！","ko":"긴 유리잔에 달콤한 팥(빨강), 부드러운 녹두 앙금(노랑), 싱그러운 판단 젤리(초록)를 순서대로 쌓아 올립니다. 간 얼음을 소복하게 얹고 진한 코코넛 크림 3~4큰술과 땅콩을 뿌려줍니다. 긴 스푼으로 골고루 저어 시원하게 즐기세요!"},"durationSeconds":60,"image":"/images/vn/che-ba-mau-step3.jpg"}],"troubleshooting":[{"id":"che-ba-mau-too-sweet","problem":{"zh-TW":"三色冰喝到一半覺得過於甜膩口渴","en":"Dessert tastes overly sweet and cloying midway through","vi":"Chè bị ngọt gắt cổ, mau ngấy","ja":"甘すぎて途中で重く感じてしまう","ko":"너무 달아서 먹다 보면 물려요"},"cause":{"zh-TW":"碎冰加得太少，或椰奶中沒有加入微量鹽花調和。","en":"Not enough crushed ice, or omitted the pinch of salt in the coconut cream.","vi":"Cho quá ít đá bào hoặc quên dằn muối trong nước cốt dừa.","ja":"氷の量が足りなかったか、ココナッツクリームの塩を省いてしまった。","ko":"얼음이 적었거나 코코넛 크림에 소금을 넣지 않았기 때문입니다."},"solution":{"zh-TW":"補入大量細碎冰並用長匙充分攪拌稀釋！越式甜品中的椰漿一定要加微量海鹽，鹽分能有效抑制死甜感，轉化為醇厚回甘。","en":"Add plenty of finely crushed ice and stir thoroughly. Always add salt to the coconut cream.","vi":"Thêm nhiều đá bào và khuấy đều. Luôn dằn chút muối vào nước cốt dừa để hãm ngọt.","ja":"クラッシュアイスをたっぷり足してよく混ぜます。ココナッツミルクの隠し塩は必須です。","ko":"간 얼음을 넉넉히 넣고 잘 저어 드세요. 코코넛 크림에 소금을 꼭 넣어야 단맛이 깔끔해집니다."}}],"proTips":[{"zh-TW":"西貢老街吃法儀式：剛端上桌時三色分層極美，拍照打卡完畢後，一定要拿長長的不鏽鋼匙，深深插到底部用力「大搗特搗」！將硬挺的冰山、冰水、黏糯的紅豆、綿軟綠豆沙與椰奶完全搗碎攪拌成稠稠的奶昔狀，用粗吸管大口吸食，每一口都是幸福！","en":"Saigon street ritual: After admiring and photographing the colorful layers, plunge the long spoon to the very bottom and vigorously smash and churn everything together! The shaved ice, beans, jelly, and coconut milk meld into a dreamy thick tropical milkshake consistency.","vi":"Nghi thức ăn chè đường phố: Sau khi ngắm nghía và chụp ảnh những tầng màu xinh đẹp, hãy cắm sâu chiếc thìa dài xuống tận đáy ly dầm thật mạnh cho đá bào tan ra hòa quyện cùng cốt dừa và các loại đậu thành hỗn hợp sánh ngậy mát lạnh, rồi hút một ngụm đã đời!","ja":"本場の食べ方作法：写真を撮ったら、長いスプーンを底まで差し込んで「親の仇のように」全体をガシガシ激しくかき混ぜます！氷とゼリーとあんこがココナッツミルクと混ざり合い、とろとろのシェイク状にしてストローで吸い上げるのがサイゴン流！","ko":"사이공 현지인 먹방 팁: 예쁜 층을 감상한 뒤 긴 스푼으로 바닥까지 푹 찔러넣고 얼음과 앙금, 코코넛 밀크를 마구 으깨어 섞어주세요! 시원하고 걸쭉한 밀크셰이크처럼 만들어 빨대로 쭉 들이켜면 천국의 맛입니다!"}]}];
